INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593260582', 'Berço Americano Tutto Freijó Branco Soft - Matic', 'Berço Americano Tutto Freijó Branco Soft - Matic Berço Americano Tutto Freijó Branco Soft - Matic Chegou a hora de escolher o berço do bebê, e procura por qualidade, conforto, modernidade e com preço baixo, aqui você encontra! Apresentamos o Berço Americano Tutto desenvolvido pela Matic com materiais de alta qualidade, e com um lindo design na cor Freijó Branco Soft. Não deixe de aproveitar, garanta já o seu! Características Técnicas: - Desenvolvido 100% em MDF - Pintura com sistema de tinta atóxica, que não tem cheiro e não faz mal a saúde do bebê - Na cor Freijó Branco Soft - Grade fixa para maior segurança - O estrado do colchão possui 03 níveis de altura podendo ser alterando conforme as fases de crescimento do bebê - Acompanha suporte para mosquiteiro - Padrão americano - Utiliza colchão americano padrão 70/130 (Vendido separadamente) - Possui função mini cama aumentando a vida útil do móvel - 04 Rodízios em gel sendo 02 com travas - Lindo design Dimensões: Altura: 101 cm Largura: 140 cm Profundidade: 83 cm Obs: Não realizamos a montagem, porém acompanha manual de instruções.', 816.06, 816.06, NULL, 'Mom & Baby > Nursery > Cribs & Cradles & Beds', 'https://cf.shopee.com.br/file/sg-11134201-7rdxz-lzp4ourexqw2c3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F22593260582', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
