INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894951121', 'Ola Bebê Lava Roupas Frasco', 'O lava-roupas Ola Bebê foi desenvolvido para cuidar das roupas do seu bebê, mantendo os tecidos como novos por muito mais tempo. Sua fórmula balanceada não agride as fibras e ainda deixa um cheirinho suave e relaxante. * Possui extratos naturais de Camomila e Erva-Doce * Dermatologicamente testado * Ideal para roupas finas e delicadas Modo de uso: * Para lavagem na máquina, dissolva 3 tampas de Ola na máquina já cheia de água, coloque as roupas e inicie a operação de lavagem no ciclo delicado ou normal e complete o enxágue. * Para lavagem manual, dissolva 1 tampa de Ola em 5 litros de água, coloque as roupas de molho de 5 a 20 minutos, lave as peças massageando-as levemente e, a seguir, enxágue-as bem em água limpa.', 30.49, 30.49, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-825b7-mqnekyd7mpz52f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554886%2F22894951121', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
