INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5246517766', 'Tônico para Fortalecimento de Cabelos Gota Dourada com Extrato de Alho 100ml', 'Legítimo Tônico para Fortalecimento De Cabelos Com Extrato de Alho Gota Dourada 100ml O Tônico para fortalecimento de cabelos Gota Dourada, foi desenvolvido com Óleo de Alho, Extrato de Alho, Extrato de Aloe Vera e Calêndula, que fortalecem a raiz enfraquecida, auxiliando no Combate `a queda, caspa, e excesso de oleosidade. Desodorizado Rende 9 aplicações PROVA DE TOQUE: Aplique uma pequena quantidade do produto no antebraço ou atrás da orelha e deixe-o agir por 45 minutos. Em seguida, lave o local e aguarde 24 horas. Caso apareça irritação, ardência ou coceiras na pele, o produto não deve ser utilizado. MODO DE USO: Faça a prova de toque. Aplicar 1 dose somente na raíz dos cabelos, deixe agir por no mínimo duas horas. Fazer o tratamento três vezes por semana, durante 3 meses. PRECAUÇÕES: Manter fora do alcance das crianças. Não ingerir. Em caso de contato com olhos, lavar abundantemente com água. Uso externo. COMPOSIÇÃO: Álcohol, Allium Sativum Extract, Calendula Offcinalis Extract, Aloe Barbadensis Extract, Parfum (Hexyl Cinnamal, D-Limonene, Coumarin), Cl 19140, Allium Sativum, Aqua (water).', 18.99, 18.99, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/c5f93aa218ce041e2703df225e1788d8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F5246517766', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697618581', 'Shampoo Fortalecedor Ervas Milenares Antiqueda Tio Nacho 415ml', 'O Shampoo Tio Nacho Ervas Milenares combina uma série de extratos de origens naturais, que nutrem e fortalecem a raiz do cabelo, limpando profundamente o folículo capilar e eliminando o excesso de oleosidade no couro cabeludo. Com seu poder de revigorar os fios, revitaliza o cabelo fraco em situações de queda, devido à quebra Modo de Uso Aplique o produto sobre o cabelo molhado, distribuindo generosamente fazendo uma leve massagem no couro cabeludo Enxágue Para melhores resultado repita a operação Benefícios Revitaliza o couro cabeludo Fortalece e regenera o cabelo Estimula o fio Hidrata, suaviza e dá brilho Oferece ação umectante e previne a queda do cabelo Regula a secreção sebácea', 44.9, 44.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rd4s-lx1k58ictqx21c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F22697618581', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
