INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699243041', 'Livro Fantoche Unicórnio - Ciranda Cultural', 'Livro Fantoche Unicórnio - Ciranda CulturalO Livro Fantoche Unicórnio da Ciranda Cultural é a escolha perfeita para estimular a criatividade e a imaginação dos pequenos. Com uma narrativa lúdica e envolvente, este livro encantador permite que as crianças mergulhem em aventuras mágicas ao lado de um adorável unicórnio. Idade recomendada: A partir de 4 anos. Selo Inmetro: 2334/2023. Diferenciais:Contém um fantoche de unicórnio que torna a leitura interativa e divertida. Incentiva o desenvolvimento cognitivo e emocional. Faz parte da coleção "Fantoches Divertidos" da Ciranda Cultural, conhecida por produzir livros educativos e cativantes. Excelente opção para estimular a criatividade e promover momentos de diversão em família. Mais sobre o Produto:O fantoche de unicórnio pode ser usado durante a leitura para as crianças darem vida ao personagem. A história envolvente incentiva a imaginação e a interação das crianças com o livro. Perfeito para ser utilizado em atividades de contação de histórias em casa, na escola ou em bibliotecas. Dicas de Uso:Utilize o fantoche de unicórnio para criar diferentes vozes e interpretações do personagem durante a leitura. Encoraje as crianças a participarem ativamente da história, fazendo perguntas e incentivando a imaginação. Promova sessões de contação de histórias com a presença do fantoche para tornar o momento ainda mais especial e divertido. Ficha Técnica:Nome do produto: Livro Fantoche Unicórnio; Marca: Ciranda Cultural; Idade recomendada: A partir de 4 anos; Selo Inmetro: 2334/2023; Contém: 1 livro com fantoche.', 33.99, 33.99, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rcdk-ltv6eq7mn9c70b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F19699243041', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55303126888', 'Cobertura Fracionada Chocolate Meio Amargo 1,01kg Cobertop', 'A Cobertura Cobertop Fracionada Meio Amargo em Gotas Produzida com matérias-primas selecionadas e rigoroso controle de qualidade, garante alto rendimento e resultados impecáveis em todas as preparações. Suas gotas são de fácil derretimento e não necessitam de têmpera, oferecendo praticidade e agilidade no manuseio. Com brilho intenso, textura cremosa e sabor marcante de chocolate meio amargo, é perfeita para coberturas, recheios, banhos de trufas, pães de mel, bombons e sobremesas em geral. Ideal para quem busca equilibrar o sabor do chocolate com um toque sofisticado de intensidade, proporciona acabamento profissional, aroma irresistível e desempenho superior em todas as receitas.! Ingredientes: Açúcar, gordura vegetal, cacau em pó, líquor de cacau, sal, aromatizante e emulsificantes INS-322(i) (Lecitina de Soja) e INS-476 (Poliglicerol Polirricinoleato). ALÉRGICOS: CONTÉM DERIVADOS DE SOJA. PODE CONTER LEITE. CONTÉM LACTOSE. NÃO CONTÉM GLÚTEN. INFORMAÇÃO NUTRICIONAL - Porção de 100g Valor Energético: 538kcal Carboidratos: 57g Açúcares Totais: 53g Açúcares Adicionados: 53g Proteínas: 3,4g Gorduras Totais: 33g Gorduras Saturadas: 30g Gorduras Trans: 0,3g Fibras Alimentares: 4,4g Sódio: 20mg', 63.32, 51.29, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-822z3-miadiood21af2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F55303126888', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
