INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11786155283', 'Mangá - Tokyo Ghoul: re - 03', 'Tokyo Ghoul: re - 03 Os ghouls se reuniram no local do ''leilão'' para vender e comprar humanos sequestrados. Com o objetivo de exterminar o maior número possível de ghouls procurados, o CCG dá início à operação ''Limpa-leilão'' com um grande contingente de oficiais. Haise e a equipe Quinx entram na batalha para capturar seu alvo principal, a ghoul ''Nut Cracker'', e se deparam com uma estranha figura que é chamada de ''Owl''. A imagem fugaz de um rosto conhecido enche Haise de tristeza e ele escuta uma ''voz'' em sua mente! Periodicidade: Especial - Reimpressão Formato: 13,7x20cm Tipo de Papel: Offset 90/Couché 90Tipo de Produto: RevistaSegmentos: MangásMarcas: Planet MangaAutor(es): Sui IshidaISBN: 978-85-426-1031-4Check-List: Janeiro/2021Classificação Etária: 18 anosGênero: Ação, Sobrenatural, TerrorEditora: Editora PaniniNúmero de páginas: 220Lombada/Encadernação: QuadradaTipo de capa: CartãoData de Lançamento: 11/01/2021Idioma: Português', 51.9, 51.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/a5a800d532407964ebebea687accad1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F11786155283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
