INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698321111', 'Shampoo Anticaspa Darrow Doctar Plus 240ml', 'O Shampoo Darrow Doctar Plus Doctar, a linha anticaspa N1º mais prescrita pelos dermatologistas. Doctar Plus Shampoo Dermatológico Anticaspa Intensivo é um tratamento com fórmula patenteada no combate à descamação severa. Proporciona resultados contra a caspa desde a 1ª aplicação. Testado dermatologicamente e comprovado cientificamente, Doctar Plus proporciona redução de 84% de caspas no 1º uso, tem 0% de sulfato e possui 87% de ingredientes naturais. É hipoalergênico e sem parabenos, corantes, petrolatos, silicones e sal (NaCl). Doctar Plus não resseca os fios e deixa uma sensação de frescor. Doctar Shampoo Dermatológico Anticaspa possui a maior eficácia terapêutica contra a caspa severa. Além de combater a descamação, a sua nova fórmula exclusiva protege a fibra capilar e promove uma redução da oleosidade sem agredir os fios. Benefícios: . Eficácia imediata contra: descamação, coceira, vermelhidão . -84% de caspas no 1º uso . Protege a fibra capilar . Não resseca os fios . Reduz a oleosidade . Deixa uma sensação de frescor . 0% de sulfato . 87% de ingredientes naturais . Sem silicone, parabenos, petrolatos e sal (NaCl) . Testado dermatologicamente e comprovado cientificamente . Cruelty Free - sem teste em animais', 169.33, 169.33, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rd5r-m77flii7auwi9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23698321111', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193168514', 'PICOLINATO DE CROMO ELABORE COM 60 CÁPSULAS', 'Picolinato de Cromo Elabore para que serve: - Suplemento com minerais que fortalece os cabelos, unhas, protege dos radicais livres e retarda o envelhecimento da pele.', 42.38, 42.38, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rd6g-lvvvomyrupmj66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F23193168514', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21398076143', 'Desodorante Corporal Body Splash Giovanna Baby Gold 260ml', 'Elaborada com nanopartículas de ouro, a Body Splash GOLD reúne propriedades estimulantes, revitalizantes e iluminadoras, proporcionando um irresistível aspecto dourado à pele com efeito iluminador. O mix olfativo provoca uma experiência sensorial única, mesclando notas frutais de amora, bergamota e pera com acordes de cassis, chantili, baunilha e marshmallow, transformando os sabores de nossa memória afetiva em uma fragrância suculenta e revigorante. A madeira de cashmere empresta uma tonalidade aveludada, moderna e abusada à composição. Leve e reluzente, pode ser reaplicada a qualquer momento do dia. Dermatologicamente testado.', 33.92, 33.92, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-7rd5q-m79mx16bw82r26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F21398076143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897567329', 'FIO DENTAL JOHNSON''S REACH COM 50M', 'O Fio Dental é um aliado essencial na sua rotina de higiene bucal, projetado para limpar e remover eficientemente placas bacterianas entre os dentes. Embora a escovação seja fundamental, ela não alcança todos os espaços, especialmente nas áreas interdentais, onde a placa pode se acumular e causar problemas como cáries e doenças gengivais. Com o uso regular do fio dental, você não apenas mantém a saúde bucal, mas também melhora o hálito e previne a formação de tártaro. Sua aplicação é simples e rápida, tornando-se um hábito fácil de incorporar ao dia a dia. Para melhores resultados, utilize o fio dental antes da escovação, garantindo que todos os resíduos alimentares e bactérias sejam removidos. Experimente diferentes tipos de fio dental, como cerados ou não cerados, para encontrar aquele que se adapta melhor às suas necessidades. Com o fio dental, você está investindo na sua saúde oral e mantendo seu sorriso radiante e saudável!', 40.34, 40.34, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd69-lvvuld4otwav5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F23897567329', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
