INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41662031917', 'Declaração de Fé das Assembleias de Deus para Crianças', 'Declaração de Fé das Assembleias de Deus para Crianças É com alegria e senso de missão cumprida que apresentamos a Declaração da Fé das Assembleias de Deus para Crianças — uma obra que traduz, com fidelidade e sensibilidade, os fundamentos da nossa fé em uma linguagem acessível aos pequenos. Em tempos em que ensinar a verdade é mais urgente do que nunca, este livro, inspirado nas Escrituras e em Provérbios 22.6, é um apoio precioso para pais, professores e líderes que desejam transmitir, com clareza e amor, a verdade da Palavra de Deus desde os primeiros anos. Fruto do compromisso da CGADB e da CPAD com a Educação Cristã, este material foi preparado com esmero para auxiliar na formação espiritual das novas gerações. Que Deus use este livro para fortalecer a fé das crianças e abençoar cada família. Faixa etária indicada: de 07 a 12 anos. Autor: Elias Torralbo Editora: Cpad Acabamento: Capa comum brochura Dimensões: 21 cm larg. x 25 cm alt. Número de páginas: 80', 30.9, 30.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdyb-md6d8no9c1fg60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F41662031917', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15319605288', 'Livro Graça Futura | John Piper', 'O propósito do pastor Piper ao escrever este livro é revitalizar o decadente cristianismo que só conhece a graça barata e a fé barata. Impregnado da Bíblia, embebido de Deus, profundamente evangélico e apaixonadamente humano, Piper preenche as dimensões esquecidas da fé — esperança e contentamento, estabilidade e santidade, a apreciação de Deus e o louvor a ele — com mão de mestre. Este é um livro rico e sábio, um livro para ser apreciado e relido. Detalhes do produto: Autor: John Piper Editora: Shedd Acabamento: Brochura Formato: 16 larg. X 23 alt. Número de Páginas: 384', 69.9, 69.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8262w-mksccw4hm5tu15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F15319605288', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21159166763', 'Kit com 2 Cremes Para Pentear Hidratação e Super Volumão + Gelatina #todecacho Super Definição Salon Line', 'O Kit Salon Line contém 1 Creme para Pentear Hidratação Profunda 1kg, 1 Creme para Pentear Super Volumão 1L e 1 Gelatina #todecacho Super Definição 1kg. Juntos, garantem finalização com hidratação, volume, definição e controle do frizz. INDICAÇÕES Para quais tipos de cabelo? Cabelos ondulados, cacheados e crespos. Qual a indicação? Cabelos desidratados, sem volume, sem definição e com frizz. Pode usar a partir de quantos anos? A Gelatina #todecacho Super Definição pode ser usada a partir de 03 anos, os demais produtos a partir de 12. ATIVOS Quais os principais ativos? Creme para Pentear Hidratação Profunda Óleo de coco: rico em vitaminas e ácidos graxos, fortalece os fios e proporciona brilho e maciez extrema. Babosa: também conhecido como aloe vera, o ativo possui vitaminas e sais minerais, garantindo hidratação e couro cabeludo saudável. D-pantenol: além de proteger o cabelo contra danos externos, fortalece o couro cabeludo e garante fios hidratados, brilhantes e ultramacios. Creme para Pentear Super Volumão Óleo de semente de melancia, D-Pantenol e óleo de argan: ajudam a proporcionar brilho intenso e revitalização capilar. Gelatina #todecacho Super Definição Possui babosa e D-pantenol em sua fórmula que garantem hidratação, maciez e brilho. Além disso, aliados à tecnologia PROFIX, proporcionam definição intensa, combate ao frizz e fixação duradoura. MODO DE USO Qual a melhor forma de usar? Com os cabelos limpos e úmidos, aplique qualquer um dos produtos mecha a mecha, uniformemente, no comprimento e pontas. Desembarace os fios com um pente de dentes largos e, em seguida, amasse-os iniciando o movimento das pontas até a raiz. Repita o movimento quantas vezes forem necessárias. A aplicação ideal dependerá da quantidade e do comprimento dos fios. Não enxágue. CARACTERÍSTICAS É produto vegano? Os produtos são veganos. É liberado? Apenas a Gelatina #todecacho Super Definição é liberada.', 123.0, 111.07, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-825a9-mfuq4ecu7too2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F21159166763', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393718224', 'Kit Shampoo e Condicionador SOS Cachos Kids Super Óleos', 'O Kit Shampoo e Condicionador SOS Cachos Kids Nutrição em Ação foram feitos para facilitar a rotina dos pais no cuidado dos cabelos das crianças. Trazendo uma limpeza capilar nutritiva que, além de deixar os cabelos mais sedosos e comportados, controlam o frizz e deixam os cachos definidos e com brilho intenso. <>INDICAÇÕES$& Para quais tipos de cabelo? Cacheados, Crespos e Ondulados. Qual a indicação? Cabelos secos, desidratados e com frizz. Pode usar a partir de quantos anos? De 3 a 12 anos. <>ATIVOS$& Quais os principais ativos? Shampoo e Condicionador SOS Cachos Kids Nutrição em Ação Manteiga de Karité: rica em ácidos graxos essenciais, promove nutrição capilar intensa, além de proporcionar cabelos brilhosos e macios. Óleo de Argan: com alto poder de nutrição, garante hidratação para cabelos secos e quebradiços, revitaliza e garante muito brilho. <>MODO DE USO$& Qual a melhor forma de usar? Shampoo SOS Cachos Kids Nutrição em Ação Aplique o Shampoo SOS Cachos Kids Nutrição em Ação uniformemente no cabelo molhado. Massageie suavemente até formar espuma. Enxágue. Condicionador SOS Cachos Kids Nutrição em Ação Após usar o Shampoo S.O.S Cachos Kids Nutrição em Ação, aplique o Condicionador S.O.S Cachos Kids Nutrição em Ação uniformemente no cabelo molhado. Massageie e deixe agir entre 1 e 3 minutos. Enxágue. <>CARACTERÍSTICAS$& É produto vegano? Todos os produtos são veganos. É liberado? Os produtos não são liberados.', 44.0, 44.0, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/sg-11134201-7rcf5-m6e3pvw28ivu13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F23393718224', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994952686', 'Lip Oil Tint Charm Brown Eudora Make Kiss Me 2ml', 'O Lip Oil Kiss Me Tint Charm Brown é a união entre beleza e acessórios, criado para quem valoriza conforto e as maiores tendências de maquiagem. Seguindo a tendência mundial Charmcore, possui charm exclusivo para compor diversos looks e você levar o seu tint colecionável para onde for! Possui textura oil confortável que desliza facilmente sobre os lábios e um efeito tint duradouro, mantendo lábios naturalmente pigmentados mesmo após a remoção do produto. Possui aplicador big brush que proporciona aplicação uniforme e fórmula multifuncional, que pode ser usada no rosto e nos lábios. Para completar essa experiência de estilo, o produto traz um pingente exclusivo (charm) altamente colecionável, permitindo que você personalize sua bolsa ou chaves e viva o conceito tint to go para retoques em qualquer ocasião! Quais os benefícios do Lip Oil Kiss Me Tint Charm? Efeito Tint duradouro que mantém a cor mesmo após a absorção do brilho;Textura Oil confortável que proporciona sensação de lábios hidratados com acabamento espelhado;Charm exclusivo incluso para você colecionar e usar como acessório de moda;Fórmula multifuncional que entrega versatilidade para lábios e bochechas. Leve seu Tint colecionável para onde for: O brilho que pigmenta e o estilo que te acompanha. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. Produto Vegano. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 69.99, 69.99, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-822yq-mo6ubcb6ht6r86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F23994952686', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
