INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293662627', 'Kit 3 Fraldas Turma Da Mônica Mega G - 96 Tiras', 'A Fralda Descartável Turma Da Mônica uniu proteção e conforto em uma nova opção de fralda. A fralda Turma da Mônica Baby possui a nova Tecnologia QuatroSec para que ele fique calmo, tranquilo e seguro durante o dia e a noite toda. Conta com um exclusivo sistema de canais que distribui mais rápido o xixi, barreiras anti-vazamento e uma fina camada extra que ajuda a manter o bebê sequinho por até 12 horas. Além disso possui cintura elástica que proporciona um ajuste perfeito no corpo. Benefícios: - Maior absorção; - Proteção por até 12hs; - Proteção contra vazamentos; - Tecnologia QuatroSec. Modo de uso: Coloque o bebê sobre a fralda aberta com as fitas na parte traseira. Em seguida, abra as fitas agarradinhas e ajuste a fralda no corpinho do bebê posicionando as fitas sobre a faixa frontal branca. Sobre a marca: A marca e sua turma estão presentes no coração dos brasileiros há mais de 3 gerações, e desde julho de 2021 faz parte da Ontex Brasil. Os novos produtos foram pensados e elaborados para as mamães e os papais que, assim como nós, valorizam a tradição e os valores culturais aprendidos na infância, alinhado com o conforto e a qualidade dos produtos Turma da Mônica para seu bebê.', 129.56, 105.9, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-824gk-mptibn31egi460', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F23293662627', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
