INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4975126579', 'Perfume Mister Caviar 100ml Paris Elysees', 'Uma fragrância sensual, magnética e sutil do cedro da china e lavanda, com uma estrutura suave e profunda ao mesmo tempo. E as madeiras exóticas e o incenso formam uma verdadeira bomba de sensualidade. Família Olfativa: Aromático e Amadeirado Notas de Cabeça: Tangerina, Limão e Notas Aromáticas Notas de Corpo: Noz Moscada e Cardamomo Notas de Fundo: Vetiver e Sândalo', 99.9, 78.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lt5ehupy94kf2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369057850%2F4975126579', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21997759592', 'Perfume Masculino PIACENZA PROFONDO Primacial', 'Sobre a fragrância Piacenza Profondo Mergulhe em uma jornada nas profundezas do mar com Piacenza Profondo. Inspirada pela profundidade misteriosa do mar mediterrâneo, esta fragrância Aromático Fougère convida você a explorar um universo de frescor elegante e liberdade. Piacenza Profondo é a escolha ideal para o homem contemporâneo que valoriza a elegância e busca uma fragrância que ecoa a grandiosidade do mundo natural, refletindo a masculinidade moderna. Piacenza Profondo é para o homem que busca uma expressão de elegância e uma conexão com a serenidade das águas. Ele é convicto de suas escolhas e exala um charme natural. Imerja nesta experiência com Piacenza Profondo 🔵 Fixação: Moderada, até 9 horas. 🔵 Projeção: Moderada, aproximadamente 1 metro. 🔵 Família olfativa: Aromático Fougère. Pirâmide olfativa do Piacenza Profondo 🔺 Topo: Notas Oceânicas, Bergamota e Mandarina Verde. 🔺 Coração: Alecrim, Cipreste, Lavanda e Lentisco. 🔺 Fundo: Notas Minerais, Almíscar, Patchouli ou Oriza e Âmbar. O que você sentirá no Piacenza Profondo Inicia-se com um frescor de notas oceânicas, bergamota e mandarina verde, seguido pela vivacidade de alecrim e lavanda. No fundo, almíscar e âmbar oferecem uma base sensual e sofisticada. Piacenza Profondo o transportará a uma jornada marítima profunda, elegante e envolvente. Ocasiões para usar o Piacenza Profondo Ideal para dias ensolarados e quentes de verão, oferecendo um frescor refinado que se destaca em ocasiões especiais. Seu aroma revigorante e sofisticado é perfeito para eventos onde você deseja uma presença distinta.', 89.0, 76.0, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lz7o64cuhvepc4', 'https://shope.ee/an_redir?origin_link=https%