INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297677598', 'Lapis Para Olhos Oceane Shine Eye Pencil 4You', 'Descrição: O Lapis Para Olhos Oceane Shine Eye Pencil 4You é perfeito para deixar o seu olhar com um toque delicado de cor! Sua fórmula vegana e cruelty free garante muita fixação, ainda conta com uma esponjinha na ponta para esfumar o produto. MODO DE USAR: 1 - Use toda a sua criatividade na hora de usar o Shine Eye Pencil. Para um delineado perfeito, passe o lápis rente aos cílios e garanta traços muito bem feitos. Use a esponjinha que vem em uma das pontas e crie o esfumado perfeito. 2 - Na linha d''água, ele dá um toque todo especial para o seu olhar. USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 01unidade. Composição: Dimethicone (Dimeticona), Synthetic Wax (Parafina), Mica (Mica), Trimethylsiloxysilicate (Trimetilsiloxissilicato), C20-24 Alkyl Dimethicone (C20-24 Alquil Dimeticona), Phenylpropyldimethylsiloxysilicate (Fenilpropildimetilsiloxisilicato), Phenoxyethanol (Fenoxietanol), Caprylyl Glycol (Caprililglicol), Tocopheryl Acetate (Acetato De Tocoferila), Ci77891 (Corante Branco 77891), Ci77492 (Corante Amarelo 77492), Ci77491 (Corante Vermelho 77491). #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 34.99, 34.99, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-7rdvs-lygy4vuk4ltg8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322432427%2F23297677598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210144677', 'Cerveja Heineken Barril 5L', 'O barril Heineken proporciona uma experiência única para você e seus amigos. Não pode ir a um bar? Então leve o bar até você. O barril Heineken conta com 5 litros da mais icônica cerveja Puro Malte. Heineken é uma cerveja lager Puro Malte, refrescante e de cor amarelo-dourado, produzida com ingredientes 100% naturais: água, malte e lúpulo. Durante o processo de fermentação da Heineken, a exclusiva Levedura A é responsável pelo sabor característico e bem equilibrado, com notas frutadas sutis. A cerveja é fabricada em tanques horizontais para mais sabor e consistência. É por isso que nenhuma outra cerveja tem o gosto de Heineken. Preparado para servir a cerveja perfeita? Seja em uma festa, churrasco ou para assistir um jogo de futebol, você pode servir seus convidados o copo perfeito de cerveja gelada!', 132.99, 108.99, NULL, 'Food & Beverages > Alcoholic Beverages > Beer & Cider', 'https://cf.shopee.com.br/file/sg-11134201-82586-mqnekp2sc07fb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554774%2F58210144677', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
