INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298009951', 'Caderno espiral capa dura cartografia milimetrado 96 folhas D Mais Feminino Tilibra', 'Pronto para deixar seu lado criativo à solta com o Caderno de Cartografia e Desenho Milimetrado Espiral Capa Dura D+ Feminino 96 Folhas da Tilibra. Este produto é a escolha certa para expressão criativa e o desenvolvimento de habilidades motoras. D+ oferece produtos com estampas versáteis, inspiradas em temáticas no momento. Planejada para atender aos mais diversos perfis e faixas etárias, a marca é a escolha perfeita para quem busca uma coleção versátil. Detalhes: - Capa: dura - Folhas: com escala milimétrica e sem pauta - Formato: 275mm x 200mm - Gramatura: 63 g/m² - Número de folhas: 96 folhas', 26.28, 26.28, NULL, 'Stationery > Notebooks & Papers > Notebooks & Notepads', 'https://cf.shopee.com.br/file/sg-11134201-824hu-mdyyv39ys0leb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F23298009951', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798800666', 'Óculos de Sol Feminino Chilli Beans Clássicos Quadrado Degradê Marrom', 'Coleção: Linha Clássicos Óculos de Sol Feminino Chilli Beans Clássicos Quadrado Degradê Marrom, as extremidades facetadas dá um charme ainda maior para a peça. Moldado em metal leve e de alta resistência. Lentes com proteção 100% contra raios UVA e UVB, protegendo seus olhos dos raios nocivos do sol, reduzindo o risco de desenvolvimento das doenças oculares. No shape frontal inserimos ponte metálica fina com apoio nasal em silicone de fácil ajuste. Hastes com assinatura da marca mais apimentada, Chilli Beans. A Linha Clássicos Chilli Beans, é um best-seller desenvolvida para agradar todos os gostos. Os Clássicos são ideais para quem preza por praticidade e peças únicas, com design clássico e atemporal, porém com aquele toque apimentado para você está sempre na moda. Na paleta de cores da Linha Clássicos, incluímos tons neutros, versáteis e cores da estação, tudo para dar um match com as peças do seu guarda-roupa. Ref.: OC.MT.3690.5702', 399.98, 399.98, NULL, 'Fashion Accessories > Eyewear > Sunglasses', 'https://cf.shopee.com.br/file/sg-11134201-8262x-mjtzmrxgx5vpea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356106526%2F22798800666', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42676855761', 'Base de Carregamento PS5 com Cooler e Gaveta para Jogos LED indicador', 'Base de Carregamento Multifuncional para Consoles PS5 foi desenvolvida para organizar, carregar e otimizar seu setup, oferecendo praticidade e eficiência no dia a dia. Conta com carregador duplo para controles, sistema de refrigeração integrado e gavetas para armazenamento de jogos, mantendo tudo no lugar com visual moderno. Possui proteção contra sobrecarga, superaquecimento, curto-circuito e sobre tensão, garantindo uso seguro. Com LEDs indicadores, oferece um carregamento estiloso e funcional, ideal para quem busca praticidade e organização no ambiente. ESPECIFICAÇÕES GERAIS: - Compatibilidade: PS5, PS5 Digital Edition, PS5 Slim, PS5 Pro - Carregamento: Carregador duplo para controles - Porta adicional: USB 2.0 - Armazenamento: 8 gavetas para jogos - Ventilação: Sistema de refrigeração eficiente e de baixo ruído - LEDs: Indicadores de carga - Segurança: Proteção contra sobrecarga, superaquecimento, sobre tensão e curto-circuito DIMENSÕES: - Largura: 255 mm - Comprimento: 268 mm DIFERENCIAIS: - Organização completa para o setup - Gavetas práticas para jogos - Carregamento estiloso com iluminação LED - Estrutura estável e multifuncional CONTEÚDO: - 01 Base de Carregamento Multifuncional', 209.5, 155.0, NULL, 'Gaming & Consoles > Console Accessories', 'https://cf.shopee.com.br/file/sg-11134201-8226f-mhlytri9gpvk26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F42676855761', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597164822', 'Fone De Ouvido Headphone On-ear P2 C/mic Dobrável', 'O design dobrável do fone de ouvido é acompanhado por almofadas auriculares acolchoadas, que proporcionam conforto durante longos períodos de uso. As hastes ajustáveis permitem que você personalize o ajuste do fone de ouvido de acordo com o tamanho da sua cabeça. Compatibilidade: Windows ( Todas as versões ), Mac, Linux, PS4, PS5, XBOX ONE E XBOX SERIES. Especificações: Proteção magnética: Ferrite Frequência de resposta: 20 ~ 20KHz Impedância: 32 Ohms Potência Máx: 100mW Plugue de 3,5mm Banhado a ouro Haste revestida para máximo conforto Dimensões: Diâmetro dos alto-falantes: 40mm Comprimento do cabo: 1,20m Plugue de 3,5mm Banhado a ouro Esse tipo de fone de ouvido é ideal para pessoas em movimento, que estão sempre em trânsito ou que desejam economizar espaço ao guardar o dispositivo quando não estiver em uso. A capacidade de dobrar os fones de ouvido torna-os portáteis e fáceis de transportar, sem ocupar muito espaço.', 50.0, 25.8, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134201-7rbm0-lowm96y3c8hq35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F23597164822', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
