INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22699054836', 'Multimídia Honda City 2015 A 2021 9" 2+64gb Quadcore Gps Bluetooth', '**VERIFIQUE NA FOTO 2 O PAINEL CORRETO DO SEU CARRO E SELECIONE-O ANTES DA COMPRA** Central Multimídia Android SOAUDIO 9 Polegadas – Modelo S964B Sobre Nós Desde 2007, somos especialistas em centrais multimídia automotivas, oferecendo produtos modernos, confiáveis e com o melhor custo-benefício. Diferenciais: Garantia de 12 meses Suporte técnico especializado Atendimento rápido e personalizado Produto de altíssima qualidade, testado e garantido. Especificações Técnicas: Tela: IPS 9” 1280x720dpi (toque capacitivo duplo vidro) Android: 15.0 Memória: 2GB RAM / 64GB Flash Processador: Quad Core RK3326 1.5GHz Bluetooth: 5.0 (50 Mbps) Wi-Fi: Dual Band 2.4G / 5.0G Som: 4x41W com DSP e Sub EQ Compatível com: CarPlay e Android Auto sem fio Aplicativos Instalados: GPS IGO 3D offline, Waze, Netflix, Spotify, YouTube, Google Maps, Chrome e Play Store. Funções Principais: Interface personalizável: opções de layout Logo da montadora ajustável Câmeras compatíveis: 480p e 720p Multitela: Divisão de tela para múltiplos apps Bluetooth Hands-Free: Ligações e música Ajuste de iluminação automática Reprodução multimídia: MP3, MP4, AVI, MKV e mais Rádio FM: Frequência 76–108 MHz Wi-Fi com antena integrada Conteúdo da Embalagem: Central Multimídia 9” Moldura do painel Chicote plug and play Câmera de ré + cabo Antena GPS Cabos USB e RCA Microfone Bluetooth **Suporte técnico pós-venda incluso.**', 1250.7, 1100.62, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-820m8-mqj5vsfcmz9f68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1613233738%2F22699054836', NULL, NULL, '2026-07-28T02:11:31.70845