INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19599090282', 'Lâmpadas LED 5W G9 Halopin 110V/220V, Branco Quente (Amarelo) Branco Frio (Branco) para arandelas luz bipino', '💡 Iluminação Eficiente e Personalizável! 💡 🌟 POTÊNCIA: 5W: Proporciona uma iluminação eficaz com baixo consumo de energia. 🔌 TENSÃO: 127 ou 220V: Versátil e compatível com diferentes sistemas elétricos. 💡 LUMENS: 280-320LM: Oferece uma ampla faixa de intensidade luminosa para atender às suas necessidades. 🎨 COR: Branco Frio (6500K) ou Branco Quente (3000K): Escolha entre o frescor do branco frio ou o aconchego do branco quente. 🔒 IP: 20: Adequada para uso em ambientes internos. 📏 TAMANHO: Ø16*50 mm: Compacta e versátil, perfeita para diversas aplicações. Personalize sua iluminação de acordo com suas preferências, escolhendo entre as opções de cor e tensão. Com um tamanho compacto, esta lâmpada se adapta facilmente a uma variedade de luminárias. Adquira já a sua Lâmpada de 5W e desfrute de uma iluminação eficiente e personalizável para seus espaços! 💫✨', 29.0, 20.99, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lo5jppg6xzd361', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979730489%2F19599090282', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
