INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593643351', 'Copo Life Gocase 880ml - Aço Inox, Tampa e Canudo Tritan, Isolamento a Vácuo, Bebidas Quente e Fria', 'Informações Com capacidade de 880ml, o Copo Life mantém sua bebida quente por até 6 hrs ou fria (com gelo) por até 40 hrs (880ml). Depois dessa, não tem espaço para café frio e suco quente, hein? Quanto mais fria/quente estiver a bebida, por mais tempo o Copo Life manterá a temperatura dela. P.S: Para uma bebida mais gelada, recomendamos utilizar gelo dentro do copo. Depois dessa novidade, a hora de combinar a estampa do copo com a estampa da mochila, lancheira, capinha e bolsa de viagem, é agora. O seu sonho se realizou! Informações relevantes: Alça lateral 6 horas bebida quente 40 horas com gelo (880ml) Alça: PP Tampa e Canudo: Tritan Parede dupla isolada a vácuo Corpo em Aço inoxidável 304 (aço inoxidável 18/8) Medidas: Capacidade: 880ml. Altura: - 880ml: 22,8cm (incluindo altura da tampa) Diâmetro: - 88ml: 8,6cm Litragem: 880ml Instruções de lavagem / cuidado: Os copos devem ser lavados à mão, evitando esponjas abrasivas e somente as tampas podem ser lavadas na máquina de lavar louças. Garantia do vendedor: 15 dias', 199.99, 129.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-7ra2d-m5383dkxfa0kba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442913304%2F23593643351', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19497761396', 'catnip erva gateira 72g no pote - oikos animal', '"conheça o catnip erva gateira 72g no pote da oikos animal! atrativo, antiestresse e atóxico, o catnip é a erva mais amada dos felinos! os gatos se sentem atraídos pela erva. você pode esfregar uma pequena porção nos brinquedos, arranhadores ou colocar dentro de almofadas onde seu gato mais gosta de ficar: ele vai te agradecer pelo mimo! além disso, ajuda a deixar os gatos mais tranquilos em visitas ao veterinário, viagens ou qualquer outro momento que ele precise entrar na caixa transportadora. é só esfregar um pouquinho da erva dentro da caixa. duração do efeito: cerca de 10 minutos. pode ser usado com gatos de todos os portes. leve diversão para o seu pet! medidas: comprimento: 8,5 cm | largura: 11 cm | altura: 8,5 cm"', 39.9, 32.9, NULL, 'Pets > Pet Food > Cat Treats', 'https://cf.shopee.com.br/file/sg-11134201-7rdwg-ly3u2bqtb4jc01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F19497761396', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
