INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9455856733', 'Loção Hidratante Corporal Perfumada Lolla Natu Charm', 'A loção hidratante perfumada Lolla vai perfumar e hidratar sua pele, pois possui em sua formulação água de coco que promove alta performance de hidratação com sensação imediata de maciez na pele, além de alta concentração de essência transformando-a em um perfume corporal de ação duradoura e fixação eficiente. É como se você estivesse passando em seu corpo um perfume sólido e não líquido, por isso a eficiência de perfumação é tão alta.', 49.9, 49.9, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/br-11134201-820ll-mqx7y12x7lz829', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F434200296%2F9455856733', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
