INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193897414', 'Suplemento Alimentar Suprabio Mulher c/ 60 Cápsulas', '*Produto Original* *Atenção:* Venda exclusiva para pessoa física. Pedidos com CNPJ serão cancelados. Suplemento Alimentar Suprabio Mulher c/ 60 Cápsulas Suprabio Mulher é um suplemento alimentar, desenvolvido com base nas necessidades nutricionais específicas das mulheres. Sua composição de nutrientes foi cuidadosamente escolhida de modo a complementar a ingestão de vitaminas e minerais, essenciais à saúde e o bem-estar feminino. Uma correta ingestão de nutrientes reflete diretamente na saúde da pele, unhas e cabelos. Suprabio Mulher complementa a alimentação diária e possui vitaminas que auxiliam no aproveitamento da energia dos alimentos. C/uma boa nutrição você poderá desenvolver melhor as suas atividades diárias. O consumo de Suprabio Mulher deve ser associado a uma alimentação equilibrada e hábitos de vida saudáveis. Sua composição de vitaminas e minerais foi selecionada dentro dos limites diários recomendados para uma boa saúde. Possui 21 nutrientes, sendo 13 vitaminas e 8 minerais, além de não conter glúten, ser zero valor energético e isento de açúcar. Disponível nas embalagens com 60 cápsulas. Experimente!', 42.9, 42.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7repe-m8klzrgqi7k0bc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F23193897414', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
