INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393871467', 'FortSkin Melasma 1000mg 60 Cápsulas - FORTLIFE', 'FortSkin Melasma 1000mg 60 Cápsulas - FORTLIFE Descrição FortSkin Melasma 1000mg 60 Cápsulas é um suplemento alimentar desenvolvido para auxiliar no tratamento do melasma e outras hiperpigmentações da pele. Sua fórmula exclusiva combina ingredientes que atuam de dentro para fora, promovendo uma pele mais uniforme e com tom homogêneo. Benefícios: Reduz manchas e uniformiza o tom da pele. Ajuda a controlar o melasma e outros tipos de hiperpigmentação. Protege contra os danos causados pela exposição solar. Modo de uso Tomar 2 (duas) cápsulas ao dia. Precauções Mantenha fora do alcance de crianças.Indicado para maiores de 19 anos. Cuidados com a conservação Conservar bem fechado, em temperatura ambiente, protegido da luz, umidade e calor intenso. Importante Decoração não inclusa. Imagens ilustrativas. Cores podem variar por luminosidade, monitor ou percepção. Dados fornecidos pelo fabricante/fornecedor', 97.99, 97.99, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rep3-m85me2u9g7ft26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F23393871467', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
