INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209452075', 'Removedor de Esmalte Seduction Zulu', 'O Removedor de Esmalte Seduction da Zulu remove o esmalte de forma rápida e eficaz, sem deixar as unhas esbranquiçadas, além de possuir um aroma agradável. Modo de uso: Umedecer um algodão com o removedor de esmalte Zulu seduction e aplicar nas unhas até remover totalmente o esmalte. Se necessário repetir a aplicação.', 9.79, 9.79, NULL, 'Health > Personal Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mqnelz1cwu0wd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555072%2F58209452075', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43461767513', 'Camiseta Masculina Atletico Goianiense Dragão Oficial ACG Original', 'A Dragão Premium lançou oficialmente a nova camisa titular do Atlético-GO. A camisa titular do Atlético Goianiense mantém padrão com faixa transversal, mas agora, mudando de lado, do ombro direito até o lado esquerdo da barra. Segundo o clube, a inversão da faixa remete à camisa de 1944, ano da conquista do primeiro título estadual. Sobre o corpo, é colocado um padrão, característicos do estilo Art Déco, tendência na época da fundação de Goiânia e perceptível em monumentos históricos da capital, como por exemplo, na fachada do Estádio Antônio Accioly. Na gola tem a nuca em preto e vermelho, mesma cor de detalhes nos punhos e na faixa transversal, e nas costas a frase “Dragão do Brasil". Garanta já a sua!', 269.9, 199.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgnqse901xjb51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F43461767513', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998696645', 'Tênis Fila Acd Classic Feminino Original', 'Cheio de estilo! O Tênis Fila Acd Classic é aposta certa para acompanhar as suas produções em qualquer ocasião. Confeccionado em couro e material têxtil, tem design do icônico Arcade Low. Esse tênis feminino é ideal para quem está sempre antenado com as maiores tendências do streetwear. Moderno e confortável, seu visual traz autenticidade em modelo que combina com qualquer look. O calçado conta com cabedal (parte superior do calçado) confeccionado em Nimbus com parte frontal em camurça, que proporciona durabilidade e conforto. A respirabilidade é garantida por perfuros nas regiões de maior transpiração do pé. Possui a inconfundível flag lateral, sobreposição de peças com acabamento pespontado, assinaturas Fila por todo o cabedal que atribuem originalidade ao modelo e palmilha macia em EVA com tecido forrado. O solado monocromático todo em borracha com aplicação de logo Fila Letter oferece maior resistência à abrasão e aderência ao solo. Garanta já o seu!', 429.9, 299.9, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820m3-mo9z7wia0miua6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F23998696645', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47512278993', 'Chinelo Kenner Ibiza Pro Feminino - Branco e Rosa', 'Desenvolvida especialmente para mulheres que não abrem mão do conforto, mas fazem questão de manter a personalidade em cada detalhe, esta sandália feminina casual de dedo une perfeitamente um design clássico à modernidade. O modelo destaca-se pelas suas tiras slim com acabamento texturizado e um sutil toque de brilho que agrega sofisticação ao visual do dia a dia. O grande charme do calçado fica por conta da entressola, que traz uma faixa em tom rosa vibrante para criar um contraste marcante e cheio de atitude com a base clara e o solado escuro. Além do estilo inconfundível, a peça entrega máxima segurança através de um solado com acabamento tratorado antiderrapante, garantindo excelente aderência e estabilidade a cada passo. Com uma palmilha macia e anatômica que acomoda os pés perfeitamente, ela é a escolha ideal para acompanhar sua rotina, curtir momentos de lazer nos dias mais quentes ou simplesmente relaxar com máxima leveza. Compre já! Tabela de medidas, aproximadamente: Tamanho (BR) Comprimento do Pé 34 22,5 cm 35 23,3 cm 36 24,0 cm 37 24,6 cm 38 25,3 cm 39 26,0 cm 40 26,6 cm Como saber sua numeração? Coloque o papel no chão: Apoie a folha de papel em uma superfície lisa e encoste a borda dela contra uma parede. Posicione o pé: Pise descalço em cima da folha, garantindo que o seu calcanhar esteja encostado firmemente na parede (sem apertar demais). Marque o dedão: Com a caneta em pé (na vertical, sem inclinar), faça um risco na folha exatamente onde termina o seu dedo mais longo (atenção: Em algumas pessoas, o segundo dedo é maior que o dedão). Meça a distância: Use a régua para medir em linha reta da borda da folha (onde estava o calcanhar) até a marcação que você fez. O resultado em centímetros é a medida do seu pé.', 149.9, 129.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-824hr-mpi77bcfka9u3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F47512278993', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
