INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209664931', 'Café Torrado e Moído Sul de Minas Gourmet 3 Corações', 'O Café Gourmet 3 Corações Sul de Minas é um convite aos apaixonados por café, oferecendo uma experiência única a cada xícara. Com grãos 100% arábica plantados nas regiões cafeeiras mais nobres do Brasil, este café torrado e moído proporciona sabores e aromas diferenciados. * Sabor: notas de castanha e amêndoas. * Aroma: intenso de frutas secas. * Acidez: média cítrica. Modo de Preparo: Use 5 a 6 colheres de sopa de café cheias para cada litro de água quente. Adoce somente na hora de servir. Para preservar o aroma e o sabor, guarde o pacote em um recipiente fechado.', 33.99, 25.99, NULL, 'Food & Beverages > Cooking Essentials > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zu0-mmkdzmiwh5vs89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554850%2F58209664931', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
