INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4546510608', 'Creme Facial Nutritivo Sensação Não Oleosa 100g Nivea', 'Creme Facial Nutritivo Sensação Não Oleosa 100g Nivea - 1 unidade O Creme Facial Nivea Cuidado Nutritivo foi desenvolvido para todos os tipos de pele, proporciona uma hidratação intensa, sem deixar a pele com aspecto oleoso. Sua fórmula leve de rápida absorção, contém hidro nutrientes que quando em contato com a pele, derretem, atingindo a camada mais profunda, promovendo nutrição intensiva. Além disso, possui Karité e Vitaminas, que juntos regulam o equilíbrio das células e protege da perda de umidade. Nivea Cuidado Nutritivo refresca e protege a pele, deixando-a macia e firme durante too o dia. Benefícios: - Nutrição intensa; - Livre de oleosidade; - Contém hidronutrientes; - Prepara a pele para a maquiagem; - Hidratação por até 24 horas; - Dermatologicamente testada. Modo de Usar: Com a pele limpa e seca, aplique o Creme Facial Nivea Cuidado Nutritivo sobre todo o rosto, massageando suavemente em movimentos circulares até a completa absorção do produto.', 39.99, 39.99, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/4e445b309eb8b9e5862256ad2a47bd6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F4546510608', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
