INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18898984782', 'Livro O Evangelho Revelado Nas Estrelas | André Coelho', 'Este livro apresenta uma acurada investigação sobre como Deus revelou no Céu a sua mensagem e o seu propósito nas 48 constelações mais antigas e conhecidas desde os primórdios da humanidade. Elas revelam os vestígios de uma mensagem que Deus colocou nas estrelas antes mesmo da criação do homem, necessária enquanto o Antigo Testamento ainda não tinha sido redigido. Porém, com a chegada das Escrituras, esse registro foi esquecido e seu sentido original pervertido. Com isso, as constelações passaram a ser associadas a mitologias pagãs e, finalmente, à astrologia. Mas a maneira como as figuras do Zodíaco foram distribuídas no Céu têm o objetivo revelar alguns dos eventos mais importantes da história, como a vinda do Messias e outros acontecimentos contidos nas Escrituras. A partir dessa perspectiva, podemos olhar para cima e ter a certeza de que o Deus de amor apresentou seu plano eterno antes mesmo que fôssemos abençoados com a lei e com a graça em Cristo Jesus. Isso porque ele não faz nada sem propósito e, como disse o salmista: “Os céus declaram a glória de Deus”! Em O evangelho revelado nas estrelas o autor nos leva a refletir sobre esses fatos extraordinários, registrados pela vontade divina no Céu, desfazendo as vãs especulações e subjetividades contidas na pseudociência astrológica.', 24.99, 24.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rblg-lm4pz5i4qjq263', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F18898984782', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099851726', 'Bola Futsal Topper Tech Fusion Slick Branco/laranja', 'A Bola Futsal Topper Tech Fusion Slick Branco/laranja, uma ótima opção para aperfeiçoar suas habilidades em treinos e jogo. Material resistente, o que significa menos tempo para se preparar e mais tempo para jogar. A bola também conta com cores vibrantes que auxiliam na visualização. Feita em TPU, a bola tem construção costurada à máquina, que oferece maior durabilidade. OBS: Por questões de segurança no transporte, a bola é enviada vazia, necessitando calibração. As Lojas Radan conta com 10 lojas físicas no Rio Grande do Sul, oferecendo esta e uma grande variedade de produtos e marcas de calçados e vestuário feminino, masculino, infantil e esportivo. Compre online com entrega rápida para todo o Brasil ou em uma de nossas lojas físicas, aproveitando nossa experiência e adquirindo produtos de qualidade. Aproveite! Produto de autenticidade garantida vendido pela Lojas Radan. A cor do produto nas fotos pode sofrer alteração em decorrência do uso do flash ou da configuração do seu monitor. Características: Indicado: Esportivo Tipo de Bola: Futsal Material: TPU Tecnologia: Fusion Circunferência: 60cm Diferencial:Cores vibrantes que auxiliam na visualização. Peso do produto: 413g', 119.89, 119.89, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-81zv9-mmunzgyohds3f7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577790116%2F19099851726', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
