INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498680910', 'Semi Eixo Lado Direito Para Honda Civic 1.8 / 2.0 16v 2011 Até 2016 Flex Automático', '>> PRODUTO ORIGINAL VOLDA VOCÊ ENCONTRA AQUI <<< ---------------------------------------------- SOMOS UMA EMPRESA 100% BRASILEIRA Especializada na venda de peças para carros Importados e peças para carros Nacionais. Buscamos sempre oferecer as melhores marcas, atendendo nossos clientes de forma rápida e com preço competitivo. Para isso, trabalhamos com os principais fabricantes de peças para carros Importados e Carros Nacionais. Todos os produtos são originais, novos na embalagem do fabricante e com garantia. Temos como compromisso atender à necessidade de cada cliente, oferecendo um portfólio diversificado, com peças para carros nacionais e importados, garantindo qualidade e satisfação do cliente, em todo o processo de compra em nossas unidades. PRODUTO: Semi eixo Para Honda Civic 1.8 / 2.0 16V Flex Automático 2001 até 2016 COMPATÍVEL COM VEÍCULOS > Carro: Honda Civic Motor: 1.8 16V Flex Automático Ano: 2011 2012 2013 2014 2015 2016 > Carro: Honda Civic Motor: 2.0 16V Flex Automático Ano: 2011 2012 2013 2014 2015 2016 INFORMAÇÕES ADICIONAIS • Marca: Volda • Produto Novo • Semi Eixo Lado Direito • Peso: 9,5 Kg • NCM: 87085099 • S/ABS ITENS INCLUSOS 01 UN Semi eixo COMPATÍVEL COM AS SEGUINTES REFERÊNCIAS SE087 - SEC10010 - DG80119 - NJH03895S - 44305TT4M010M1 - VT9606', 1220.32, 1220.32, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbi9yonqs0ag41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1023761037%2F22498680910', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51650316319', 'Hidratante Corporal Cheiro de Rica Karité 200ml Kokeshi', 'HIDRATANTE CORPORAL CHEIRO DE RICA KARITÉ 200ML KOKESHI Sua pele merece um cuidado luxuoso todos os dias. O Hidratante Corporal Cheiro de Rica nutre e hidrata profundamente, deixando um toque macio, iluminado e radiante. Sua textura cremosa e confortável desliza facilmente na pele, proporcionando absorção rápida sem aspecto pegajoso. A fórmula é enriquecida com Manteiga de Karité, Óleo de Coco, Vitamina E e Extratos de Arroz, Cereja e Romã, que suavizam o ressecamento e promovem uma pele mais uniforme e saudável. A experiência fica completa com sua fragrância sofisticada e envolvente: notas florais e frutadas de pera e groselha preta, combinadas à elegância de íris e jasmim, finalizadas por um fundo cremoso de baunilha e pralinê. MODO DE USAR: Aplique sobre a pele limpa e seca, massageando até sua completa absorção Use diariamente. ATIVOS: Manteiga de Karité, Óleo de Coco, Extrato de Arroz, Vitamina E BENEFÍCIOS: - Hidrata e Nutre a pele - Poporciona toque iluminador suave na pele - Fragrância Floral e Frutada - Dermatologicamente testado - Livre de Parabenos PRECAUÇÕES: Uso externo. Não ingerir. Evite contato com os olhos. Em caso de contato com os olhos, enxágue com água em abundância. Não aplique sobre a pele irritada ou lesionada. Suspenda o uso em caso de irritação e procure orientação médica. Mantenha fora do alcance de crianças. Conservar ao abrigo da luz e do calor. COMPOSIÇÃO: Água, Álcool Cetílico, Álcool Estearílico, Óleo De Coco, Parafina Líquida, Glicerol, Propileno Glicol, Fenoxietanol, Carbômer, Cetearete-20, Perfume, Peg-7 Cocoato De Gliceril, Petrolato, Imidazolidinilureia, Goma Xantana, Corante Branco 77019, Octinoxato, Trietanolamina, Álcool Laurílico, Edetato Dissódico, Álcool Miristílico, Corante Branco 77891, Salicilato De Benzila, Linalol, Alfa-Isometil Ionona, Limoneno, Hidroxicitronelal, Álcool Araquidílico, Cumarina, Corante Vermelho De Azorrubina, Citronelol, Caprilato De Poliglicerila-3, Manteiga De Karité, Acetato De Tocoferila, Extrato De Arroz, Extrato De Ginja, Extrato Da Casca De Romã.', 49.9, 39.92, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mge2mxyc2zgkfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F395166866%2F51650316319', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
