INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41468274173', 'Sérum Facial NIVEA Luminous630 Skin Glow 15ml', 'O Sérum Facial NIVEA Luminous630 Antimanchas 15ml é um tratamento avançado desenvolvido para reduzir visivelmente manchas escuras e uniformizar o tom da pele, revelando uma aparência mais luminosa e saudável. Sua fórmula exclusiva com LUMINOUS630, patenteada pela NIVEA após 10 anos de pesquisa, atua nas causas das manchas, ajudando a prevenir o reaparecimento. Benefícios: Reduz manchas visíveis em até 4 semanas* Uniformiza o tom da pele e melhora a luminosidade Textura leve e de rápida absorção Dermatologicamente testado e adequado para todos os tipos de pele Resultados comprovados com uso contínuo 💧 Modo de uso: Aplique algumas gotas do sérum diariamente, de manhã e à noite, sobre o rosto limpo antes do hidratante. Use protetor solar durante o dia para potencializar os resultados.', 62.9, 62.9, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfnb5uf0k268e9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F502619181%2F41468274173', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
