INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15020321147', 'Pulseira Bali Buzios em Prata 925', 'Pulseira Bali Búzios em Prata 925 Leveza, estilo e inspiração no mar em uma joia cheia de personalidade. A Pulseira Bali Búzios em Prata 925 é perfeita para quem busca um acessório delicado com um toque artesanal e sofisticado. Seu design traz o charme dos búzios com acabamento em estilo bali, criando uma peça moderna e atemporal. Detalhes da Pulseira Modelo: Bali Búzios Material: Prata 925 legítima Estilo: Delicado com acabamento artesanal Fecho: Tradicional com ajuste confortável Destaques da Joia Búzios detalhados com inspiração no oceano; Acabamento estilo bali com toque artesanal sofisticado; Produzida em Prata de Lei 925, garantindo brilho e durabilidade; Peça leve e confortável para o uso diário; Design versátil que combina com diferentes estilos; Excelente opção para presentear com significado e elegância. Cuidados com sua Joia Evite contato com perfumes, cremes e produtos químicos; Guarde em local seco e protegido da umidade; Limpe com flanela macia para manter o brilho da prata. A Pulseira Bali Búzios em Prata 925 é uma joia delicada e cheia de charme, perfeita para representar a conexão com o mar e o estilo livre da natureza. Uma peça especial da Aqua Joias, produzida com acabamento impecável e alta qualidade.', 446.3, 220.0, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjk9ma5d6c5fbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F15020321147', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
