INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194460010', 'RENOVADOR PLASTICOS E BORRACHAS 100G - LUXCAR', 'RENOVADOR DE PLASTICOS E BORRACHAS LUXCAR 100G 4770 O RENOVADOR DE PLÁSTICOS E BORRACHAS LUXCAR É UM PRODUTO ESPECIALMENTE FORMULADO PARA REVITALIZAR, PROMOVER BRILHO E PROTEGER TODAS AS SUPERFÍCIES PLÁSTICAS DO SEU VEÍCULO. SUA FÓRMULA EXCLUSIVA COMBINA ADITIVOS ESPECIAIS, POLÍMEROS E PROTETIVOS, RECONSTITUINDO A CAMADA PLÁSTICA E PROPORCIONANDO UM ACABAMENTO PERFEITO, COM BRILHO SECO E LIVRE DE POEIRA. É IDEAL PARA RENOVAR E PROTEGER UMA VARIEDADE DE SUPERFÍCIES, INCLUINDO PLÁSTICOS, BORRACHAS, VINIL, PARA-CHOQUES, PAINEL, MAÇANETAS, CAPAS DE RETROVISORES, ENTRE OUTROS. APÓS O TRATAMENTO COM O PRODUTO, AS SUPERFÍCIES PLÁSTICAS DO SEU CARRO FICAM PROTEGIDAS CONTRA OS DANOS CAUSADOS PELOS RAIOS SOLARES UV E PELA AÇÃO DO TEMPO. VANTAGENS: ALTO RENDIMENTO: UMA PEQUENA QUANTIDADE DO PRODUTO É SUFICIENTE PARA COBRIR UMA GRANDE ÁREA, GARANTINDO ECONOMIA. AÇÃO PROLONGADA: A FÓRMULA DO RENOVADOR DE PLÁSTICOS E BORRACHAS LUXCAR OFERECE UMA PROTEÇÃO DURADOURA, MANTENDO AS SUPERFÍCIES REVITALIZADAS POR MAIS TEMPO. BRILHO ORIGINAL: PROPORCIONA UM BRILHO INTENSO E DURADOURO, RESTAURANDO O ASPECTO ORIGINAL DAS SUPERFÍCIES PLÁSTICAS E BORRACHAS DO VEÍCULO. MODO DE USAR: CERTIFIQUE-SE DE QUE A SUPERFÍCIE ESTEJA LIMPA E SECA ANTES DA APLICAÇÃO. APLIQUE UMA PEQUENA QUANTIDADE DO PRODUTO NA ESPONJA FORNECIDA. ESPALHE O PRODUTO DE MANEIRA ECONÔMICA E UNIFORME SOBRE A SUPERFÍCIE, GARANTINDO UMA COBERTURA COMPLETA. CASO NECESSÁRIO, REMOVA O EXCESSO DE PRODUTO COM UM PANO DE MICROFIBRA LIMPO E SECO. SE A SUPERFÍCIE ESTIVER MUITO RESSECADA, REPITA A APLICAÇÃO PARA OBTER MELHORES RESULTADOS. VALIDADE: 24 MESES A PARTIR DA DATA DE FABRICAÇÃO. CONTEÚDO DA EMBALAGEM: 01 RENOVADOR DE PLÁSTICOS E BORRACHAS LUXCAR 100G 01 ESPONJA PARA APLICAÇÃO', 29.09, 29.09, NULL, 'Spare Parts and Accessories for Vehicles > Heavy Duty and Boats > Spare Parts for Heavy Duty Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-824g4-mfe5y7i66olref', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1414895408%2F23194460010', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
