INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10996166947', 'Livro Oração Eficaz (Nova Edição) C , H , Spurgeon', 'Oração Eficaz Através da vida de Jó aprendemos como ele almejava suplicar e interceder diante de Deus. Ele nos revela os segredos do seu íntimo e nos mostra a arte da oração. Aqui somos incorporados ao grêmio dos suplicantes; é-nos mostrado a arte e o mistério da súplica; aqui se nos ensina a abençoada ciência e habilidade da oração, e se nós nos tornarmos aprendizes de Jó, e se pudermos receber uma lição do seu Mestre, poderemos adquirir bastante habilidade para interceder diante de Deus. Título , Oração ,Eficaz Autor , C , ,H , ,Spurgeon Páginas , 40 Formato , 18 ,x ,12 ,x ,1 Capa , Brochura Peso , 0,50 ,g ISBN , 9788568026441 Editora , PES', 18.13, 18.13, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/3810fe4fc418f3c8d8c72de848d539b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F10996166947', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18407533106', 'Aqueles da Bíblia | André Daniel Reinke', 'Aqueles da Bíblia A formação do povo de Deus na perspectiva bíblica histórica e teológica Nossa leitura da Bíblia é profundamente influenciada pela maneira como imaginamos o passado Ciente disso o autor nos propõe uma nova imaginação dessa narrativa trazendo as pesquisas acadêmicas da arqueologia e da historiografia para compor o contexto de formação do Israel antigo André Daniel Reinke busca compreender esse povo na especificidade de cada época explicitando as muitas identidades tão belamente descritas nas páginas da Bíblia Por isso ele pergunta o que diferencia e o que aproxima o mesopotâmio Abraão do levita Moisés? Que relação continuidade cultural há entre o danita Sansão e o efraimita Samuel? Quais são as ligações deles com o judaíta Davi ou com o judeu Paulo? E com o galileu Jesus? Eles falavam a mesma língua? Como os antigos israelitas se relacionavam com as culturas vizinhas? Como era a compreensão de Deus em cada tempo?Essas são algumas questões exploradas em uma ampla pesquisa com pinceladas da história dos impérios e das influências políticas culturais e religiosas dos outros povos sobre Israel Entre assimilações e rupturas o povo narrado na Bíblia foi constituído em muitas identidades algumas desaparecidas na poeira do tempo outras vivas até os nossos dias No meio dessa história encarnada na realidade veio a revelação divina registrada no testemunho desse povo sobre a invasão de seu Deus na história Este livro é uma obra fundamental para que o leitor possa compreender melhor o contexto histórico cultural e religioso da formação do povo de Israel e da própria emergência da Bíblia Sagrada Título Aqueles da Bíblia Autor André Daniel Reinke Acabamento Brochura Páginas 416 Dimensôes Altura 23 cm x Largura 15 5 cm x Profundidade 2 cm Peso 540 g ISBN 9786556891750 Editora Thomas Nelson', 39.31, 39.31, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/acdfaefd51e0c8bc79b4744cb08ca32c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F18407533106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
