INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54308435657', 'Livro Meu mundo é uma bola', 'Quatro amigos e um sonho em comum: Ser jogador(a) de futebol. Em meio às dificuldades do dia a dia, às diferenças sociais e aos próprios sentimentos, eles descobrem que o esporte vai muito além de vencer ou perder; também é possível construir uma grande amizade. Editora: Ciranda Cultural Edição: 2, 2026 Autor: Regiane Alves, Liliane Mesquita Ilustrador: Janine Eufrásio Idioma: Português Páginas: 48 Dimensões: L 20.50 x A 27.50 x E 0.10 ISBN: 9786526129326 Coleção: Não se aplica Linha Editorial: Ciranda Cultural - Literatura infantil Faixa Etária: + 9 anos Assuntos (tags): Amigos, Copa do mundo, Disciplina, Escola, Comportamento, Família, Diversidade Cultural, Futebol, Fãs de futebol, História do futebol, Brincar, Esportes, Livro presente, Presente, Amizade, Copa, World Cup, Craques do futebol BISAC: Literatura Infantil / Literatura Infantil / Esportes e Recreação / Futebol Linha de Produto: Literatura infantil Encadernação: Brochura Acabamento: Laminação brilho Material: Papel', 49.9, 49.9, NULL, 'Books & Magazines > Books > Hobbies', 'https://cf.shopee.com.br/file/sg-11134201-81zwb-mmt8pthr1jie0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F54308435657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
