INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9167360318', 'Livro - As aventuras de Hans Staden - Capa comum - Ciranda Cultural', 'Cheia de conhecimento para compartilhar com seus netos, Dona Benta dessa vez escolheu uma história real para contar às crianças. Pedrinho e Narizinho estão empolgados para descobrir o desfecho das peripécias vividas pelo alemão Hans Staden em terras brasileiras nos anos de 1500. São arcos, flechas, tempestades e barcos para todos os lados. Poderá um europeu sobreviver em uma tribo indígena? Editora: Ciranda Cultural Edição: 1, 2019 Autor: Monteiro Lobato Idioma: Português Páginas: 80 Dimensões: L 15.50 x A 22.30 x E 0.70 ISBN: 9788538088912', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/fa75b95bf52c7d6ac3ddc7c1ddb3d1a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F9167360318', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594964330', 'Salgadinho Baconzitos Clássicos Pacote 36g', 'O Baconzitos Clássico é um ícone da saudade e do sabor. Com aquele gosto inconfundível de bacon defumado e a textura crocante que gruda na memória, ele é um dos salgadinhos mais queridos do Brasil — e não é à toa. Uma vez que você abre o pacote, é difícil parar. Leve, prático e no tamanho perfeito para matar aquela vontade de um petisco gostoso a qualquer hora do dia, o Baconzitos é aquele clássico que atravessa gerações sem perder o charme. Do lanche da escola ao happy hour com os amigos, ele sempre cai bem. Combinações perfeitas: Acompanhe com refrigerante ou cerveja gelada, sirva em tigelas para petiscar em grupo ou leve na bolsa para aquele lanche rápido onde estiver.', 4.99, 4.99, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/sg-11134201-820o1-mnyg05reswzm99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554859%2F22594964330', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494953480', 'Lasanha Sabor Quatro Queijos Sadia', 'A Lasanha Sadia 4 Queijos é perfeita para uma refeição rápida e saborosa, com 4 tipos diferentes de queijo: mussarela, parmesão, gorgonzola e provolone. * Modo de Preparo: 1. Remova totalmente a película plástica da bandeja. 2. Leve a lasanha congelada ao micro-ondas, forno elétrico ou a gás, conforme as indicações: Micro-ondas: 11min (potência alta). Forno elétrico: 45min (210°C). Forno a gás: 50min (200°C). Recomenda-se utilizar luvas térmicas ao retirar o produto do forno.', 21.79, 21.79, NULL, 'Food & Beverages > Fresh & Frozen Food > Others', 'https://cf.shopee.com.br/file/sg-11134201-825ag-mqnekuk6euizaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676552986%2F23494953480', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14493686798', 'Kit Chaves Catraca Reversível com 28 Peças Philips Torx Fenda Bits', 'Com o Kit de Chaves Catraca, você pode apertar ou afrouxar parafusos rapidamente, sem precisar reposicionar a ferramenta constantemente. O mecanismo de catraca interna garante maior precisão e menor esforço, reduzindo a fadiga nas mãos e braços e tornando seu trabalho mais seguro e rápido. Características do Produto: - Alta Resistência: Ferramentas fabricadas em aço de alta qualidade, garantindo durabilidade e desempenho. - Variedade de Soquetes: Inclui 12 soquetes sextavados (4mm a 14mm) para atender a diferentes necessidades. - Bits Versáteis: 14 modelos de bits, incluindo: Fenda, Phillips, Torx e Allen - Chave Catraca Reversível: Permite apertar ou afrouxar com agilidade. - Extensor de Aço Incluso: Perfeito para alcançar locais de difícil acesso. - Estojo Compacto: Armazene e transporte todas as ferramentas com praticidade. Conteúdo: 1x Chave Catraca Reversível 1x Estojo para Armazenamento 1x Extensor de Aço 14x Bits 12x Soquetes Sextavados', 140.0, 45.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8259q-mq23thpntsel06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F14493686798', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
