INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16786842965', 'Tinta Esmalte Sintético para Metais e Madeira Brasimob 225ml Escolha Sua Cor', 'Descrição: Produto formulado a base de resinas alquídicas e pigmentos, argas naturais e sintéticas, aditivos especiais, com teor reduzido de V.O.C. De fácil aplicação, proporciona ótimacobertura, aderência e rendimento com um resultado brilhante e resistente as intempéries Uso e Aplicações: Recomendado para acabamentos em ambientes internos e externos, sobre superfícies demadeiras e metais ferrosos. Diluente/Catálise: Exclusivamente com Aguarrás AG 10.00.100 ou querosene, na proporção de 20 a 30%Teor de Sólidos: Por Peso: 36 +/- 2% Formas de Aplicação: Revolver (Pressão de 40 a 50 libras), trincha, pincel ou roloDemão(s) recomendada(s):Aplicar 01 a 02 demãosEspessura seca por demão de 20 a 25 micronsSecagem (25ºC)Ao Toque: 08 horasAo Manuseio: 16 horasFinal: 72 horas -Instruções Gerais:Misturar com agitação constante até perfeita homogeneização, diluir o produtoexclusivamente com aguarrás AG 10.00.100 ou querosene, ajustando a viscosidade doproduto em função do equipamento de aplicação.A superfície a ser pintada deverá estar seca e isenta de contaminantes, como, poeira, graxa,óleo, respingos de solda, ferrugem, etc. Rendimento teórico:Densidade: 30 a 35 m2 /galão/demão 0,980 + / - 0,020 g/cm3 -Normas de Segurança: Produto Inflamável, manter embalagem fechada, fora do alcance de crianças, animais efontes de calor. Armazenar em local coberto, fresco, seco e ventilado.Não reutilizar embalagens. Evitar inalação dos vapores, não ingerir.Efetuar aplicação em ambiente ventilado, utilizando-se de todos os EPIs como máscara,óculos de segurança, luvas e outros tipos pertinentes ao produto.', 19.9, 15.99, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf49ufbybg1x6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557320114%2F16786842965', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
