INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093584219', 'Boneco Funko Pop! & Buddy Disney Moana 2 - Moana e Simea', 'Explore novas aventuras com o Boneco Funko Pop! Moana e Simea! Este incrível conjunto traz a destemida Moana, pronta para navegar pelo oceano, acompanhada da sua irmã mais nova Simea. Com detalhes encantadores e aproximadamente 10 centímetros e 5 centímetros de altura, essas figuras de vinil são perfeitas para colecionadores e fãs do universo Disney. Adicione esse duo à sua coleção e reviva os momentos mágicos da sequência de Moana. Não perca a chance de trazer a magia Disney para sua casa!', 219.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7rfgv-m3doeb8bxfqfc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F22093584219', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
