INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11982745349', 'Par Amortecedor Oleo Dianteiro Brasilia Fusca Kombi Cofap', 'Conteúdo: Par Amortecedor Oleo Dianteiro Marca: Cofap Ref: SB27003 Aplicação: VOLKSWAGEN BRASILIA 1973 | Todas as versões BRASILIA 1974 | Todas as versões BRASILIA 1975 | Todas as versões BRASILIA 1976 | Todas as versões BRASILIA 1977 | Todas as versões BRASILIA 1978 | Todas as versões BRASILIA 1979 | Todas as versões BRASILIA 1980 | Todas as versões BRASILIA 1981 | Todas as versões BRASILIA 1982 | Todas as versões FUSCA 1969 | 1300L | 1500 | 1600 FUSCA 1970 | 1300L | 1500 | 1600 FUSCA 1971 | 1300L | 1500 | 1600 FUSCA 1972 | 1300L | 1500 | 1600 FUSCA 1973 | 1300L | 1500 | 1600 FUSCA 1974 | 1300L | 1500 | 1600 FUSCA 1975 | 1300L | 1500 | 1600 FUSCA 1976 | 1300L | 1500 | 1600 FUSCA 1977 | 1300L | 1500 | 1600 FUSCA 1978 | 1300L | 1500 | 1600 FUSCA 1979 | 1300L | 1500 | 1600 FUSCA 1980 | 1300L | 1500 | 1600 FUSCA 1981 | 1300L | 1500 | 1600 FUSCA 1982 | 1300L | 1500 | 1600 FUSCA 1983 | 1300L | 1500 | 1600 FUSCA 1984 | 1300L | 1500 | 1600 FUSCA 1985 | 1300L | 1500 | 1600 FUSCA 1986 | 1300L | 1500 | 1600 FUSCA 1987 | 1300L | 1500 | 1600 FUSCA 1988 | 1300L | 1500 | 1600 FUSCA 1989 | 1300L | 1500 | 1600 FUSCA 1990 | 1300L | 1500 | 1600 FUSCA 1991 | 1300L | 1500 | 1600 FUSCA 1992 | 1300L | 1500 | 1600 FUSCA 1993 | 1300L | 1500 | 1600 FUSCA 1994 | 1300L | 1500 | 1600 FUSCA 1995 | 1300L | 1500 | 1600 FUSCA 1996 | 1300L | 1500 | 1600 TL 1970 | Todas as versões TL 1971 | Todas as versões TL 1972 | Todas as versões TL 1973 | Todas as versões TL 1974 | Todas as versões TL 1975 | Todas as versões TL 1976 | Todas as versões VARIANT 1970 | I VARIANT 1971 | I VARIANT 1972 | I VARIANT 1973 | I VARIANT 1974 | I VARIANT 1975 | I VARIANT 1976 | I VARIANT 1977 | I O QUE É E COMO FUNCIONA? O amortecedor é um componente do sistema de suspensão dos veículos destinado ao controle das oscilações da mola. Localizado na região inferior do veículo, é um elemento de ligação entre a suspensão e a carroceria, que controla os movimentos das molas, e faz com que a roda do veículo mantenha a aderência ao solo. QUANDO SUBSTITUIR? A estabilidade, conforto e segurança ficam diretamente comprometidos se os amortecedores não estiverem atuando corretamente. Isso é verificado pela dificuldade no controle do veículo em curvas, freadas, pulos descontrolados das rodas e desgaste prematuro (ou irregular) dos pneus e demais componentes da suspensão. É importante a verificação periódica dos amortecedores, bem como dos demais componentes da suspensão, sempre que o veículo passar por uma revisão.', 289.0, 289.0, NULL, 'Spare Parts and Accessories for Vehicles > Heavy Duty and Boats > Spare Parts for Heavy Duty Vehicles', 'https://cf.shopee.com.br/file/6b89458bf39c5b615b0afd1798c5f363', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F325589565%2F11982745349', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
