INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49112758406', 'Livro O acordo (Nova edição) - Capa Comum', 'O primeiro livro da série Amores Improváveis, que inspirou a primeira temporada da adaptação do Prime Video, agora com nova capa em brochura. Edição especial de tiragem limitada com lombada dupla. Estudiosa, objetiva e sempre sarcástica, Hannah Wells não tem tempo nem paciência para caras convencidos como Garrett Graham, o atleta mais popular da universidade. Tudo o que ela quer é focar em seu curso de música e deixar o passado dolorido para trás. Apesar de fazer o maior sucesso com o sexo oposto, Garrett só está interessado em se formar para finalmente começar sua promissora carreira de jogador de hóquei profissional, de preferência o mais longe possível de seu pai. Um simples acordo vai virar o mundo desses jovens de ponta cabeça. Aos poucos, eles vão descobrir que têm mais em comum do que imaginavam. Antes meros conhecidos, os dois se tornam cúmplices e até melhores amigos, capazes de apoiar um ao outro nos momentos mais difíceis. Quando um beijo inesperado revela uma química explosiva entre os dois, Garrett percebe que não pode mais ignorar os seus sentimentos por aquela garota encantadora, tão forte e ao mesmo tempo tão vulnerável. Mas como convencer a teimosa Hannah de que vale a pena se arriscar nesse romance? Contém tropes que amamos: Enemies-to-lovers Fake dating Proximidade forçada CONTEÚDO ADULTO', 58.41, 58.41, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-824j8-mpv2ppil93pe25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F49112758406', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
