INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41662643059', 'O idiota - Grupo Editorial Martin Claret', 'Um dos mais cultuados romances de Dostoiévski, “O idiota” narra a história do humanista e epilético Príncipe Míchkin, uma mistura de Cristo e Dom Quixote. A relação entre Míchkin, o mundano Rogójin e a bela Nastácia Filíppovna revelará ao leitor como em um mundo obcecado por dinheiro e poder, o sanatório parece ser o único lugar para um santo.', 102.49, 102.49, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rdwj-mddg45ir7by412', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F41662643059', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
