INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21199544429', 'Estojo Escolar Esportivo 20x6,5cm Flamengo Xeryus', 'O estojo Simples Flamengo Xeryus é a escolha ideal para quem busca organização e estilo, além de mostrar a sua paixão pelo time. Confeccionado em tecido de alta qualidade, este estojo apresenta um design moderno e funcional, perfeito para uso escolar ou no trabalho. Detalhes Especiais Puxadores Personalizados: Os puxadores de zíper são personalizados com um design exclusivo, oferecendo um toque único à mochila. Compartimentos Funcionais: Oferece espaço suficiente para armazenar e organizar seus materiais de forma prática. Material: Poliéster 900D alta qualidade. DIMENSÕES: - Largura: 20cm - Altura: 6.5cm - Comprimento: 5cm PESO: 500gr', 54.9, 54.9, NULL, 'Stationery > School & Office Equipment > Pencil Cases', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5n8ldw6kms012', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F572649927%2F21199544429', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26976951771', 'Garrafinha De Alumínio Canudo Animal Fun 400ml Buba', 'Garrafinha Infantil Alumínio Animal Fun 450mL – Buba | Diversão e Hidratação Segura para os Pequenos 🐻🦄 A Garrafinha Infantil Alumínio Animal Fun da Buba é a escolha perfeita para manter seu pequeno hidratado com estilo e segurança. Com capacidade para 450mL, ela é ideal para crianças a partir de 36 meses, tornando a hidratação ao longo do dia ainda mais divertida e atraente! Design Encantador e Divertido Com ilustrações fofas de animais, em verde e rosa, essa garrafinha transforma a hora da bebida em um momento encantador. Seu design lúdico e colorido cativa as crianças, tornando a tarefa de beber água ou sucos ainda mais divertida e estimulante. Material Seguro e Durável Fabricada com alumínio resistente e livre de BPA, a garrafinha garante segurança e saúde para os pequenos. Além disso, é leve e prática, tornando-se fácil de transportar para a escola, passeios ou atividades ao ar livre. Bico de Silicone e Sistema Anticólica A garrafinha vem equipada com bico de silicone com um único orifício, proporcionando facilidade no uso e evitando vazamentos. O sistema anticólica assegura uma alimentação confortável, sem preocupações com o desconforto. Praticidade no Dia a Dia A tampa com alça integrada facilita o transporte, permitindo que seu filho leve a garrafinha para todos os lugares com facilidade. Perfeita para passeios, atividades ao ar livre ou mesmo para a rotina diária, a Garrafinha Animal Fun é ideal para acompanhar a criança em todas as suas aventuras. Destaques: Design Animado e Colorido: Ilustrações de animais e cores vibrantes que tornam o momento da bebida mais divertido. Segurança: Livre de BPA, garantindo a saúde e bem-estar dos pequenos. Bico de Silicone: Fácil de usar e previne vazamentos, com sistema anticólica para maior conforto. Especificações: Capacidade: 450 mL Material: Alumínio resistente Bico: Silicone com único orifício Idade recomendada: A partir de 36 meses Cor: Verde e rosa com ilustrações de animais Cuidados e Conservação: Lavar com detergente neutro e uma esponja macia. Não utilizar em micro-ondas. Evitar o uso de produtos abrasivos que possam danificar o material. Transforme a rotina de hidratação do seu filho com a Garrafinha Infantil Alumínio Animal Fun da Buba! Uma escolha divertida, prática e segura para os pequenos se manterem hidratados durante o dia. Buba – Porque o conforto e a diversão podem caminhar juntos! 🌟', 99.0, 64.9, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/sg-11134201-7rcdg-m6hcvl3wurgy2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F572649927%2F26976951771', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
