INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993249952', 'Filtro Separador Racor Mercedes Benz 1944 Om457 2003 A 2005', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação 1944-S 2P (DIESEL) 2003 até 2005 1944-S 3-EIXOS 2P (DIESEL) 2003 até 2005 Conteúdo Da Embalagem > 1 Filtro Separador Tipo de Veículo para Caminhões Marca > Com uma ampla e inovadora linha de produtos a Mann-Filter, sempre primando um alto padrão de qualidade em seus produtos, atendendo assim a todas as exigências da montadoras. Contando com filtros de ar, óleo, combustível e cabine para todos os tipos de motores veículares é máquinas. O Produto A função do filtro separador de água do diesel é exatamente o que seu nome diz: retirar a água do diesel. “Ao impedir que esta água contamine o motor, evita-se a corrosão dentro do sistema e que se prejudique assim a injeção do diesel nele. Importante • Tempo de garantia - 3 meses • Imagem meramente ilustrativa • Valor unitário • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7893390801004 Código do Fabricante WK1060/4 >', 101.86, 101.86, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rdwl-lzks09xtv0503e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1340945235%2F22993249952', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23899442313', 'Teclado com Fio USB K120 Logitech', 'Conheça o teclado da Logitech e se surpreenda com a qualidade Gostou? Compartilhe Alta durabilidade para você Com o teclado com fio USB K120 Logitech preto, você vai usar seu computador com muito mais conforto. O produto tem teclas de perfil plano e silenciosas, conexão USB, versão em português e design resistente a derramamentos. Com caracteres bastante nítidos e brilhantes, esse teclado vai trazer toda a inspiração para você. Tudo com muita ergonomia e facilidade. Dê adeus àquele velho teclado O teclado com fio da Logitech possui teclas duráveis que resistem a até 10 milhões de pressionamentos, suportes inclináveis, fortes e ajustáveis. Além disso, você terá uma digitação agradável e um layout com teclas F em tamanho normal e teclado numérico. O teclado é super moderno e basta conectá-lo a uma porta USB, no computador de mesa, no laptop ou notebook, para começar a usar. Pontos Fortes Teclas duráveis Versão em português Suportes reclináveis Características: Conectividade: USB Tipos de Teclado: Com Fio Acessórios Inclusos do Teclado:1 Teclado Garantia do Fornecedor: 3 meses', 79.91, 79.91, NULL, 'Computers & Accessories > Keyboards & Mice > Keyboards', 'https://cf.shopee.com.br/file/sg-11134201-820n0-mnypyqvjpdl24f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443109642%2F23899442313', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
