INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23502192700', 'Balcão Cozinha Gabinete Pia 150 cm 3 Portas 1 Gaveta Veneza GW Multimóveis MP3740 Branco', 'O Balcão Cozinha Gabinete Pia 150 cm 3 Portas 1 Gaveta Veneza Multimóveis tem um excelente custo benefício e um amplo espaço interno. Produzido em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), pés retrô em polipropileno, que deixam o ambiente mais estiloso, puxadores em ABS e tampo em MDP 15mm com pintura de alta resistência. O balcão possui tampo removível (compatível com pia de 150 cm) e a gaveta pode ser montada de ambos os lados (direito ou esquerdo). Conteúdo da Embalagem: 1 (um) Balcão com tampo 150cm Kit ferragem Manual de montagem Dimensões do produto montado: Altura: 84cm | Largura: 150cm | Profundidade: 53cm (balcão com tampo) *Você pode consultar as medidas detalhadas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 579.9, 479.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7qvds-lhz4blcwqv960f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F23502192700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19677587243', 'Estante Escritório de Canto Multimóveis CR25067 Amêndoa/Branca', 'A Estante Escritório Multiuso com 2 Portas Mutimóveis é prática e cheia de estilo, se destaca em qualquer tipo de ambiente. Possui 2 portas, 5 prateleiras, estrutura em MDP, acabamento em pintura UV e parte em BP. Suas principais características são versatilidade, design contemporâneo, e linhas simétricas, trazendo elegância e harmonia no ambiente desejado. Conteúdo da Embalagem: Estante Manual de Montagem Kit Ferragem Dimensões do produto montado: Altura: 165,5cm | Largura: 65cm | Profundidade: 35,5cm *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 659.9, 599.99, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-7qvex-lf8dg4oa4cek13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F19677587243', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
