INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394221219', 'Conjunto de Sala de Jantar Analice 1,20 com 4 Cadeiras 100% MDF', 'A Sala de Jantar Analice 1,20 com 4 Cadeiras 100% MDF é a escolha perfeita para reunir família e amigos com estilo. Fabricado em 100% MDF de alta qualidade, combina design elegante e conforto. Acabamento: Pintura U.V. Touch com 7 camadas de proteção, garantindo proteção e beleza duradoura. Destaques: Fabricante: MH Móveis Dimensões Totais (Mesa): Altura 80 cm Largura 120 cm Profundidade 81 cm Dimensões Totais (Cadeiras): Altura 106 cm Largura 41 cm Profundidade 53 cm Garantia: 6 Meses Contra defeitos de Fabricação', 1472.5, 1457.78, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rdwc-mc889dlnxrds11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1573190120%2F23394221219', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17588440654', 'Cama Articulada Casal para Colchão 138 x 188 cm Multimóveis CR35034 Amendoa', 'A Cama Articulada Casal para Colchão 138 x 188 cm Multimóveis CR35034 foi produzida para agregar conforto e beleza em seu quarto! Possui estrutura em MDP, acabamento em pintura UV, sistema de articulação e trava, chave para segurança de uso fechada, e para completar, a cama suporta até 260kg. Além de ser um móvel prático e funcional, foi desenvolvida 100% de forma ecológica garantindo a vitalidade, resistência e durabilidade no ambiente. Conteúdo da Embalagem: Cama Articulada Casal Manual de Montagem Kit Ferragem Dimensões do produto montado: Altura: 198,5cm | Largura: 178,5cm | Profundidade: 57,2cm (fechada) - 193cm (aberta) *Tamanho máximo do colchão (L x A x P): 140,6 x 18 x 190cm *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 1429.9, 1219.99, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7reor-m90pi0ft0z8952', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F17588440654', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9395632088', 'Papete Infantil Menino Sandália Masculino Calce Fácil 15.02j', 'Papete é um modelinho clássico que sempre está presente na vida dos pequenos! Além da praticidade, é super confortável; ótima escolha para os aventureiros passarem dias longos com estilo e segurança que nossos calçados oferecem. Modelo 100% leve e confortável Encaixe perfeito dos pés Fácil fechamento Palmilha EVA macia Sola antiderrapante Tipo de Produto: Papete Ocasião/Estilo: Casual Material cabedal: Têxtil Material Interno: Têxtil Material da Sola: PVC Nós da Pópidi cuidamos com carinho da relação pré e pós-venda, afinal a satisfação de nossos clientes é muito importante para nós! Atendimento: Segunda à sexta: 07:00 às 18:00 Sábado: 09:00 às 13:00 TABELA DE MEDIDAS 28 ------------- 19,0cm 29 ------------- 19,5cm 30 ------------- 20,0cm 31 ------------- 20,5cm 32 ------------- 21,5cm 33 ------------- 22,0cm COMO MEDIR Coloque o pé em cima de uma folha de papel e risque em volta dele com um lápis ou caneta. Meça o comprimento do topo até a base do contorno e adicione 0,5 cm de folga. LIMPEZA E CONSERVAÇÃO Fácil de lavar e secar! Mas evite usar substâncias abrasivas como álcool, detergentes ou solventes nos calçados, usar produtos neutros. Nunca os deixe de molho ou lave na máquina. A secagem deve ser feita em temperatura ambiente e na sombra, nunca no sol ou em máquinas. SOBRE A EMPRESA Visão Estar em constante expansão e inovação, de uma forma consistente e arrojada. Missão Proporcionar o bem estar dos nossos clientes, satisfazendo-os em um ambiente agradável e cortês com produtos a preços justos e de qualidade. Valores Respeito, Dedicação, Conexão e Atitude. Boas compras e volte sempre!!!', 89.9, 79.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lf5euloxcqancc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318839552%2F9395632088', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
