INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10059266558', 'Alça Pro Tork Arrow Titan 125 / Fan 125 2000/08', 'A Alça Traseira Pro Tork TITAN 2000 A 2004 E FAN 125 2004 A 2008 serve para amarração de pequenos objetos e fixação dos ganchos do extensor. Desenvolvida com desenho ergonômico que proporciona conforto e segurança na qual o passageiro possa segurar-se. Especificações: - Modelo: Traseiro ; - Disponível nas cores: Cromado e Preto ; - Fabricado em Aço; - Marca: Pro Tork. Aplicação: - TITAN 2000 A 2004 E FAN 125 2004 A 2008. Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada; - O produto é pronto para instalação de acordo com o modelo da moto, e encaixa -se perfeitamente no lugar do original, não sendo necessário nenhum tipo de adaptação.', 84.11, 69.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lkpc9i1uxw43c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F10059266558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
