INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499176743', 'Magnético Compressor Mahle Fiat Palio, Uno Vivace, Mobi', 'Magnético do Compressor – Código 37434 Descrição do Produto: Magnético (embreagem eletromagnética) desenvolvido para compressores automotivos do modelo Mahle. Produto novo, de elevada qualidade, indicado para substituição em sistemas de ar-condicionado automotivo. Aplicações: Compatível com veículos equipados com o compressor Mahle nos seguintes exemplos: Fiat Uno Vivace / Way (a partir de 2010) Fiat Siena / Palio / Strada (modelos a partir de 2010) Fiat Mobi (a partir de 2016) Fiat Fiorino 1.4 (a partir de 2016) Especificações Técnicas: Tipo: Embreagem eletromagnética (magnético) para compressor Tensão: 12 V Produto novo, pronto para instalação Informações Importantes: Verifique o modelo do compressor instalado no veículo, pois a compatibilidade depende do modelo e da tensão. A instalação deve ser efetuada por profissional especializado em ar-condicionado automotivo para garantir funcionamento correto. Produto comercializado com nota fiscal e garantia conforme legislação vigente.', 99.9, 99.9, NULL, 'Spare Parts and Accessories for Vehicles > Heavy Duty and Boats > Spare Parts for Heavy Duty Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-821g8-mh0vrdpyxt6zcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1454843384%2F23499176743', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256680294', 'Suporte Microondas e Forno Elétrico Aéreo 60cm Itália Branco - Lumil', 'Suporte Microondas e Forno Elétrico Aéreo 60cm Itália Branco - Lumil Ideal para ambientes que pedem organização, este móvel contribui para uma Cozinha mais funcional, mantendo tudo acessível e bem distribuído. O Suporte Aéreo valoriza o espaço e facilita a rotina diária. Pensado para otimizar o uso vertical, acomoda Micro-ondas ou Forno Elétrico com segurança, ajudando a liberar a bancada e deixando o ambiente mais prático e visualmente leve. Produzido com estrutura firme e visual atual, garante resistência no uso diário e se adapta com facilidade a diferentes propostas de decoração, mantendo harmonia e elegância no conjunto. Com proposta versátil, este Armário de Cozinha atende quem busca equilíbrio entre utilidade e estética, contribuindo para um ambiente organizado, funcional e agradável no dia a dia. Dimensões do Produto Largura: 60 cm. Altura: 42 cm. Profundidade: 42 cm. Peso: 7 kg. Outras Medidas Espaço livre Forno ou Micro-ondas: 57 x 39 cm. Características do Produto Material da estrutura: MDP 15mm. Acabamento: Melamina BP. Escala de Brilho: Fosco. Peso Suportado: 16kg Distribuídos. Diferenciais: - Design moderno. - Estrutura em MDP de 15mm. - Suporte suspenso para forno elétrico ou micro-ondas. Sistema de Montagem: Parafusos. Manual de Montagem: Sim. Complexidade da Montagem: Baixa. Volumes: 1 Volume. Conteúdo da Embalagem: 1 Suporte Micro-ondas. Garantia do Fabricante: 90 dias contra defeito de fabricação. Montagem: Recomendamos que seja feita por um profissional. Recomendação de Limpeza: Utilize pano levemente úmido.', 119.77, 119.77, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-82629-mkske60hzrpdee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F375188138%2F58256680294', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294446657', 'Porta Escova e Pasta De Dentes - Vermelho', 'Deixe seu banheiro moderno e organizado com o Porta Escova e Pasta de Dentes. Produzido em ABS, conta com acabamento fosco que proporciona um visual arrojado à sua decoração e quatro opções de cores: preto, vermelho, bege e branco. Possui capacidade para 280ml e superfície interna lisa, tornando-o fácil de lavar e ideal para organizar suas escovas e pasta de dentes e até mesmo fio dental. Resistente, o Porta Escova e Pasta de Dentes é o que faltava para deixar seu banheiro mais bonito e prático.', 12.0, 12.0, NULL, 'Home & Living > Home Organizers > Others', 'https://cf.shopee.com.br/file/sg-11134201-824hi-mfbbkh4ekgsr6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F23294446657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
