INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20398029582', 'Par De Amortecedor Traseiro Megane Grand Tour 1.6 Cofap', 'PAR DE AMORTECEDOR TRASEIRO LINHA - RENAULT MEGANE GRAND TOUR 1.6 2.0 PRODUTO NOVO ORIGINAL COFAP COM NOTA FISCAL CARACTERÍSTICAS - Código do fabricante: GB48369 - Aplicação: Traseiro - Lado: Esquerdo / Direito - Modelo Turbogás: O amortecedor Turbogás da Cofap possui, além do óleo, um gás em seu interior, o que evita a formação de bolhas de ar (cavitação), comum em situações de solicitação extrema, que leva à perda de eficiência do amortecedor. Proporciona maior rendimento, conforto e estabilidade. APLICAÇÃO: MEGANE GRAND TOUR 2006 2007 2008 2009 2010 2011 2012 2013 ITENS INCLUSOS NA EMBALAGEM: 02 AMORTECEDORES TRASEIROS GB48369 GARANTIA DO PRODUTO - A troca ou desistência desse item pode ser feita em até 7 dias corridos a partir do recebimento do produto. - Os amortecedores possuem 2 ANOS de garantia contra defeito de fabricação diretamente com o fornecedor. Para a garantia, é importante manter o certificado de qualidade com o selo do código de barras (vide embalagem). ATENÇÃO - A EMPRESA não se responsabiliza pelo mau uso ou instalação indevida do produto, sempre recomendamos que a instalação seja feita por um profissional especializado. - Imagens meramente ilustrativa', 830.0, 747.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rcew-m6cui1zx0damfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442403193%2F20398029582', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
