INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28417996780', 'Fonte Para Xbox 360 E 1 Pino Bivolt Cabo De Energia Bivolt KP-W017', 'Fonte Para Xbox 360 E 1 Pino Bivolt Cabo De Energia Bivolt Esta fonte de alimentação para XBOX 360 Super Slim, fornece a energia necessária para que você possa continuar jogando em seu XBOX em qualquer lugar. A fonte é ideal para que você tenha mobilidade e transportar apenas o seu console e ter uma fonte em cada local, ou mesmo se você esquecer sua fonte na casa de um amigo por engano, você não precisa se preocupar. Agora você terá uma Fonte de alimentação alternativa. Esta fonte também é indicada para reposição, caso a fonte original de seu XBOX 360 Super Slim tenha sido danificada. Por ser Bivolt, ela elimina o uso de transformadores, podendo instalar em qualquer tomada 110 ou 220v, sem riscos. ESPECIFICAÇÕES: - LED indicador; - Potência: 115W; - Compatível com XIII60 E; - Comprimento do cabo: 80cm; - Bivolt 110V / 220V - Ac Adapter; - Dimensões: 17cm x 7,3cm x 5cm; - Tensão de entrada: 100 ~ 240V ~2A 47 - 63Hz; - Tensão de saída: 12V / 9.6 A + 5Vsb 1A. ITEM INCLUSO: +01 Fonte AC 100-240V 2A 47 - 63HZ +01 Cabo 3 pinos Xbox Model:360 E, Super Slim, Fat Pack Size:22 Quantity:1 Registration ID:16572-37-85663 Model Name:Fonte De Alimentação Manufacturer:Guangzhou Ehang Intelligent Technology Co. Warranty Duration:1 Month Warranty Type:Supplier Warranty', 95.0, 69.5, NULL, 'Gaming & Consoles > Console Machines > Xbox', 'https://cf.shopee.com.br/file/sg-11134201-7rbk1-m5lhshrq39eg38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F28417996780', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
