INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13454260597', 'Farol Milha Vectra 2000 2001 2002 2003 2004 2005', 'Código do produto: 63070 O farol de milha é uma peça essencial para visibilidade em vias noturnas ou em dias de neblina. Eles devem estar sempre em bom estado para maior segurança do motorista e seus ocupantes. Este item possui material de alta qualidade e resistência, composto com sua lente em vidro que deixa seu carro com aspecto diferenciado de todos os outros. Compatível com: Chevrolet - Vectra 2000 - Vectra 2001 - Vectra 2002 - Vectra 2003 - Vectra 2004 - Vectra 2005 Especificações Técnicas: - Lente Lisa - Material da Lente em vidro - Material da Carcaça em Plástico - Encaixe de lâmpada H3 ATENÇÃO Garantia - 3 Meses O valor anunciado referente a Unidade. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 91.37, 91.37, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/707cbdfc8945c0637702ecd237a55437', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F13454260597', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42059026231', 'Refil Shampoo Glicerina Suave Baruel Baby 210ml', 'Refil Shampoo Glicerina Suave Baruel Baby 210ml Principais Características: • Fórmula com glicerina vegetal, que limpa suavemente sem agredir o couro cabeludo delicado do bebê. • Textura leve e fácil de enxaguar, proporcionando praticidade no uso diário. • Embalagem em formato refil, ideal para reposição e consumo mais sustentável. Benefícios: • Hidrata e protege os fios desde o primeiro uso. • Ajuda a manter o equilíbrio natural da pele e do couro cabeludo. • Proporciona maciez e brilho aos cabelos do bebê. • Econômico e ecológico, contribui para a redução de resíduos plásticos. Diferenciais do Produto: • pH balanceado e dermatologicamente testado, garantindo segurança e suavidade. • Indicado para uso diário desde os primeiros meses de vida. • Livre de corantes, álcool e parabenos, ideal para peles sensíveis. • Embalagem prática, que permite recarregar frascos tradicionais com facilidade. Especificações Técnicas: • Peso: 210 ml. Instruções de Uso: • Aplique uma pequena quantidade nos cabelos molhados do bebê. • Massageie delicadamente até formar espuma. • Enxágue bem com água morna. • Pode ser usado diariamente. Avisos e Precauções: • Uso externo. • Evite contato com os olhos. Em caso de contato, enxágue abundantemente. • Mantenha fora do alcance de crianças quando não estiver em uso. O que está incluso? • 1 unidade de Refil Shampoo Glicerina Suave Baruel Baby 210ml ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 20.79, 15.79, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcm8gs9e2eblee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F42059026231', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
