INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29191022708', 'Kit Pastilhas de Freio P/ Royal Enfield Super Meteor 650 Cobreq', 'Kit Pastilhas de Freio - Cobreq Racing ( Semimetálica ) Pastilha da melhor qualidade para frenagem da sua moto, testado e aprovado por laboratórios de qualidade! Não vai te deixar sem freio! A linha Racing da Cobreq é projetada para motocicletas acima de 500 cc que exigem alto desempenho na frenagem. Ideal para uso esportivo e de alta performance, com menor desgaste das pastilhas e dos discos, mesmo sob altas temperaturas. Aplicação Dianteira e Traseira ROYAL ENFIELD: SUPER METEOR 650 Todos os Anos Conteúdo da Embalagem: 01 Par de Pastilhas de Freio Dianteira Cobreq Racing (Semimetálica) 01 Par de Pastilhas de Freio Traseira Cobreq Racing (Semimetálica) Código Original (OEM) da Pastilha Dianteira: 5VK-W0045-00 / 06455 MAK 000 Código Original (OEM) da Pastilha Traseira: 34 21 2 314 947 / 2GS-W0045-00 / 5US-W0045-00 Especificações Técnicas: – Linha Racing – Pastilha Semimetálica (fibra de aramida e kevlar) – Não contém amianto – Alta performance e durabilidade – Rápida resposta de frenagem – Baixo nível de ruído – Maior dissipação de calor – Compatível com medidas originais – Segurança aprimorada mesmo em uso extremo – Testada em ambientes como Moto GP, Superbike, Stock Car e F-Truck Especialmente projetada para motocicletas a partir de 500 CC, que exigem um melhor poder de frenagem devido as altas temperaturas, com menor desgaste das pastilhas e dos discos de freios Importante !! Verifique, antes da compra, se as medidas das pastilhas são compatíveis com a da sua moto. Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 199.9, 179.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis',