INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18998011669', 'Agenda 2025 claquete roteiro do ano - Imaginarium', 'Luz, câmera, agenda! É isso mesmo, com a nossa Agenda 2025 Claquete Roteiro do Ano, você vai poder dirigir, ou melhor, anotar seus compromissos e se sentir como um verdadeiro diretor de cinema! Super presenteável e apresentando um design mega criativo, ela imita uma claquete e é toda em capa dura, contando com: 142 folhas; capa de proteção; divisórias com calendário entre os meses; tabelas mensais de controle financeiro; organizador mensal; folhas pautadas e datadas; páginas para anotações (ao final de cada mês). Com ela, uma coisa é certa, sua rotina vai virar roteiro de filme! Contém 1 agenda. Dimensões: 18,5 cm x 13,3 cm x 2,3 cm. Material: Papel. Possui 142 folhas com gramatura de 100 g/m² cada. Limpar com pano seco. Teme químicos e abrasivos. Validade indeterminada.', 125.0, 125.0, NULL, 'Stationery > Notebooks & Papers > Notebooks & Notepads', 'https://cf.shopee.com.br/file/sg-11134201-7ra14-m4ru1lm01xjvb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F789092088%2F18998011669', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
