INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23899186423', 'Lancheira Menina Infantil Shine Like the Stars 4734360', 'Lancheira Infantil Republic Vix - Shine Like the Stars 4734360 A Lancheira Infantil Republic Vix Shine Like the Stars 4734360 é ideal para acompanhar as meninas no dia a dia escolar com muito estilo e praticidade. Com design encantador, traz fundo rosa com estampa de estrelas coloridas e painel frontal turquesa brilhante com a frase inspiradora ?Shine Like the Stars?. Além do visual moderno, conta com chaveiro de estrela em lantejoulas que dá um toque especial ao acessório. Produzida em Nylon600D, material resistente e fácil de limpar, a lancheira possui compartimento térmico interno para conservar os alimentos, bolsos laterais em tela para garrafinhas e alça tiracolo regulável que proporciona mais praticidade no transporte. É a escolha perfeita para garantir organização e charme na rotina escolar. Medidas Aproximadas Altura: 21 cm Largura: 14 cm Comprimento: 22 cm Polegadas: 9.0" Material: Nylon600D Cuidados com o Produto Guardar em local seco e arejado. Limpar com pano úmido e sabão neutro; não utilizar solventes ou abrasivos. Evitar objetos cortantes no interior para preservar o material. Não submergir em água.', 118.9, 118.9, NULL, 'Travel & Luggage > Travel Bags > Others', 'https://cf.shopee.com.br/file/sg-11134201-822yd-mi0mge1m2cxse2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1690020804%2F23899186423', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
