INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23896677556', 'Bola Beach Soccer Pro Xxiii', 'Levante a bola e marque um golaço de bicicleta com a Bola Beach Soccer Pro XXIII. Seu design e nova cor proporcionam qualidade na visualização até mesmo em partidas noturnas. A bola é ideal para partidas em areia batida, permitindo melhor contato durante os passes e chutes de alta potência. Seus grandes diferenciais são o conforto e maciez, permitindo que você possa aproveitar a partida da melhor maneira possível sem deixar marcas avermelhadas no pé. Feita exclusivamente para craques que gostam de produtos com qualidade, a Beach Soccer Pro é ideal para você marcar um golaço e ser o rei das areias. Benefícios: Maior controle da bola. Maciez e conforto durante os passes e chutes. Equilíbrio para domínios e cabeceios certeiros. Alguns diferenciaistécnicos: A Bola Beach Soccer Pro XXIII conta com a tecnologia Termotec, garantindo 0% de absorção de água e mantendo as propriedades develocidade e peso da bola. O produto conta com a câmara Airbility 6D proporcionando precisão total e controle absoluto durante os domínios e os toques.', 399.99, 399.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh971pvsyqrred', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F23896677556', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
