INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598322515', 'PULSEIRA DE ACO 20MM COM TRAVA MANUAL - VARIAÇÃO CORES', 'Bem - Vindo(a) à At4u - Loja Oficial do Mercado Livre! Pulseira de Aço Milanese com Fecho Magnético para Relógio 20mm As pulseiras de aço com fecho magnético trazem mais estilo e sofisticação em cada detalhe. Fabricada com aço de alta qualidade, a pulseira proporciona um toque suave e confortável ao pulso. É a escolha perfeita para quem busca versatilidade e estilo em todas as ocasiões. Possui um fecho magnético, permitindo assim um ajuste perfeito para todos os tamanhos de pulsos. Desfrute da praticidade e da segurança, permitindo que você use seu dispositivo com confiança. Especificações: - Material: Aço; - Fecho: Magnético; - Conectores: Pinos de engate rápido; - Comprimento: 21,5 cm; - Largura: 2 cm; *Não acompanha o relógio *Pode haver alteração na tonalidade das pulseiras* Conteúdo da Embalagem: - 01 Pulseira de aço com fecho magnético para relógio 20mm - 02 Pinos para engate IMPORTANTE: * Postagem em até 24h. * Entrega Garantida. * COMPRE COM SEGURANÇA. * Tire suas dúvidas via chat com nossos especialistas.', 18.86, 18.86, NULL, 'Watches > Watches Accessories > Straps', 'https://cf.shopee.com.br/file/sg-11134201-7rd4w-m7hz14hqlgc162', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349249646%2F23598322515', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
