INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42262010912', 'Pulverizador Costal Elétrico 20 Litros - Importway', 'O Pulverizador Costal a Bateria da Importway é indicado para o combate a focos de mosquitos, pernilongos, baratas e também, na sanitização de ambientes e na umidificação de plantas e jardins. Esse produto pode ser utilizado para pulverização de inseticidas, herbicidas, pesticidas, fungicidas, carrapaticidas e adubos foliares. Muito prático, possui motor elétrico a bateria, que proporciona conforto ao operador, pois o mesmo não necessita realizar o bombeamento manual, mantendo o volume de aplicação uniforme. CARACTERÍSTICAS: - Marca: Importway - Peso: 6 Kg - Material do bico: Plástico Reforçado - Altura x Largura x Comprimento: 46 cm x 17 cm x 39 cm - Material do corpo: Plástico Reforçado - Modelo: IWPE20-020 - Pressão: 0,15 a 0,4 MPa - Capacidade: 20 Litros - Carregador Bivolt: 127v / 220v - Bateria: 12v 8ah - Consumo: 0,3 kwh - Pulveriza 400 a 480kg de líquido após carregamento completo - Bomba: Mini Bomba De Diafragma - Possui 3 bicos: Pulverização Setorial, Pulverização Cônica e Pulverização Ajustável.', 259.99, 259.99, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md603sdza3gh25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F42262010912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4085427317', 'Luminária Piscina RGB 9W 80MM', 'A luminária LED para piscina é ideal para proporcionar iluminação eficiente e segura em ambientes submersos. Com design compacto e alta vedação, é indicada para piscinas, fontes e áreas externas, garantindo excelente desempenho mesmo em contato direto com a água. CARACTERÍSTICAS: - Tensão: 12Vcc - Ângulo de abertura dos LEDs de 120° - À prova d''água (IP68 - uso submerso) - Foi desenvolvida cuidadosamente com materiais de qualidade para garantir alta proteção contra intempéries (cloro, sol, maresia, etc) - Material: PC - CORPO 80mm - Fixado através de rosca 1/2 BSP cônica.', 73.99, 73.99, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/744d7fea8968e0f73ba9fab3d057235a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F4085427317', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794640956', 'Xtreme Mol Protelim 5l Detergente Desengraxante Neutro', 'DETERGENTE DESENGRAXANTE XTREME MOL 5 Litros PROTELIM Ação do Xtreme Mol: Xtreme Mol foi especialmente desenvolvido para situações extremas de lavagens, como Moto Cross, Carros Off Road, Caminhões, Ônibus e Barcos. Indicado também para remoção de graxas, molduras, limpeza de pisos, paredes, máquinas agrícolas e superfícies pintadas em geral. Sua fórmula balanceada contém tensoativos biodegradáveis e sequestrantes que facilitam a remoção de sujidades mais difíceis. DILUIÇÃO: 1:10 até 1:120 MODO DE USAR 1 - Dilua o produto de acordo com as instruções abaixo: Limpeza pesada – 1 parte do produto para até 10 partes de água. Limpeza média – 1 parte do produto para até 50 partes de água. Limpeza leve – 1 parte do produto para até 120 partes de água. Snow foam – 100 ml do produto para 900 ml de água. 2 - Aplique o detergente desengraxante automotivo XTreme Mol sob a superfície a ser lavada manualmente ou por meio de máquina. 3 - Esfregue com pano ou esponja. 4 - Enxágue com água em abundância. IMPORTANTE: As diluições citadas são apenas orientativas, podendo ser alteradas. Utilize Equipamento de Proteção Individual (EPIs). Conteúdo: 5L Benefícios: Fórmula balanceada Alta diluição Alto poder de espuma Não mancha plásticos, borrachas e alumínios Livre de corrosão Não danifica a pintura Contém Tensoativos Biodegradáveis', 89.9, 89.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-821ev-mh6lic179f629a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F735686176%2F23794640956', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
