INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44158896912', 'Bíblia Sagrada | NVT | Jesus Saves', 'Bíblia Sagrada | NVT | Jesus Saves Bíblia NVT facilita a compreensão dos ensinos da Palavra. Para tornar a leitura da Bíblia Sagrada ainda mais atraente, com uma linguagem que permite entendermos melhor ainda os ensinamentos da Palavra de Deus, a Bíblia Nova Versão Transformadora (NVT) traz uma nova abordagem dos versículos. Traduzida por um grupo de profissionais especializados na linguagem dos textos bíblicos originais, que foram escritos em hebraico, aramaico e grego, a Bíblia NVT traz uma linguagem de fácil compreensão, numa abordagem contemporânea da língua portuguesa. Referência entre os cristãos que leem e estudam a Palavra, a Bíblia NVT nos permite assimilar com mais sabedoria o que Deus nos ensina e, assim, sermos sábios e prudentes nos desviando do mal em nosso caminho. Editora: Publicações Cordeiro Acabamento: Capa comum brochura Dimensões: 14 cm larg. x 21 cm alt. Número de páginas: 796', 19.99, 19.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdyk-mcb86zw53re9c0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F44158896912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
