INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25991351600', 'Bíblia Todo Dia com Espaço para Anotações | AM | Letra Grande| Capa Dura Botânica', 'Bíblia Todo Dia com Espaço para Anotações | AM | Letra Grande| Capa Dura Botânica A Bíblia Todo Dia é um convite ao estudo criativo, agradável e profundo das Escrituras. Você poderá usá-la como desejar, pois foi projetada para que a leitura se adapte às suas necessidades. Inovadora, você encontrará, para cada dia, porções do Antigo Testamento, do Novo Testamento e de Salmos, além de um espaço para anotações ou imagens, de acordo com a sua criatividade. Você nunca leu a Bíblia assim antes! O seu relacionamento com o Senhor certamente se aprofundará, e a Bíblia Todo Dia será a sua melhor companheira nesta jornada! Desfrute com alegria seu tempo com o Senhor e sua Palavra! Editora: Vida Acabamento: Capa Dura Dimensões: 16 cm larg. x 24 cm alt. Número de páginas: 1210', 145.92, 145.92, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rcdf-m65n3sqnpv144f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F25991351600', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
