INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28550794167', 'HINCE Mood Enhancer Water Liquid Glow (12 núcleos)', '🌿 Características do Produto Textura creme de água: Leve e hidratante, aplica suavemente sem viscosidade e adere confortavelmente aos lábios. Pagamento de cores claras e vibrantes: Melhora a cor natural do lábio com visual animado e fresco. Brilho personalizável com camadas: Uma única camada dá um brilho natural, enquanto várias camadas construem um brilho vívido e semelhante ao vidro. Fórmula hidratante: Infundida com ingredientes hidratantes à base de plantas para manter os lábios macios e hidratados. Ampla gama de sombra: Disponível em 13 tons macios e lamados para se adequar a vários tons e humores da pele. ✨ Modo de usar Aplique uma pequena quantidade na parte interna dos lábios usando o aplicador. Misture suavemente do centro para fora para um acabamento natural. Para um visual mais ousado, aplique uma camada adicional para construir a cor.', 97.27, 97.27, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134207-7rd6m-lvnxofl50o8d9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F28550794167', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394042796', 'H''maston YD67 Carregador Power Bank Portátil 4 Cabos 10000mAh com indicador LED inteligente', '"Estação de carregamento no bolso" com display digital e cabo: esta mini fonte de alimentação com display digital e cabo integrado pode carregar telefones celulares, tablets, fones de ouvido bluetooth e muito mais, tornando-se uma verdadeira estação de carregamento portátil com quatro cabos de dados integrados. Compatibilidade estendida: equipado com quatro cabos de dados integrados, fácil de carregar e armazenar, suporta quatro tipos de interfaces. Ideal para pessoas que comem fora ou fazem compras sem levar cabos extras. Pequeno e portátil, fácil de transportar, design compacto e possibilidade de pendurar, muito conveniente para transportar em seu bolso ou bolsa, seja para uso diário ou viagem. Interface de entrada dupla quatro portas de saída para carregar 4 dispositivos ao mesmo tempo. Conteúdo incluído :1 entrada USB e 3 saídas de cabo integradas para carregar até 4 dispositivos simultaneamente. Exposição digital do diodo emissor de luz da eletricidade: exposição em tempo real da eletricidade restante, eliminando a adivinhação da eletricidade restante. Compatível com a aviação e ideal para viagens: este banco de potência está em conformidade com os padrões de segurança da aviação e pode ser transportado a bordo com confiança, garantindo que você possa carregar seus dispositivos, mesmo em viagens longas. Solução completa e conveniente para suas necessidades de energia: com capacidade de 10000mAh, esta mini fonte de alimentação fornece uma solução de carregamento completa e conveniente para o seu dispositivo. Seu design compacto, cabo integrado multifuncional, função 2 em 1, lanterna embutida, indicador de energia e conformidade com as normas aeronáuticas, o tornam perfeito para carregar seus dispositivos em qualquer situação.', 189.0, 99.99, NULL, 'Mobile & Gadgets > Accessories > Powerbanks & Batteries', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ma5cjf7228ef14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1155571749%2F23394042796', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211198791', 'Jogo de Panelas 6pçs Com Panela de Pressão 4,2L Brinox Botanika Revestimento Cerâmico e Indução', 'Conjunto de Panelas 6 Peças Brinox Botanika Antiaderente e Indução Descrição Comercial: O conjunto de panelas Brinox Ceramic Life Botanika 6 peças é ideal para quem busca praticidade, tecnologia e sofisticação para o dia a dia. Composto por panelas, caçarolas, frigideira e panela de pressão, oferece versatilidade para preparar diferentes receitas com mais eficiência e segurança. Produzidas em alumínio com revestimento antiaderente Ceramic Life, as peças proporcionam aquecimento rápido e uniforme, evitando que os alimentos grudem e facilitando a limpeza. Compatível com fogões por indução, gás, elétrico e vitrocerâmico, o conjunto entrega desempenho e praticidade para diferentes tipos de cozinha. O acabamento na cor verde Botanika traz um visual moderno e elegante, enquanto os cabos e alças antitérmicos oferecem mais conforto e segurança durante o uso. Características principais: - Conjunto completo com 6 peças - Revestimento antiaderente Ceramic Life - Compatível com fogão por indução - Estrutura em alumínio - Panela de pressão com sistema de segurança - Tampas em vidro temperado - Cabos e alças antitérmicos - Acabamento verde Botanika Benefícios ou diferenciais: - Cozimento rápido e uniforme - Antiaderente de fácil limpeza - Compatível com todos os tipos de fogão - Design moderno e sofisticado - Cabos e alças com toque confortável - Ideal para o preparo diário de diferentes receitas - Conjunto completo para equipar a cozinha Ficha Técnica: - Marca: Brinox - Linha Comercial: Ceramic Life Botanika / Pressure - Tipo de Produto: Conjunto de Panelas - Quantidade de Peças: 6 - Material principal: Alumínio - Revestimento Interno: Antiaderente Mineral Ceramic / Pro-Ceramic Premium - Revestimento Externo: Pintura siliconada - Cor: Verde Botanika - Compatibilidade com fogões: gás, elétrico, vitrocerâmico e indução - Material das tampas: Vidro temperado - Material dos cabos e alças: Soft-touch e baquelite antitérmico - Livre de PFOA: Sim Orientações de Uso: - Antes do primeiro uso, lave as peças com água, sabão neutro e esponja macia - Utilize utensílios de silicone, nylon ou madeira para preservar o revestimento - Evite materiais abrasivos na limpeza - Não aqueça as peças vazias por tempo prolongado - Utilize fogo médio para melhor desempenho térmico - Aguarde o resfriamento antes da lavagem Conteúdo da embalagem: 01 Caçarola Indução Brinox com Tampa Ø 22 x 10,5 cm - 3,55 Litros 01 Caçarola Indução Brinox com Tampa Ø 20 x 9,5 cm - 2,55 Litros 01 Panela Indução Brinox com Tampa Ø 18 x 9 cm - 1,55 Litros 01 Panela Indução Brinox com Tampa Ø 16 x 8 cm - 1,25 Litros 01 Frigideira Antiaderente Indução Brinox Ø 22 x 4,5 cm - 1,1 Litros 01 Panela de Pressão Brinox Ceramic Life Pressure - 4,2 Litros', 879.99, 569.99, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/br-11134207-820mf-mojs3v223x1c0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826682830%2F58211198791', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493142728', 'Sandália Infantil Plataforma Canal Da Belinha Preto Gliter Aranha Blogueira Confortável', 'Kidy está muito feliz por mais uma colab de sucesso com Belinha! Amamos a Belinha assim como você! Aos 9 anos, ela já conquistou mais de 6 milhões de inscritos no YouTube, oferecendo conteúdos encantadores sobre sua rotina, brincadeiras, histórias, músicas, danças e moda. A Sandália da Belinha, criada pela Kidy, já é um sucesso entre a própria Belinha e suas fãs e amigas. Com um toque atemporal, essa sandália combina com qualquer ocasião, seja para o dia a dia, festinhas no final de semana ou até mesmo para curtir um show da Belinha. Seu design inclui um solado de TR expandido e uma palmilha super macia, garantindo conforto em cada passo. Apesar de ser uma plataforma, a altura do salto é aprovada pelo IBetec para garantir a segurança das meninas. E o cabedal super moderno, com um toque de glitter, é simplesmente encantador, não é mesmo?', 119.99, 99.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-7rdxw-lxmxpn715x490f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F23493142728', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55513770394', 'Tênis Infantil Kidy Energy Bebê Calce Fácil Preto e Azul Royal', 'Tênis infantil confortável para o dia a dia Descubra o Tênis Infantil Kidy Energy Bebê Calce Fácil em Preto e Azul Royal, ideal para os pequenos que estão sempre em movimento. Projetado para proporcionar máximo conforto, este tênis infantil confortável é perfeito para longas horas de brincadeiras e atividades. Calçado prático para bebês ativos Com seu design exclusivo, o calçado prático bebê permite um encaixe simples e rápido nos pezinhos. Facilita a rotina dos pais, garantindo que os pequenos fiquem bem equipados com rapidez e segurança, sem complicações. Tênis antiderrapante para mais segurança A sola antiderrapante do tênis fornece estabilidade extra, essencial para os primeiros passos e aventuras. Este tênis antiderrapante criança traz uma combinação de estilo moderno e proteção, ideal para acompanhar o desenvolvimento infantil.', 139.99, 139.99, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-825aw-mqhm2eujbvnwac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F55513770394', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
