INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23791552690', '3 Gotas Mágica Solda Alumínio / Cobre / Latão 10ml', 'Gota Mágica - Frasco com 10 ml Fluxo para dar a liga da solda em cobre com alumínio. Use estanho comum. Contém 3 Unidades Aplicações: Fios e rabichos oxidados, soldas de escovas novas em bobinas de campo de alumínio, soquetes de lâmpada, enrolamentos de motores elétricos com fios de alumínio e instalações elétricas. Modo de usar: Lixe o alumínio e aplique uma gota no alumínio a ser soldado. Derreta o estanho no alumínio. Use uma gota também no cobre e derreta o estanho sobre ele. Após, efetue a soldagem. Aguarde 3 minutos para manuseio. Substitui a pasta de solda. Obs: O líquido do frasco pode estar na cor amarelada igual a foto ou na cor transparente. O produto é o mesmo, apenas o oxigênio em contato com o líquido altera a cor do produto porém continua com a mesma eficiência sem alterar suas propriedades. ***ATENÇÃO*** COMPARE AS NUMERAÇÕES E DESCRIÇÃO DO ANÚNCIO COM A SUA PEÇA OU INFORMAÇÕES. EM NOSSO ANÚNCIO CONSTAM A MAIORIA DOS NÚMEROS DE CONVERSÃO PARA COMPARAR. CASO NÃO TENHA A NUMERAÇÃO QUE PROCURA, FAÇA UM PERGUNTA PARA QUE POSSAMOS LOCALIZAR A PEÇA EQUIVALENTE. EQUIPE DL AUTO PARTS', 64.1, 64.1, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7qukw-li3d8xpche4005', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F662883696%2F23791552690', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
