INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22819138966', 'Calça Goleiro 3/4 Penalty Delta Pro', 'Máxima Proteção Para os Guardas-Redes! A Calça de Goleiro Penalty Delta Pro com comprimento , é uma ótima opção para os dias mais quentes. Sua modelagem anatômica de espuma pespontada com proteção de alta densidade e durabilidade, protege o quadril e os joelhos, reduzindo lesões no momento de impacto com o gramado. Para regulagem perfeita, a calça dispõe de elástico e cordão no cós. Use e Comprove! Benefícios Calça Delta Pro : Alta Proteção contra lesões. Desenvolvida para suportar impacto. Durabilidade. Alguns diferenciais técnicos: Com tecnologia de secagem rápida Dry One proporciona maior conforto e ágil absorção do suor.', 199.99, 199.99, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Training Equipments', 'https://cf.shopee.com.br/file/sg-11134201-7r99u-llpfw25i64pleb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F22819138966', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23219136676', 'Calça Penalty Chimpa Masculina', 'Pensando em praticar atividades físicas ou utilizar no dia a dia, a Penalty criou a Calça Penalty Chimpa Masculina. A peça vai encaixar perfeitamente no seu corpo e proporcionar o máximo de conforto e maciez no contato do tecido com a pele durante a utilização. A peça garante rápida absorção e passagem do suor para o exterior do tecido, proporcionando leveza e conforto. Benefícios: Leveza. Máximo conforto. Maciez do tecido no contato com a pele.', 112.9, 112.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-7rbkq-llp4keutou1v0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F23219136676', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58212635088', 'Vinil Frank Zappa - Bongo Fury 50th Anniversary (LP Colour Exclusive) - Importado', 'Vinil Frank Zappa - Bongo Fury 50th Anniversary (LP Colour Exclusive / Orange & Black Galaxy) - Importado Lançado em outubro de 1975, Bongo Fury é um álbum colaborativo dos músicos de rock experimental americanos Frank Zappa, Captain Beefheart e a banda de Zappa, The Mothers. Repertório do LP: Lado A: A1. Debra Kadabra A2. Carolina Hard-Core Ecstasy A3. Sam With The Showing Scalp Flat Top A4. Poofter''s Froth Wyoming Plans Ahead A5. 200 Years Old Lado B: B1. Cucamonga B2. Advance Romance B3. Man With The Woman Head B4. Muffin Man', 279.9, 237.9, NULL, 'Hobbies & Collections > Vinyl Records', 'https://cf.shopee.com.br/file/sg-11134201-82589-mr0j4ue8iha9f8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F58212635088', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597686452', 'O TAROT DA FRATERNIDADE BRANCA E AS CARTAS SAGRADAS DOS 12 RAIOS', 'O TAROT DA FRATERNIDADE BRANCA E AS CARTAS SAGRADAS DOS 12 RAIOS Denominado Tarot da Fraternidade Branca e as Cartas Sagradas dos 12 Raios, fruto de um trabalho de vários anos, finalmente concluído e pronto para ser utilizado por qualquer pessoa, mesmo para aqueles que ainda não tiveram contato com a Fraternidade Branca, e que tenham interesse em conhecê la ou aos que já tiveram contato com ela e que querem uma referência visual relacionada e com uma síntese de seus princípios. Com 36 cartas servem também aos tarólogos que procuram uma alternativa diferente das imagens e símbolos de outros tarots, e, aos curiosos em geral que tenham a mente e o coração abertos à evolução pessoal e autoconhecimento independente de crença, religião ou linha de pensamento.. Informações Adicionais Autor: RIBEIRO, MACHADO Data Publicação: 01/01/1900 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: O TAROT DA FRATERNIDADE BRANCA E AS CARTAS SAGRADAS DOS 12 RAIOS Idioma: PORT. DE PORTUGAL Páginas: 160 Edição: 1 ISBN-13: 9788598307060 ISBN-10: 8598307068', 175.0, 175.0, NULL, 'Books & Magazines > Books > Horoscopes', 'https://cf.shopee.com.br/file/sg-11134201-7rdy6-lygjnjnz1v3e36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23597686452', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58213384952', 'BUCHA GUIA DESLIZANTE BENGALA PAR GSF BANDIT 1200 N 96 A 08', 'PAR DE BUCHAS GUIA E DESLIZANTE DE BENGALA Compatibilidade: SUZUKI GSF BANDIT 1200 N de 1996 até 2008 Alta qualidade e maior desempenho: buchas guia e deslizante de bengala ORIGINAL Parts produzidas com revestimento em PTFE (teflon), garantindo baixo atrito, deslizamento preciso e maior durabilidade da suspensão. Produto novo, à pronta entrega, com garantia, compatível exclusivamente para os anos descritos abaixo. SUZUKI GSF BANDIT 1200 N 1996 SUZUKI GSF BANDIT 1200 N 1997 SUZUKI GSF BANDIT 1200 N 1998 SUZUKI GSF BANDIT 1200 N 1999 SUZUKI GSF BANDIT 1200 N 2000 SUZUKI GSF BANDIT 1200 N 2001 SUZUKI GSF BANDIT 1200 N 2002 SUZUKI GSF BANDIT 1200 N 2003 SUZUKI GSF BANDIT 1200 N 2004 SUZUKI GSF BANDIT 1200 N 2005 SUZUKI GSF BANDIT 1200 N 2006 SUZUKI GSF BANDIT 1200 N 2007 SUZUKI GSF BANDIT 1200 N 2008 Este produto refere-se a um kit contendo: 2 (duas) unidades de bucha guia de bengala com PTFE (teflon) interno, marca ORIGINAL Parts 2 (duas) unidades de bucha deslizante de bengala com PTFE (teflon) externo, marca ORIGINAL Parts SKU: KGS-1830 MEDIDAS NOMINAIS Bucha guia: 43 * 47 * 15 Bucha deslizante: 42 * 44 * 20 Marca da suspensão OEM na montadora: KAYABA Tipo de suspensão: Telescópica convencional O QUE É? O retentor de bengala é responsável por evitar o vazamento do fluido interno da suspensão dianteira, garantindo o funcionamento correto, a vedação precisa e a durabilidade do sistema. SERVE EM OUTRA MOTO? Não. Mesmo que outras motos tenham peças parecidas, as medidas podem ser diferentes. Este produto é exclusivo para o modelo de moto e anos indicados acima. Se tiver dúvidas, entre em contato com nosso suporte técnico antes da compra. Consulte também a política de trocas e devoluções. MEDIDAS CONFIÁVEIS As medidas seguem rigorosamente o padrão original da moto e são 100% calibradas. Você pode confiar na precisão técnica dos nossos retentores. GARANTIA Este item tem 90 dias de garantia contra defeitos de fabricação. Fatores externos como mau manuseio ou montagem sem ferramentas adequadas, que possam danificar o produto, não são cobertos pela garantia, configurando mau uso. RECOMENDAÇÃO IMPORTANTE Ao substituir este item, verifique também os demais componentes da suspensão da sua moto. Consulte nossa linha ORIGINAL Parts TECHCILINDROS para um reparo completo e seguro. SOBRE A MARCA A TECHCILINDROS atua desde 2008, oferecendo qualidade e variedade em tubos de bengala para motos de média e alta cilindrada, atendendo mais de 90% do mercado nacional. Em 2018, lançou a marca ORIGINAL Parts, com componentes premium de vedação e suspensão, garantindo mais segurança e durabilidade.', 170.79, 170.79, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-825ad-mq2di6hmd8uacd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609848355%2F58213384952', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494312975', 'Coleira Pet Snoopy G Up4you', 'Coleira Pet Snoopy ? Estilo, conforto e resist?ncia para o seu melhor amigo A nossa cole??o PET acaba de ganhar uma novidade encantadora: as coleiras tem?ticas do Snoopy, o personagem mais ic?nico dos quadrinhos agora faz parte dos acess?rios do seu pet com muito charme e autenticidade. Confeccionadas em poli?ster de alta resist?ncia, as coleiras contam com fecho pr?tico de encaixe, argola met?lica personalizada com o tema Snoopy e logo em silicone exclusivo. Al?m disso, s?o ajust?veis, garantindo maior conforto e seguran?a para o animal durante o uso di?rio. Tamanhos e indica??es de uso Antes de finalizar sua compra, verifique as medidas da coleira e compare com o porte do seu pet para garantir um ajuste ideal e confort?vel: Tamanho PP (modelo PC26004SN-PP): 15 x 120 x 250 mm ? Indicado para filhotes e c?es de porte muito pequeno, como Pinscher Mini, Chihuahua e Yorkshire mini Tamanho P (modelo PC26004SN-P): 15 x 230 x 350 mm ? Indicado para c?es de pequeno porte, como Yorkshire, Shih Tzu, Spitz Alem?o (Pequeno), Poodle Toy Tamanho M (modelo PC26004SN-M): 20 x 300 x 500 mm ? Indicado para c?es de porte m?dio, como Poodle M?dio, Beagle, Cocker Spaniel, Bulldog franc?s Tamanho G (modelo PC26004SN-G): 20 x 380 x 660 mm ? Indicado para c?es de porte m?dio a grande, como Golden Retriever, Labrador, Boxer, Border Collier Diferenciais do produto Estampa exclusiva do Snoopy Material leve, resistente e confort?vel Logo em silicone personalizado Argola met?lica com acabamento tem?tico Fecho de alta praticidade Produto oficial e licenciado Cuidados e conserva??o N?o lavar na m?quina N?o utilizar escovas duras ou produtos qu?micos agressivos Limpar com pano ?mido e sab?o neutro Secar ? sombra, longe de fontes de calor A coleira Snoopy ? ideal para quem deseja unir qualidade, funcionalidade e um toque divertido nos passeios com o seu pet. Um acess?rio seguro, bonito e cheio de personalidade.', 39.9, 39.9, NULL, 'Pets > Pet Accessories > Leashes, Collars, Harnesses & Muzzles', 'https://cf.shopee.com.br/file/sg-11134201-82595-mqsa65u01czzd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251967897%2F22494312975', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
