INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599844303', 'Luminária Arandela para Cabeceira Led 2W Recarregável Luz Quente Ajustável Bivolt', '🔋 Luminária Arandela de Cabeceira LED 2W Recarregável Luz Quente – Branco ou Preto Design moderno, funcionalidade e conforto visual! Ideal para cabeceiras, quartos, escritórios ou espaços de leitura. Compacta e discreta, essa luminária proporciona iluminação quente e aconchegante, além de contar com bateria recarregável e ajuste de ângulo. ✅ Principais Vantagens: Luz Quente (3000K): Iluminação suave e confortável para os olhos. Recarregável: Praticidade e autonomia sem depender de fios constantemente ligados. Design Minimalista: Disponível em branco ou preto, se adapta a qualquer decoração. Ajustável: Direcione a luz como quiser – ideal para leitura ou foco direcionado. Alta Eficiência: LED de 80LM/W com economia de energia. Instalação Fácil: Perfeita para ambientes residenciais e comerciais. 💡 Especificações Técnicas: Potência: 2W Cor da Luz: Branco Quente (3000K) Fluxo Luminoso: 80LM/W Tensão: Bivolt (110V - 220V) Ângulo de Abertura: 38° IRC (Índice de Reprodução de Cor): >80 Fator de Potência: >0,5 Grau de Proteção: IP20 (uso interno) Vida Útil: até 30.000 horas Cor do Produto: Branco ou Preto Dimensões: 60x140mm Tipo: Recarregável 📦 Itens Inclusos: 1x Luminária Arandela LED 2W 1x Kit de Fixação 1x Manual de Instalação ✨ Dê um toque moderno, funcional e confortável ao seu ambiente! Ideal para quem busca iluminação inteligente com estilo e eficiência. Aproveite!', 84.0, 39.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcprr88vfnle6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979730489%2F21599844303', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
