INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27639873784', 'Perfume Masculino La Rive Fearless Man EDT 90ml', 'Você é definido por ambição, independência e elegância. Seu superpoder reside na sua capacidade de se expressar da melhor forma, especialmente através da fragrância. Descubra LA RIVE FEARLESS MAN – uma composição que reflete perfeitamente o estilo de um homem moderno. Notas distintas de bergamota e pimenta rosa definem sua individualidade. Acordes aromáticos de sálvia, lavanda e cardamomo representam a força – não apenas da fragrância, mas também do seu caráter. Ouse enfrentar qualquer desafio e conheça o seu valor. Tenha orgulho de você – o mundo pertence a homens como você! Família Olfativa: Aromático Fougére Notas de Topo: Bergamota, Pimenta Rosa, Cardamomo Notas de Coração: Flor de Laranja, Lavanda, Sálvia Notas de Fundo: Patchouli, Madeiras Secas, Musgo de Carvalho', 132.55, 99.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mddw8tqedooic1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369057850%2F27639873784', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998842867', 'Processador Moedor Alimentos Elétrico Inox Com 4 Lâminas 2L 220V', 'Processador Moedor Alimentos Elétrico Inox Com 4 Lâminas 2l Voltagem:220v Processador de Alimentos Elétrico Picador de 2 Litros Mais Versatilidade na cozinha: com o processador de alimentos elétrico. Desde picar vegetais até misturar massas, ele simplifica uma variedade de tarefas culinárias. Potência e Eficiência: Equipado com um motor potente, este processador oferece um desempenho excepcional para lidar com uma variedade de alimentos, desde os mais macios até os mais duros, de forma rápida e eficiente. Facilidade de Limpeza: Esqueça a preocupação com a limpeza após preparar suas refeições. Com partes removíveis, você economiza tempo e esforço. Com o processador de alimentos elétrico, você pode preparar receitas deliciosas e . Desde cortar legumes para saladas até processar ingredientes para massas e sobremesas, este aparelho será um grande aliado na cozinha. Características: Cor: Prata Material: Aço Inoxidável Tensão: 110V ou 220V (Selecione a voltagem no ato da compra) Potência: 850W Velocidade: 2 níveis Capacidade da tigela: 2L', 169.0, 169.0, NULL, 'Home Appliances > Kitchen Appliances > Food Processors & Meat Grinders', 'https://cf.shopee.com.br/file/sg-11134201-824h1-mdw6ibuliuiq4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23998842867', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
