INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598808274', '10 AÇÚCAR CRISTAL VERMELHO PARA MORANGO DO AMOR 500g', 'Açúcar Cristal Vermelho para Morango do Amor 500g – Mix Festas Ideal para dar cor, brilho e sabor irresistível às suas receitas, o Açúcar Cristal Vermelho Mix Festas é perfeito para preparar deliciosos morangos do amor, maçãs caramelizadas, confeitar doces e criar decorações vibrantes. Com granulação uniforme e coloração intensa, garante um acabamento profissional e atraente. Embalagem de 500g, prática e fácil de armazenar, indispensável para festas, eventos e confeitaria criativa.', 159.85, 127.88, NULL, 'Food & Beverages > Cooking Essentials > Sugar', 'https://cf.shopee.com.br/file/sg-11134201-7rdwv-mdbx7r3r6k3ya2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F22598808274', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
