INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097996423', 'Minilanterna Recarregável 50 Lúmens Bateria De Lítio Vonder', 'Minilanterna recarregável, 50 lúmens, bateria de lítio, VONDER Possui bateria de íons de lítio recarregável, entrada para carregamento micro USB, LED indicador de carregamento e acompanha cabo USB de 20 cm. Conta ainda com três modos de luminosidade: forte, fraco, S.O.S. Indicada para iluminação em geral. Utilizada em campings, residências, entre outros. Material da lanterna: Plástico ABS Cor da lanterna: Preta Fluxo luminoso (lm): 50 Quantidade de LEDs da lanterna: 1 LED SMD Tipo de lâmpada: Led Diâmetro da lente da lanterna: 20,5 mm Comprimento total da lanterna: 105,0 mm Tempo de carga: Aproximadamente 4 horas Alimentação da lanterna: Recarregável Bateria: 3,7 V - 1.200 mAh - Íons de lítio Entrada de carregamento: Micro USB Massa aproximada (peso) (kg): 0,055 kg Conteúdo da Embalagem: 1 Minilanterna. Acompanha: 1 cabo micro USB.', 56.99, 42.53, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/sg-11134201-7rd6b-lvz1xif4x0dr67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23097996423', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202617568', 'Kit Elseve Collagen Lifter Completo 5 Unidades 400ml', '#html-body [data-pb-style=CQQFWTE]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}O Kit Elseve Collagen Lifter Completo é ideal para quem busca uma rotina capilar completa e duradoura, com embalagens maiores que garantem melhor rendimento. Enriquecido com colágeno, o kit ajuda a fortalecer a fibra capilar, deixando os fios mais resistentes, macios, alinhados e com aparência saudável. O kit contém cinco produtos essenciais para um cuidado diário eficaz: Shampoo Elseve Collagen Lifter 400ml: Limpa profundamente sem ressecar, removendo impurezas e preparando os fios para o tratamento. Condicionador Elseve Collagen Lifter 400ml: Desembaraça, sela as cutículas e proporciona maciez prolongada. Máscara Elseve Collagen Lifter 300g: Tratamento intensivo que nutre profundamente, fortalecendo os fios e devolvendo elasticidade. Creme de Pentear Elseve Collagen Lifter 250ml: Auxilia no desembaraço, controla o frizz e mantém os cabelos disciplinados ao longo do dia. Sérum Capilar Elseve Collagen Lifter 100ml: Finaliza com brilho intenso, toque sedoso e proteção térmica, sem pesar os fios. Indicado para todos os tipos de cabelo que precisam de mais corpo, força e luminosidade, o kit proporciona resultados visíveis desde as primeiras aplicações, com fios mais encorpados, suaves e brilhantes. Modo de Uso: Shampoo Elseve Collagen LifterAplique nos cabelos molhados, massageando suavemente o couro cabeludo. Enxágue bem. Repita se necessário. Condicionador Elseve Collagen LifterApós o shampoo, aplique no comprimento e pontas. Deixe agir por alguns minutos e enxágue completamente. Máscara Elseve Collagen LifterCom os cabelos limpos e úmidos, aplique a máscara no comprimento e pontas. Deixe agir de 3 a 5 minutos e enxágue bem. Creme de Pentear Elseve Collagen LifterAplique nos cabelos úmidos ou secos, distribuindo do comprimento às pontas. Não enxaguar. Sérum Capilar Elseve Collagen LifterAplique algumas gotas nas mãos e espalhe nos fios, evitando a raiz. Pode ser usado antes ou após o uso de ferramentas térmicas.', 262.57, 262.57, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-81zu5-mj022vzxfzsz6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F58202617568', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
