INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50360357890', 'Fones de ouvido sem fio GOOJODOQ J238 Bluetooth 5.3 com assistente de voz, arco de cabeça ajustável, leves e compactos.', 'Som estéreo potente com máxima clareza: Projetado com dois drivers dinâmicos de 40 mm, este fone de ouvido portátil oferece um som estéreo profundo e potente com áudio Hi-Fi cristalino. Cada nota e detalhe ganham vida, imergindo você em uma experiência de audição com qualidade de concerto — a qualquer hora, em qualquer lugar. Ultracompacto e leve: Pesando apenas cerca de 92 g e com metade do tamanho dos fones de ouvido padrão, este mini fone de ouvido cabe facilmente em qualquer bolsa sem ocupar muito espaço. Desfrute de 6 a 8 horas de música, tão leve que você mal perceberá que está usando. Conectividade Bluetooth 5.3 ininterrupta: O chip Bluetooth 5.3 permite um emparelhamento mais rápido, maior estabilidade de sinal e maior compatibilidade com smartphones, tablets e laptops. Desfrute de áudio ininterrupto com latência ultrabaixa. Controles intuitivos e assistente de voz: O touchpad intuitivo permite reproduzir/pausar músicas, ajustar o volume, atender chamadas ou alternar para o modo de jogo com facilidade. Ative seu assistente de voz com um único toque e gerencie suas tarefas sem usar as mãos, sem precisar pegar o telefone. Arco de cabeça ajustável e almofadas auriculares respiráveis: Combinando durabilidade e conforto. Construído para durar, com uma estrutura de aço inoxidável que se ajusta à maioria dos tamanhos de cabeça. As almofadas auriculares giratórias em 90° são acolchoadas com espuma viscoelástica macia e respirável.', 150.0, 89.0, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134201-822yo-mo560wc6x2bk20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1114645438%2F50360357890', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23092498654', 'Loção Hidratante Corporal Paixão Acetinada Inspiradoras Rosas Brancas 300g', 'A Loção Hidratante Rosas Brancas vai deixar a pele hidratada por 48 horas. Sua fórmula com óleo de amêndoas e a textura cremosa acetinada, deixam a pele macia, com um delicado toque de seda. Sua fragrância possui notas de lavanda, alecrim e bergamota. Notas florais que desabrocham com um fundo de madeiras nobres e especiarias. De uso diário, o produto é indicado para todos os tipos pele. Modo de uso: Usar de modo habitual #html-body [data-pb-style="646BA65EC033B"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA65EC034F"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 44.19, 44.19, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-7rbmq-lmg6stkfntb769', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23092498654', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9550697525', 'Soro Facial MultiFuncional PhálleBeauty PH0145', 'O Soro Facial Multifuncional PhálleBeauty possui uma textura fresca, delicada e leve, que deixa uma sensação de pele nua. Atuando como um potente impulsionador da hidratação, se tornando um reforço para todos os tipo de pele que podem sofrer de desidratação, por vezes, devido a vários fatores como: clima, sol, vento, ar-condicionado e estilo de vida. Um complemento ideal para todas as rotinas de cuidados com a pele.', 15.99, 15.99, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1o3pt5tbyfca1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F434200296%2F9550697525', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57952762767', 'Colágeno Verisol Tri Plus Tipo 1 Tipo 2 e 3 - 210g Bodyaction', 'COLÁGENO TRI-PLUS Ingredientes (Sabor Manga com Maracujá): Peptídeos bioativos de colágeno hidrolisado com peso molecular médio de 2kDa VERISOL, Colágeno hidrolisado, Maltodextrina, Ácido hialurônico (Hialuronato de Sódio obtido pela fermentação de Streptococcus zooepidemicus), Colágeno tipo II (Colágeno de frango com colágeno tipo II não desnaturado), Vitamina C (Ácido ascórbico), Coenzima Q10, Silício (Ácido ortosilícico estabilizado em cloreto de colina), Vitamina E (Acetato de DL-alfa-tocoferol), Zinco (Sulfato de zinco monoidratado), Vitamina A (Acetato de retinol), Biotina (D-biotina), Selênio (Selenito de sódio), Aromatizantes sintéticos idênticos aos Naturais, Acidulante Ácido cítrico, Edulcorante Glicosídeos de esteviol (Stevia rebaudiana) e Corante Natural Urucum. NÃO CONTÉM GLÚTEN. NÃO CONTÉM LACTOSE. ALÉRGICOS: PODE CONTER LEITE E SOJA*. *Produzido em equipamento onde se processam também estes alimentos, contudo, ações preventivas de limpeza são adotadas para evitar essa ocorrência. Modo de Preparo: Diluir 7 g (aproximadamente 3 dosadores cheios) em 100 ml (1 copo americano) de água ou bebida de sua preferência, mexendo até completa dissolução. Pode ser consumido quente ou frio. Evite utilizar água fervente. Sugestão de Uso: Consumir 1 (uma) porção 1 (uma) vez ao dia. PRODUTO INDICADO PARA MAIORES DE 19 ANOS. Conservação: Manter em local fresco, não úmido e ao abrigo da luz. Não consumir o produto se o lacre de proteção estiver violado. Após aberto, consumir preferencialmente em 60 dias. Advertências: “ESTE PRODUTO NÃO É UM MEDICAMENTO”. “NÃO EXCEDER A RECOMENDAÇÃO DIÁRIA DE CONSUMO INDICADA NA EMBALAGEM”. “MANTENHA FORA DO ALCANCE DE CRIANÇAS”. “ESTE PRODUTO NÃO DEVE SER CONSUMIDO POR GESTANTES, LACTANTES E CRIANÇAS”. Apresentação: Lata com 210g', 98.63, 47.0, NULL, 'Health > Food Supplement > Beauty Supplements', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi0466iqh7upac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443076516%2F57952762767', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
