INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204162160', 'Neutrogena Sun Fresh FPS 70 - Protetor Solar Facial 40g', 'Protetor solar facial para todos os tipos de pele. Neutrogena Sun Fresh Facial FPS 70 possui textura ultraleve e seca, que te protege contra os raios UVA, UVB, e ajuda contra a luz visível. Ideal para completar sua rotina de cuidado com a pele. Protetor Solar Neutrogena Sun Fresh Facial FPS 70 foi desenvolvido especialmente para o rosto, com fórmula ultraleve, de rápida absorção, com toque seco e altamente resistente à água. Ajuda a prevenir o envelhecimento precoce e as marcas causadas pelo sol, mantendo a pele protegida, hidratada e sequinha. Além de deixar sua pele macia, aveludada e preenchida com seus ativos ricos em propriedades hidratantes. Benefícios de Protetor Solar Neutrogena Sun Fresh Facial FPS 70: ▸Protetor solar facial para todos os tipos de pele;▸FPS 70 com alta proteção contra raios UVA, UVB e luz visível;▸Textura ultraleve, de rápida absorção e toque seco;▸Ajuda a prevenir envelhecimento precoce e manchas solares;▸Mantém a pele protegida, hidratada e sequinha;▸Resistente à água e ideal para uso diário;▸Deixa a pele macia, aveludada e com aparência saudável. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 62.9, 62.9, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-8261x-mjzxmv636scg61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58204162160', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40880054138', 'Máscara de Cílios Eudora Niina Secrets Super Up 8g', 'Máscara de Cílios Eudora Niina Secrets Super Up 8g A Máscara de Cílios Eudora Niina Secrets Super Up foi desenvolvida para proporcionar efeito de cílios mais alongados, definidos e com volume intenso. Sua fórmula ajuda a destacar o olhar enquanto o aplicador facilita a distribuição uniforme do produto, garantindo acabamento marcante e elegante para diferentes ocasiões. Principais Características: - Proporciona efeito de alongamento e volume para os cílios. - Fórmula de alta pigmentação que realça o olhar. - Aplicador desenvolvido para facilitar a aplicação uniforme sem acúmulo excessivo. Benefícios: - Cílios mais destacados e definidos. - Efeito de volume intenso e aparência alongada. - Ajuda a valorizar a maquiagem dos olhos. - Fácil aplicação no dia a dia. - Longa duração para manter o visual impecável. - Secagem rápida e acabamento uniforme. Diferenciais do Produto: - Desenvolvida em parceria com a linha Niina Secrets. - Combina volume, definição e alongamento em um único produto. - Aplicador anatômico que auxilia na separação dos fios. - Ideal para compor desde maquiagens leves até produções mais intensas. Especificações Técnicas: - Marca: Eudora - Linha: Niina Secrets - Modelo: Super Up - Tipo de Produto: Máscara de Cílios - Conteúdo: 8g - Peso aproximado: 35g Instruções de Uso: - Aplique a máscara da raiz até as pontas dos cílios utilizando movimentos em zigue-zague. - Reaplique quantas vezes desejar para intensificar o efeito. - Aguarde alguns segundos entre as camadas para melhor acabamento. Avisos e Precauções: - Uso externo. - Evite contato direto com os olhos. - Em caso de irritação, suspenda o uso e procure orientação médica. - Não compartilhar o produto com outras pessoas. - Manter bem fechado após o uso. - Conservar em local fresco e seco, longe da luz solar. O que está incluso? - 01 Máscara de Cílios Eudora Niina Secrets Super Up 8g ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 71.19, 70.59, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/br-11134207-820mg-moh7ers2x728b0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F40880054138', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8784647975', 'AVENTURAS DE MIKE, AS - O LIVRO INTERATIVO - OUTRO PLANETA', 'Se você tivesse uma casa na árvore, como seria? Você tem a habilidade de encontrar uma CAPIVARA perdida? E que tal fazer parte de uma história comigo e meus amigos? Eu sou o Mike, e este é meu Livro Interativo! Com a sua ajuda, vamos embarcar em uma aventura juntos. Então, já prepare seus lápis, suas canetinhas, sua criatividade e vamos começar.', 48.5, 48.5, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-821g5-mh7szxaps6bx7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F8784647975', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097416190', 'Acidificante Capilar Triskle 1 120ml', 'O Acidificante Dr. Triskle possui fórmula equilibrada para cabelos que passaram por processo de coloração , descoloração e processos químicos , podendo ser utilizado por cabelos que estão porosos , desvitalizados , sem brilho e com frizz. Sua fórmula possui Vinagre Herbal que irá balancear o pH do fio. Modo de uso: Aplicar o acidificante após o shampoo , aguardar de 3 a 5 minutos dependendo do estado do cabelo, enxaguar e em seguida aplicar a máscara de hidratação ou condicionador. #html-body [data-pb-style="646BA662010AE"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA662010C3"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 65.43, 65.43, NULL, 'Beauty > Hair Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbku-lmhngqhfs6bp7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F21097416190', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
