INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200507110', 'Retentores de valvulas Para Astra Corsa Celta Montana Takao', 'IDEAL AUTO PARTS Dsde 1990 IDEAL PARA SEU CARRO Retentores de valvulas TAKAO APLICAÇÃO CHEVROLET Astra 1.8 8v De 1999 A 2004 Corsa 1.0 8v De 1997 A 2001 Celta 1.0 8v De 2002 A 2010 Montana 1.4 8v De 2004 A 2011 FIAT Palio 1.0 8v Fire De 2001 A 2010 Siena 1.0 8v Fire De 2001 A 2010 Palio 1.4 8v Fire De 2005 A 2010 Siena 1.4 8v Fire De 2005 A 2010 VOLKSWAGEN Fox 1.0 8v De 2002 A 2011 Fox 1.6 8v De 2005 A 2011 Crossfox 1.6 8v De 2005 A 2011 Spacefox 1.6 8v De 2005 A 2011 OBS: DIÂMETRO DO EIXO 6.00mm OBS: DIÂMETRO DO ALOJAMENTO 8.80mm OBS: ALTURA RETENTOR 12.20mm CODIGO DO FABRICANTE TAKAO RVVW10 CONTEÚDO DA EMBALAGEM 08 RETENTOR DE VALVULAS QUALIDADE Produto Novo GARANTIA 03 Meses De Garantia NOTA FISCAL Sim SUPORTE PÓS VENDA Sim SOBRE A IDEAL AUTO PARTS Fundada em 1990, somos uma empresa do ramo de comércio e varejo de peças novas para veículos automotores. São mais de 30 anos oferecendo peças reconhecidas nacionalmente e internacionalmente com os melhores preços do Brasil. A paixão por automóvel e o crescimento do mercado, contribuiu para a expansão da marca e hoje contamos com quatro endereços físicos, localizados em pontos estratégicos na cidade de Limeira, Artur Nogueira e Rio Claro, no interior de São Paulo. Contamos com uma equipe especializada para prestar o melhor atendimento e oferecer exatamente o que nosso cliente precisa. São mais de 35 mil Itens de diversas montadoras a disposição em nossas lojas. CASO TENHA ALGUMA DÚVIDA USE O CAMPO DE PERGUNTAS, ESTAREMOS A DISPOSIÇÃO PARA TE ATENDER', 28.9, 28.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-821eb-mgwqfa973g9993', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F433880234%2F58200507110', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
