INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9470355512', 'Livro - Tromba d''água - Capa comum - Ciranda Cultural', 'Conheça Binho, um elefante apaixonado pela natureza. Seu sonho é ser jardineiro, mas ele se acha muito grande, pesado, desajeitado. Será que é isso mesmo? Leia o delicado e divertido Tromba d''água e veja como é sempre atual o velho ditado: quem vê cara, não vê coração!. Editora: Ciranda Cultural Edição: 1, 2020 Autor: Leo Cunha Idioma: Português Páginas: 40 Dimensões: L 23.00 x A 26.00 x E 0.40 ISBN: 9786555000542', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/2fbaff39e01665002f49146780eb2319', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F9470355512', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8570296254', 'Livro - Pauliceia desvairada - Principis', 'Neste livro, o leitor encontrara a primeira obra marcadamente modernista de Mario de Andrade, um dos mais ativos participantes da Semana de Arte Moderna de 1922 e um dos principais autores do Modernismo brasileiro. Vista sob a ótica do Arlequim, da loucura, e representada por meio de recursos estilísticos inspirados nas vanguardas europeias, a Pauliceia desvairada revela-se multicultural e cosmopolita: atual, portanto, como a obra do escritor. Editora: Principis Edição: 3, 2019 Autor: Mário de Andrade Idioma: Português Páginas: 112 Dimensões: L 16.00 x A 23.00 x E 1.00 ISBN: 9788594318879', 19.9, 19.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/0d63489c572168ad56d2bb1dc6bb7fd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8570296254', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21597986080', 'Pet Eletrônico Interativo Bichinho Virtual Punirunes - Sunny 4280', 'Pet Interativo dos Punirunes: Explore uma nova forma de diversão com o novo pet interativo dos Punirunes, repleto de sons e luzes para brincar com você sempre! Diversão com jogos: Além do pet, você terá acesso a jogos e opções de customização para uma experiência completa e personalizada. Variedade de personagens: Com 55 personagens diferentes para desbloquear, sua brincadeira nunca terá fim com esse novo pet interativo dos Punirunes, garantindo uma diversão sem limites! Interação cativante: Desfrute de momentos de diversão e interação com o pet interativo dos Punirunes, que vai proporcionar horas de entretenimento para você e sua família. Basta tocar para interagir. Descubra a alegria dos Punirunes: Com seu novo pet interativo, mergulhe no mundo dos Punirunes e explore todas as aventuras e possibilidades que eles têm a oferecer, tornando cada momento de brincadeira ainda mais emocionante e divertido! Características: Marca: Sunny Brinquedos Referência: 4280 Idade recomendada: A partir de 4 anos Pilhas Inclusas? Tipo de Pilha/Bateria Sim. 3 pilhas AAA (LR03) de 1,5V Possui Luzes: Sim Possui Sons: Sim Dimensões aproximadas da embalagem: 17,8 x 15,3 x 6,6cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Pet Eletrônico Interativo Punirunes Certificado Inmetro: REGISTRO 001893/2023 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 509.9, 149.0, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2tr2cquiln7a4', 'https://shope.ee/an_redir?origin_link=https%3A%