INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21797608020', 'Kit óleo Motor 20W50 + Filtro De óleo Monza 1.8 2.0 Todos', 'Filtro de óleo Automotivo Anúncio referente ao Kit Inclui: 1 = filtro de óleo 4 = òleo De motor 20w50 Marca: Filtran Compatibilidade: Monza 1.8 2.0 Todos - Filtra impurezas do óleo do motor. - Varia de tamanho conforme o veículo. - Troca recomendada durante a manutenção regular. - Disponível em diferentes modelos para veículos específicos. - Ajuda a prolongar a vida do motor. Como montar: 1. Limpe a base de assentamento do filtro 2. Oleie levemente a junta de vedação 3, Após encostar na base, aperte manualmente mais de 3/4 voltas 4. Ligue o motor e veriique se há vazamento', 149.0, 149.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rd4g-lu9ogbrl15ho73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397577506%2F21797608020', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498356558', 'LEGO City - Piloto de F1 com carro McLaren - 86 Peças - 60442', 'As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. • As crianças podem mergulhar na emoção das corridas de alta velocidade com o conjunto LEGO City F1 Driver com McLaren Race Car (60442). Perfeito para entusiastas de corrida a partir de 6 anos, o brinquedo mini veículo apresenta um design superaerodinâmico de Fórmula 1 com pneus lisos e vem com uma minifigura de piloto de F1 McLaren para brincadeiras imaginativas e narrativas. Descubra a linha dinâmica de conjuntos LEGO com tema de F1 para crianças e adultos. Este brinquedo é o presente ideal para meninos e meninas de todas as idades, especialmente recomendado para maiores de 6 anos de idade! • Conteúdo da embalagem: 86 Peças Lego Características do Produto • Dimensões aproximadas da embalagem: 14x05x16cm (AxLxC) • Composição do material: Plástico • Código do fabricante: 60442 • Peso aproximado: 0.140 Idade recomendada: A partir de 06 anos ATENÇÃO: Não recomendável para menores de 03 anos por conter partes pequenas que podem ser engolidas ou aspiradas. Utilizar sob a supervisão de um adulto. Este brinquedo só deve ser entregue à criança após ter sido montado por um adulto. Certificado pelos Órgãos Autorizados - OCP´S (Organismos de Certificação de Produtos) Certificado Inmetro: REGISTRO 005828/2021', 143.99, 143.99, NULL, 'Hobbies & Collections > Collectible Items > Statues & Sculptures', 'https://cf.shopee.com.br/file/sg-11134201-8258x-mqw7opdhg1e2fa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1246508007%2F22498356558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58059614835', 'Bota Vizzano Fivela Cano Baixo Feminina - Marrom', 'A bota de cano curto da Vizzano é a escolha ideal para quem busca unir estilo atual e conforto no dia a dia. Com um design moderno e urbano, o modelo se destaca pela fivela maxi lateral, que adiciona personalidade e um toque fashion ao visual. O elástico lateral facilita o calce, proporcionando mais praticidade na rotina sem abrir mão do ajuste confortável aos pés. Seu bico levemente quadrado traz uma estética contemporânea, enquanto o salto bloco médio garante estabilidade e segurança ao caminhar, tornando a bota perfeita para longos períodos de uso. Versátil e cheia de atitude, combina facilmente com jeans, vestidos ou saias, criando produções estilosas para diferentes ocasiões. É Aquele item indispensável no guarda-roupa para compor looks elegantes com um toque urbano. Garanta já a sua!', 279.9, 259.9, NULL, 'Women Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/sg-11134201-820m8-mnlf4cxndlaa38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F58059614835', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28893932565', 'Sandália Havaianas Luna Feminina - Preto', 'Inspirada no movimento Memphis dos anos 1980, o modelo fechado Luna é perfeito para quem busca por sandálias românticas. Possui tiras inferiores trançadas e conta com quatro opções de cores, além do detalhe oval na parte da frente, sua marca registrada. Charme e conforto? Temos!', 89.9, 59.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mju9q969bv9i1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F28893932565', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259687955', 'Chocolate Recheado Negresco', 'A combinação perfeita da cremosidade do Chocolate Nestlé com a crocância do Biscoito Negresco em um só tablete! Uma experiência deliciosa para os amantes de chocolate e biscoitos. Ideal para saborear a qualquer hora, seja sozinho, com amigos ou como um toque especial em suas sobremesas.', 12.79, 12.79, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-8257s-mqnel52hdamj0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554820%2F58259687955', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897292901', 'Kit Esmalte Impala Perolado Polar (5 unidades)', 'Esmaltes Impala: Tecnologia, Qualidade e Tendências Descubra a nova coleção de esmaltes da Impala e tenha unhas deslumbrantes e duradouras. Criados com tecnologia de ponta, esses esmaltes oferecem a mais alta qualidade e são inspirados nas últimas tendências da moda. Com eles, suas mãos e seus pés estarão sempre bem cuidados e você se sentirá confiante e elegante. Os esmaltes Impala possuem ação duradoura e brilho prolongado, para que você possa aproveitar suas unhas impecáveis por muito mais tempo. Além disso, sua fórmula suave é livre de ingredientes tóxicos, garantindo a saúde de suas unhas. Experimente a diferença dos esmaltes Impala e sinta a beleza em suas mãos e pés. Disponíveis em uma ampla variedade de cores e acabamentos, eles são perfeitos para qualquer ocasião. Escolha seu favorito e arrase em todos os lugares! Modo de usar: 1. Limpe bem as unhas com um removedor de esmalte suave. 2. Aplique uma camada fina do esmalte Impala, começando pelo centro da unha e indo até as bordas. 3. Se desejar uma cobertura mais intensa, aplique uma segunda camada. 4. Deixe secar completamente antes de aplicar qualquer outro produto. Dicas: - Para uma maior durabilidade, aplique uma camada de base antes do esmalte. - Remova o esmalte com um removedor suave para proteger suas unhas. - Guarde os esmaltes em um local fresco e seco, longe da luz solar direta. Kit contém 05 unidades do Esmalte Impala Perolado Polar', 38.45, 38.45, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbl3-lqm1fjmmtp2y23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22897292901', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399306469', 'Bandeja para Banheiro Coza Flora Areia Coast', 'Apresentamos a Bandeja para Banheiro Coza Flora Areia Coast é um item prático e funcional que facilita a organização e higiene do seu banheiro. DIFERENCIAIS: A Bandeja para Banheiro Flora da Coza organiza a pia e a bancada, além de dar um up na decoração do lavabo ou banheiro da sua casa. Charmosa e funcional, facilita a rotina de higiene. Ter seus objetos de uso diário belamente dispostos e sempre à mão na hora de realizar sua higiene pessoal, é uma das praticidades que a Bandeja para Banheiro da Flora Ocean disponibiliza. Além de compor a sua bandeja com os produtos da Flora, é possível usar sua criatividade para, por exemplo, combinar um aromatizador com o Porta Sabonete líquido do conjunto organizador. Ao mesmo tempo, a cor Areia Coast do produto acrescenta um ar sofisticado e clean ao ambiente. A Coza, com sua Linha Flora, oferece esta e uma série de outros itens funcionais que realçam a décor seu banheiro. MATERIAL: Fabricada em polipropileno, a Bandeja para Banheiro Coza Flora é sustentável e eco-friendly, pois sua resina é totalmente oriunda de plástico reciclado plástico reciclado pós-consumo (PCR) recolhido do meio ambiente, reduzindo a contaminação de diversos biomas. Com a assinatura da marca Coza, o produto possui alto padrão estético e tecnológico, garantindo longa durabilidade e qualidade. Além disso, é 100% reciclável, livre de BPA e utiliza energia de fontes renováveis no processo produtivo, reforçando o compromisso da Coza com a sustentabilidade ambiental. DIMENSÕES: Com dimensões compactas de 27 cm de comprimento, 13 cm de largura e 1,5 cm de altura, a Bandeja para Banheiro Coza Flora ocupa pouco espaço e adiciona um visual descontraído ao ambiente. INSTRUÇÃO DE USO E LIMPEZA: Para garantir a durabilidade e o bom funcionamento da Bandeja para Banheiro Flora, é essencial seguir algumas orientações simples de cuidados. Para limpeza e manutenção, basta utilizar um pano macio e umedecido com água e sabão neutro, ou optar pelo lado macio da esponja para remover sujeiras leves. Evite o uso de materiais abrasivos, como esponjas ásperas ou escovas de cerdas duras. INFORMAÇÕES ADICIONAIS: A Bandeja para Banheiro Flora da Coza integra a coleção de itens de higiene pessoal para compor o seu banheiro. O conjunto completo conta com porta escova de dentes com e sem tampa, porta sabonete líquido, porta algodão cotonetes, saboneteira, lixeira e bandeja para banheiro. Conheça algumas vantagens da Bandeja para Banheiro Coza Flora Areia Coast: Mantém a pia seca; Organiza sua área bancada; Embeleza o banheiro; Deixa o que você mais precisa sempre à mão; Tem longa durabilidade, pois os produtos da Coza têm alto padrão estático e tecnológico. Com a Linha Flora da Coza, você tem acesso ao que há de mais tecnológico, moderno e elegante para organizar e decorar sua casa. Escolha a Bandeja para Banheiro Coza Flora Areia Coast e outros produtos desta coleção para transformar seu banheiro em um ambiente funcional, bonito e sustentável. Transforme sua rotina com a praticidade e sofisticação que só a Coza pode oferecer!', 22.99, 17.85, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/br-11134201-820lm-mqxhv8xybksnd9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F21399306469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252088853', 'Tintura Alta Moda Color Sem Amônia 9.1 Louro Clarissimo Cinza', '#html-body [data-pb-style=UXVU770]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}A Alta Moda Tintura Colore Louro Claríssimo Cinza 9.1 é uma coloração permanente desenvolvida pela Alfaparf, que oferece um loiro claríssimo cinza profundo e duradouro sem agredir os fios. Sua fórmula é enriquecida com peptídeos e proteínas do arroz e da quinoa, que penetram na fibra capilar, melhorando a fixação da cor e proporcionando brilho e maciez. Além disso, é livre de amônia, sendo uma opção vegana que respeita a saúde dos cabelos e do couro cabeludo. Modo de Uso: Realize a prova de toque 48 horas antes da aplicação para verificar possíveis alergias. Misture o conteúdo da coloração com o oxidante conforme as instruções do fabricante. Aplique nos cabelos secos, distribuindo uniformemente da raiz às pontas. Deixe agir pelo tempo indicado na embalagem. Enxágue bem até a água sair limpa e finalize com o tratamento pós-coloração incluso no kit.', 38.58, 38.58, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-81zug-mid7b6iotuki1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F58252088853', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19158191902', 'Porta Guardanapos - Brinox Parma 12,9x5,3x9cm Aço Inox', 'Seja Bem-Vindo(a) à Mimorada! Porta Guardanapos Brinox Parma 12,9 x 5,3 x 9 cm Aço Inox Prático, funcional e elegante, o porta-guardanapos da linha Parma deixa a sua mesa organizada e cheia de estilo. Seu desenho permite que os guardanapos sejam armazenado sem dobraduras e que possam ser retirados individualmente. Fabricado em aço inox, o produto resistente e fácil de limpar. Suas dimensões são 12,9cmx5,3cmx9cm. Material: Aço Inox', 83.99, 53.55, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-23010-iqvj9uet9ymvf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F19158191902', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797313146', 'Kit Shampoo Condicionador Tresemmé Reconstrução E Força', '#html-body [data-pb-style=RQVHMSC]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}Conheça a linha TRESemmé Reconstrução e Força que reduz a quebra dos fios em até 99% desde o primeiro uso¹. Com a avançada tecnologia de ação intra-celular, seus cabelos ficarão visivelmente mais fortes e saudáveis. Kit Contém: - Shampoo Froça e Reconstrução 300ml - Condicionador 175ml', 42.45, 42.45, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rccb-lr4jr4wj6edu76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22797313146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
