INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28536624914', 'Bíblia em Ação | Começa a Batalha', 'Livro Bíblia em Ação Começa a Batalha Esse livro da Linha em Ação conta sobre a criação, a história de Adão e Eva e a armadilha de Lúcifer de uma maneira totalmente interativa. Completamente no estilo HQ em suas mais de 100 páginas de muita ação, tornando ainda mais divertido conhecer as aventuras das Sagradas Escrituras. Sergio Cariello é o autor da prestigiada Bíblia em ação. Como artista reconhecido desde a infância, ele já desenhava tirinhas para o jornal de sua cidade desde os onze anos. Mais tarde, trabalhou para as prestigiadas Marvel e DC Comics. Foi aluno, ainda, na escola de Desenho e Artes Gráficas de Joe Kubert e do Instituto Palavra da Vida. Atualmente ele mora na Flórida (EUA), com a esposa Luzia. Caleb J. Seeling nasceu numa família americana do Colorado, com profundas raízes cristãs. Ele tem lido e escrito histórias desde que se entende por gente. Sua paixão por literatura finalmente o levou à indústria editorial como editor-sênior, onde ajudou a desenvolver as histórias e ideias de outros autores. Desde então, iniciou sua própria editora. Caleb tem quatro filhos, a quem tem alegrado através dos anos com contos originais e recontagens de histórias bíblicas. Começa a batalha é sua primeira história em quadrinhos. Especificações do livro Bíblia em Ação Título: Bíblia em Ação Subtítulo: Começa a Batalha Autor(es): Sergio Cariello Ano de Edição: 2015 Capa: Brochura Acabamento: Laminação Fosca Miolo: Papel OffSer Páginas: 104 Dimensões: Altura: 23 cm Largura: 15,5 cm Profundidade: 0,4 cm Peso: 0,160 kg ISBN: 7897185853537 Editora: Geográfica', 25.41, 25.41, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9ks3lrodg6x10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F28536624914', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20197676469', 'Volante Esportivo Gti Emblema Logo Vermelho E Preto Palio Siena Strada Punto Stilo Ducato Doblo Uno', 'ESPECIFICAÇÃO TÉCNICA • Diâmetro de 370mm; • Profundidade de 120mm. MODELOS COMPATÍVEIS COMPATIBILIDADES: • Uno 1984 À 1994 • Elba 1985 À 1996 • Fiorino 1977 À 1994 • Premio 1985 À 1994 COMPATIBILIDADES: • Variações Fiat • Fiat Uno 1995 À 2000 • Fiat Elba 1995 À 2004 • Fiat Fiorino 1995 À 2004 • Fiat Tempra 1995 À 2001 • Fiat Tipo Nacional 1995 À 2001 COMPATIBILIDADES: • Fiat Uno Fire/Mille 2001 Em Diante • Fiat Palio 1996 À 2017 • Fiat Palio Weekend 1996 À 2017 • Fiat Marea 1998 À 2007 • Fiat Brava 1999 À 2003 • Fiat Idea 2005 À 2016 • Fiat Siena 1997 À 2021 • Fiat Strada 1998 À 2020 • Fiat Punto 2007 À 2017 • Fiat Stilo 2002 À 2010 • Fiat Ducato 1998 Em Diante • Fiat Doblô 2002 Em Diante • Fiat Fiorino 2005 Em Diante • Fiat Mobi 2016 Em Diante • Fiat Linea 2008 À 2017 IMPORTANTE • Garantia de 3 Meses; • Somos FABRICANTES ESPECIALIZADOS no segmento automotivo, seguimos um processo rigoroso de fabricação e qualidade; • Entrega ágil e rápida após sua compra; • Enviamos todos os nossos volantes com CUBO ADAPTADOR; • Após a instalação, perde-se a função AIRBAG; • RECOMENDAMOS QUE A INSTALAÇÃO SEJA FEITA POR PROFISSIONAL ESPECIALIZADO. • Fabricamos volantes em POLIURETANO RESISTENTE; • Nossos volantes possuem similaridade ao original com acabamento texturizado e acionamento da buzina. Sua satisfação é nossa maior recompensa! Estamos à disposição e teremos o imenso prazer em atendê-lo! ATENÇÃO: Certifique-se de que o anúncio seja compatível com seu veículo. Em caso de dúvida realize uma pergunta ANTES da compra.', 206.0, 169.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/br-1113420