INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6397756939', 'Caixa Bolo e Panetone Kraft 100g 10x10x10 com 10 un Assk Rizzo Confeitaria', '🎁 Caixa Panetone Branca 100G 15 cm Assk ideal para montar presentes e kits com uma apresentação elegante e diferenciada! O Caixa Panetone Branca 100G 15 cm Assk combina funcionalidade e qualidade, sendo uma excelente escolha para quem busca praticidade e um ótimo resultado no uso diário. Descrição Técnica: Produto: Caixa Panetone Branca 100G Modelo: 15 cm Assk Quantidade: 5 Unidades Marca: Pacote com 5 Unidades Dúvidas Frequentes: Quanto tempo leva o envio? ⏰ Todos os pedidos com etiqueta de envio liberado pela shopee até as 18hs são coletados no próximo dia útil pela transportadora Shopee Express. Qual o prazo de entrega? 🛵 A loja não tem acesso a parte logística da shopee. A Shopee não informa para a loja prazo de entrega. Ao clicar em comprar na opção envios é apresentado o prazo de entrega. O produto é novo? 😀 Sim. Só trabalhamos com produto novos e dentro da embalagem original do fabricante. Como faço para comprar mais de um item da loja? 🛍 No app ao lado do botão comprar tem o ícone de um carrinho de supermercado, clicando nele o produto será acrescentado no carrinho que fica na parte superior do app. Após acrescentar todos os produtos que gostaria é só clicar no carrinho e selecionar todos os itens e clicar em continuar. Comemore com Alegria: 🥰😀 Na Rizzo Distribuidora, a tradição e o encanto do nosso espaço físico no coração da 25 de março, em São Paulo, são cuidadosamente embalados para chegar até você. Permita-nos levar a magia de uma das lojas mais tradicionais da região diretamente para o conforto da sua casa ou empresa.', 28.9, 28.9, NULL, 'Stationery > Gift & Wrapping > Gift Boxes', 'https://cf.shopee.com.br/file/05b671a2a7e27fb23e1ae92d94eeba6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400124163%2F6397756939', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24742631862', 'Bíblia de Estudo King James | Atualizada | Full Collor | Capa Dura | Vintage', 'Bíblia de Estudo King James | Atualizada | Full Collor | Capa Dura | VintageA Bíblia de Estudo King James Atualizada, em capa dura e letra hipergigante, traz a tradução histórica e fiel que marcou a língua inglesa e a fé cristã. Com raízes na Inglaterra clássica, essa versão foi cuidadosamente elaborada por estudiosos selecionados pelo Rei James I, garantindo precisão e clareza. Uma obra que une tradição, impacto histórico e acessibilidade, permitindo que você mergulhe na Palavra de Deus com profundidade e inspiração. Palavras de Deus em Azul: Um toque especial para destacar a comunicação direta do Senhor.Palavras de Jesus em Vermelho: As preciosas palavras do Salvador em destaque vibrante.', 70.88, 63.74, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-822xe-moe27nfszzsw8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F24742631862', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
