INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19997631121', 'Kit Fácil Le Son Alto Falante 6 Polegada + Quadriaxial 6x9', 'Kit de falantes 6 polegadas + 6x9 polegadas Kit de som ideal para montar um som básico em seu carro, 2 falantes de 6" mais 2 falantes de 6x9" quadriaxiais. Excelente custo benefício, um dos kits mais baratos do mercado com boa qualidade. Nos falantes 6x9 o médio grave é bem evidente, deixando o som bem agradável. PAR ALTO FALANTE 6 POLEGADAS QUADRIAXIAL LESON LS6 140W AUTO Especificação Técnica: • Potência RMS: 70 Wrms (cada alto-falante) • Impedância Nominal: 4 ohms • Woofer de 6 Polegadas • Material: Cone Polipropileno PP • Borda emborrachada • Sensibilidade: 87 Db • Resposta de frequência: 37 a 20000Hz • Tweeter Piezzo • Bobina Simples PAR ALTO FALANTE 6X9 POLEGADAS QUADRIAXIAL LESON 140W Especificações Técnicas do Alto Falantes 6x9: • Potência RMS: 70 Wrms (cada alto-falante) • Modelo Quadraxial • Impedância Nominal: 4 ohms • Woofer de 6x9 Polegadas • Material: Cone Polipropileno BB • sensibilidade: 87 Db • Resposta de frequência: 37 a 20000Hz • Bobina Simples • Tweeter Piezzo • Borda Emborrachada • Cone com acabamento na cor cinza / preto Conteúdo da Embalagem: • 02 Alto Falante 6 Polegadas • 02 Alto Falante 6x9 Polegadas Importante:. • Valor do Kit. • Imagens Meramente Ilustrativas. • Não nos responsabilizamos pelo mau uso do produto.', 206.75, 206.75, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ls19keweqgis0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414508631%2F19997631121', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
