INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201806249', 'Chave Canivete Honda 3 Botões Positron Flex', 'Chave Canivete Honda 3 Botões Positron Flex A Chave Canivete Positron RPX070 foi desenvolvida especialmente para veículos Honda, oferecendo alto padrão de qualidade, funcionamento preciso e excelente durabilidade. Com design moderno e sistema de lâmina retrátil tipo canivete, proporciona mais praticidade no dia a dia e maior proteção ao conjunto. Possui 3 botões com resposta rápida e segura, ideal para substituição ou modernização da chave original, mantendo o padrão Positron de confiabilidade e acabamento. Características Técnicas: Modelo: RPX070 Marca: Positron Produto: Chave Canivete Automotiva Compatibilidade: Veículos Honda (verificar compatibilidade conforme modelo e ano) Botões: 3 botões Material: Plástico ABS de alta resistência Uso: Automotivo Diferenciais: Produto Positron de alta qualidade Design exclusivo para linha Honda Sistema de abertura tipo canivete Botões com acionamento macio e preciso Excelente acabamento Vantagens: Mais praticidade no uso diário Maior durabilidade e resistência Visual moderno e compacto Ótimo custo-benefício Ideal para: Indicado para proprietários de veículos Honda que desejam substituir ou atualizar a chave original do veículo, mantendo padrão de qualidade, segurança e confiabilidade.', 94.1, 94.1, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Ignition', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi4lmlqj6ghvd4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946086188%2F58201806249', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
