INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254761126', 'Power Bank Portátil 10000mAh Carregamento Rápido 20W, 3 Cabos Integrados, Display Digital -A6', 'Power Bank 10000mAh com Cabos Embarcados – 4 Saídas, Carga Rápida, Compacto e Portátil DESCRIÇÃO: O Power Bank 10000mAh vem com 3 cabos embutidos (USB-C, Micro USB e USB-A) + 1 cabo extra para recarregar, permitindo carregar diversos dispositivos sem necessidade de cabos adicionais! Perfeito para viagens, trabalho e dia a dia. 🔋 Bateria de alta capacidade – 10000mAh, ideal para celulares, tablets e dispositivos inteligentes. ⚡ Carga rápida 10W – Corrente máxima de 2.1A para recarregar seus aparelhos com eficiência. 🎒 Portátil e prático – Leve, compacto e sem preocupação com cabos extras. 🔌 3 entradas + 4 saídas – Compatível com a maioria dos dispositivos. 📌 DETALHES: ✔ Cabos incluídos: USB-C + Micro USB + USB-A (embutidos) + 1 cabo extra para recarga ✔ Saídas: 4 portas (carga simultânea para vários dispositivos) ✔ Cor: Enviada aleatoriamente (cores variadas) ✈️ Leve para qualquer lugar – Nunca fique sem bateria! Por que escolher este Power Bank? ✅ Prático: Cabos embutidos evitam perder ou esquecer fios. ✅ Versátil: Funciona com smartphones, tablets, fones Bluetooth e mais. ✅ Compacto: Design leve e fácil de carregar. ✅ Ideal para viagens: Leve na mochila ou bolso. ⚠️ ATENÇÃO: As cores são enviadas aleatoriamente (estoque variado). Garanta já o seu e nunca mais fique sem bateria! 🔋📱 #Carregador Portátil #Banco de energía digital LED', 200.0, 65.99, NULL, 'Mobile & Gadgets > Accessories > Powerbanks & Batteries', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mkdhan4k6xoi6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1721810104%2F58254761126', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
