INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599715911', 'Cobertura Fracionada Mais Sabor Chocolate Ao Leite 2,05kg SICAO', 'Cobertura Fracionado Sabor Chocolate ao Leite da Sicao traz o verdadeiro sabor do chocolate, contém liquor de cacau em sua formulação, e a presença de leite a torna mais cremosa. Tem excelente fluidez, brilho marcante e o melhor rendimento do mercado. Ideal para produções de coberturas em bombons, trufas, pães de mel e muito mais. Cremosidade e sabor diferenciado, os Chocolates Sicao encanta a todos os paladares, inclusive os mais exigentes. Fabricado no Brasil, porém com a tradição e qualidade única da Barry Callebaut. Ingredientes: açúcar; gordura vegetal; cacau em pó processado com álcali; leite em pó desnatado; pasta de cacau; emulsificante: lecitina de soja;emulsificante: triestearato de sorbitana; emulsificante: poliglicerol polirricinoleato; aromatizante. ALÉRGICOS : CONTÉM DERIVADOS DE LEITE, DERIVADOS DE SOJA. CONTÉM LACTOSE. NÃO CONTÉM GLÚTEN.', 94.64, 89.91, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-7rfi5-m9hpplox7h1x56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F20599715911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
