INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53651365063', 'Pasta Americana Morango para Bolo 800g Arcolor', 'Pasta Americana branca da Arcolor é uma ótima opção para a decoração e revestimento de seus bolos de corte ou fake, biscuits e até detalhes em seus doces finos. Trata-se de uma pasta americana já pigmentada e saborizada, perfeita para facilitar seu dia a dia, com uma maleabilidade e cobertura impecável. Sabor: morango. Cor: branca. Ingredientes: Açúcar Refinado, gordura vegetal, gomas vegetais e xarope de glucose. Contém Estabilizante EP III e Conservantes P IV. Aromatizado Artificialmente. NÃO CONTÉM GLUTEN. Tabela Nutricional - Porção de 30G (1 colher de sopa): Valor Calórico: 118kcal/495kj; Carboidratos: 26; Proteínas: 0g; Gorduras Totais: 2g; Gorduras Saturadas: <1g; Gorduras Trans: 0g; Fibras: 0g; Sódio: 2mg.', 43.07, 31.87, NULL, 'Food & Beverages > Baking Needs > Baking Decoration', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh0uok5g7q4kf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F53651365063', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298951722', 'Usado: Moto g53 128GB Grafite Excelente - Trocafy - Motorola', 'Celular Seminovo Trocafy A Trocafy é especializada na venda de celulares Recondicionados (Seminovos). Aqui todos os aparelhos passam por revisão minuciosa de técnicos especializados e certificados pelos fabricantes para reparo. Condições: Excelente: Aparelhos com pouquíssimos sinais de uso, risco e/ou arranhões quase imperceptíveis tanto na tela quanto tampa traseira; Muito Bom: Aparelho com alguns sinais de uso como arranhões, riscos e/ou amassados na lateral perceptíveis, porém leves, tanto na tela quanto tampa traseira; Bom: Aparelhos com sinais de uso nítidos/visíveis tanto na tela quanto na tampa traseira como por exemplo: riscos, arranhões, pequenos amassados e manchas na tela. Bom Bateria 70%:Aparelhos com sinais de uso nítidos/visíveis tanto na tela quanto na tampa traseira como por exemplo: riscos, arranhões, pequenos amassados e manchas na tela. Mínimo da bateria é 70%. IMPORTANTE: - Trabalhamos apenas com PEÇAS ORIGINAIS. Não utilizamos peças alternativas ou paralelas; - Aparelhos DESBLOQUEADOS para todas as operadoras e homologados pela ANATEL; - IMEI verificado garantindo originalidade e procedência legal do aparelho; - Por serem usados, os aparelhos não são resistentes a água (IP68/IP67); - Não acompanha acessórios; - NOTA FISCAL - Emitida em nome do comprador; GARANTIA - Aceita devoluções por arrependimento em até sete (7) dias corridos após o recebimento do pedido. Oferece 90 dias de garantia contra defeitos técnicos. CONTEÚDO EMBALAGEM: Aparelho adquirido em uma caixa personalizada da Trocafy;', 799.0, 759.05, NULL, 'Mobile & Gadgets > Mobile Phones', 'https://cf.shopee.com.br/file/sg-11134201-825ap-meygq23ci4na63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br