INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202532716', 'Kit de Carregamento Turbo com Estojo USB-C 33W Vermelho | Grifinória Harry Potter', 'Seja para o dia a dia ou para acompanhar você em viagens, o Kit de Carregamento Grifinória da iWill é ideal para manter seus dispositivos sempre carregados. Compatível com aparelhos que possuem entrada USB-C, ele oferece carregamento rápido para celular, tablet, fone de ouvido e outros gadgets. O conjunto inclui uma bolsinha de transporte com divisórias extras, perfeita para guardar o carregador rápido de 33W e um cabo trançado duplo de até 60W com duas pontas USB-C, e até um fone de ouvido. E para todos os fãs que sempre sonharam em receber a carta de admissão, o kit acompanha a tão desejada carta para mergulhar no mundo mágico de Harry Potter. Especificações: Carregador Potência de carregamento rápido: 33W (máx) Entrada: 100–240V (50/60 Hz) Saída: 5V/3A, 9V/3A, 11V/3A, 12V/2.5A, 15V/2A, 20V/1.5A Proteção quádrupla: OCP, OVP, OTP e SCP Certificação ANATEL Cabo Conectores USB-C em ambas as pontas Comprimento: 1,2 m Suporte a transferência de dados Corrente de 3A Bag Divisória interna e espaço extra para acessórios Zíper metálico dourado reforçado Acompanha carta de admissão de Hogwarts Garantia de 2 anos contra defeitos de fabricação. A garantia engloba os 3 meses de Garantia Legal. Imagens ilustrativas. As cores podem variar de acordo com o monitor ou lote de fabricação.', 299.0, 179.9, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/br-11134207-81ztc-miuy8xz1b3lva0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1013839557%2F58202532716', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
