INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997463587', 'Livro Boa garota, segredo mortal - Série Manual de assassinato para boas garotas Vol. 2, por Holly Jackson - Intrínseca', 'Livro Boa garota, segredo mortal - Série Manual de assassinato para boas garotas Vol. 2, por Holly Jackson - Intrínseca Na sequência do best-seller Manual de assassinato para boas garotas, um desaparecimento misterioso abala Little Kilton Um ano após a investigação obsessiva que reescreveu a história de sua pacata cidade, Pip acredita que seus dias de detetive amadora chegaram ao fim. Prometendo nunca mais se envolver no emaranhado de segredos de Little Kilton, a garota planeja lançar um podcast sobre a resolução do caso e voltar a ter uma vida normal. Até que algo terrível acontece, e ela precisa quebrar sua promessa. Jamie Reynolds, o irmão de um de seus melhores amigos, está desaparecido. Ele foi visto pela última vez no memorial dedicado a Andie Bell e Sal Singh, seis anos após o crime. Seria mera coincidência? Quando a polícia se recusa a agir, Pip decide voltar à ativa. Com a ajuda dos amigos, dos ouvintes do podcast e de Ravi, ela se lança em uma busca frenética para encontrar Jamie antes que seja tarde demais. Cada segundo conta, e só resta uma certeza: ninguém em Little Kilton é quem diz ser. Nessa trama afiada, os efeitos da primeira investigação de Pip se misturam com um novo mistério arrepiante. E ela está disposta a correr riscos ainda maiores em sua busca pela verdade. Na sequência de Manual de assassinato para boas garotas, Holly Jackson constrói mais um thriller surpreendente, profundo e impossível de largar. Sobre a autora: Holly Jackson escreve desde jovem, tendo terminado seu primeiro (e terrível) romance aos quinze anos. Ela se tornou autora best-seller do New York Times com sua série de estreia, Manual de assassinato para boas garotas. É formada na Universidade de Nottingham, onde estudou Linguística Literária e Escrita Criativa, e tem um mestrado em Língua Inglesa. Atualmente, mora em Londres. Holly gosta de jogar videogame e assistir a documentários sobre crimes reais para fingir que é uma detetive. Detalhes do Livro: Tradução: Karoline Melo Páginas: 432 Gênero: Literatura Juvenil Formato: 14 x 21 x 2,1 cm Peso: 460 Gramas Tipo de capa: Brochura Lançamento: 03/10/2022', 69.9, 55.92, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lu6vfjxugyok89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F22997463587', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098971053', 'Esteira 1,5m x 2,00m em Polipropileno - Verde', 'As Esteiras de Praia Casal PP Dobráveis Mor foram feitas para aqueles que gostam de tomar sol com muito estilo! Produzidas em polipropileno com acabamento em TNT e alça em poliéster, são confortáveis ao deitar, impermeáveis, laváveis, de rápida secagem e resistentes. Leves e práticas de carregar são super espaçosas, medindo 1,50m x 2m, perfeitas para até duas pessoas utilizarem ao mesmo tempo. Fechadas, se transformam em uma simpática bolsinha que ocupa pouco espaço, podendo ser carregada pelas alças ou guardada na sua bolsa de praia. A Esteira Dobrável Casal é listrada com quatro opções de cores para você escolher: pink, verde, turquesa e azul.', 68.0, 68.0, NULL, 'Travel & Luggage > Others', 'https://cf.shopee.com.br/file/sg-11134201-824g3-mfb9ny2unuhbd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F22098971053', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
