INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210758571', 'Shampoo Oleosidade? Nunca nem vi! 500ml Oh My | Equilíbrio e leveza para cabelos oleosos', '- Pra cabelos oleosos - Equilíbrio e leveza - pH 6.0 - Sem corantes |sem parabenos Cabelo oleoso na raiz e ressecado nas pontas? A gente entende o seu drama, e é por isso que a linha Oleosidade? Nunca nem vi! tá aqui pra te salvar! Sua formulação incrível contém algas marinhas e chá verde, que deixam os fios limpos, soltinhos e com as pontas hidratadas. O nosso shampoo faz uma super limpeza, sem ressecar! O que os nossos ativos fazem: • Algas marinhas: limpam, recuperam o brilho natural e não deixam a hidratação ir embora! • Chá verde: é rico em antioxidantes, controla a oleosidade e purifica os fios! MODO DE USAR: é muito fácil! Molhe o cabelo, coloque uma quantidade suficiente do shampoo, massageie e relaxe. Depois, enxágue até retirar tudinho. Se necessário, faça de novo. Quer um resultado ainda mais incrível? Use toda a Oleosidade? Nunca nem vi! Oh My!', 34.9, 34.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-822wt-moa1a3aax6a4ed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1809761118%2F58210758571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251560059', 'CÂMERA IP INTERNA | Segurança Inteligente Wi-Fi Full HD 3MP', 'CÂMERA IP INTERNA | Segurança Inteligente Wi-Fi Full HD 3MP Wi-Fi Full HD 1080P 2,8mm 3MP，foi desenvolvida para cuidar de sua residência e sua família mesmo quando você estiver ausente. Todo o controle necessário estará nas suas mãos, em qualquer lugar, através do smartphone, desde a instalação e gravação até o recebimento de notificações. O equipamento identifica e diferencia a presença de pessoas, enviando uma notificação para seu celular sempre que um visitante chegar no local, seja na sua residência ou escritório. Possui ainda sirene interna, que dispara em caso de invasão. E graças à inteligência artificial integrada, a câmera detecta barulhos no ambiente, para que você receba alertas e fique de olho em tudo de onde estiver. E pode ter a certeza de visualizar sempre com ótimos detalhes, afinal, o campo de visão da Câmera é de 131°, e aliado aos sensores de alta tecnologia, captura imagens claras mesmo no escuro. - Wi-Fi - Resolução Full HD (1080p) - Zoom Digital 8x - Ângulo de visão 131° (diagonal), 112° (horizontal), 58° (vertical) - Alerta de Ruído - Áudio bidirecional / interação por voz: veja, ouça e fale com quem está no ambiente monitorado - Lente 2.8mm - Alcance IR 10 m - IR inteligente - Detecção de movimento ajustável - Local de instalação: espaço interno - Temperatura de operação: -10 °C a 45 °C - Umidade relativa de operação: 95% ou menos (sem condensação) - Padrões Wi-Fi: IEEE802.11b, 802.11g, 802.11n - Frequência Wi-Fi: 2,4 GHz ~ 2,4835 GH - Largura de banda: 20/40 MHz - Segurança WPA, WPA-PSK, WPA2, WPA2-PSK, WEP 64 bit & 128 bit - Potência de transmissão b: 17 dBm, g :17 dBm, n :15 dBm - Taxa de transmissão: 802.11b: 11 Mbps, 802.11g 54 Mbps, 802.11n 130 Mbps - Ganho da antena: 2,84 dBi (interna) - Frame Rate Adaptável (máximo de 20 FPS) - Compressão de vídeo: H.264 (perfil principal) - Taxa de bits para vídeo Adaptável - Áudio bidirecional: Sim - Compressão de áudio: AAC - Taxa de bits para áudio: Adaptável - Método de configuração: Modo AP - Gravação em nuvem (serviço contratado separadamente) - Consumo máximo de corrente: 0,62 A - Consumo máximo de potência: 3,1 W - Frequência de operação: 50/60Hz - Fonte de alimentação: entrada: 100Vac a 240Vac Saída: 5 V/1 A. - Dimensões: Altura 10,9cm; Largura 6,6cm; Comprimento 3,3cm - Peso: 0,102kg', 350.0, 99.0, NULL, 'Cameras & Drones > Security Cameras & Systems > CCTV Security Cameras', 'https://cf.shopee.com.br/file/br-11134201-820lb-mqyqf25jp9mu4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1655406395%2F58251560059', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
