INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497711371', 'Fita Dupla Face de Espuma 3M VHB IG-110WF 19MM X 5M', 'Fita Dupla Face VHB fácil de usar e com ótima adesão, praticamente invisível nas superfícies Oferece alta resistência e durabilidade a longo prazo Substitui rebites, soldas a ponto, adesivos líquidos e outros fixadores mecânicos ou permanentes Alta resistência a solventes Cria um selo permanente contra água e umidade Compensa a dilatação térmica das partes unidas, proporciona distribuição do esforço mecânico e possui colagem permanente sempre com acabamento limpo A Fita 3M VHB Dupla-Face de Espuma IG-110WF, na cor branca, é adequada para fixação de chapas metálicas em ônibus, placas de sinalização, montagem em materiais de linha branca, entre outros. Esta fita de adesivo acrílico e núcleo de espuma firme para uso geral é ideal para utilização em muitos ambientes industriais internos ou externos, substituindo rebites, soldas a ponto, adesivos líquidos e outros fixadores mecânicos ou permanentes. Pode ser usada em vários substratos, como alumínio, aço galvanizado, inox, aço pintado, vidro, epóxi, cerâmica e muitos outros.', 59.9, 59.9, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-7rdxr-lyy2ofsxvf9j8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328711923%2F23497711371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
