INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9528616887', 'Alto Falante Hurricane 6 Polegadas New Class 130w Rms Cm6', 'Se você quer um equipamento de som que traga muito mais desempenho para ouvir suas músicas com qualidade, aposte nesse Par de Alto falantes da Hurricane, com potência máxima de 130W RMS. Com o tamanho ideal para ser instalado no seu carro ele vai promover a maior festa, os alto falantes são no modelo quadriaxial e possuem 6 polegadas de diâmetro. Você vai ter um sistema de som de alto nível, contando com resposta de frequência de 80Hz a 22 KHz e sensibilidade de 89dB. Feito para durar muito mais, ele conta com carcaça injetada e borda em borracha Surround. Além disso, seu design é moderno e diferenciado, contando com as cores preta e azul, perfeito para incrementar o estilo do seu carro. Especificações Técnicas: - Modelo: Class CM6 - Diâmetro Nominal: 6 Polegadas - Potência RMS: 65W RMS (Cada) - Potência Wmax: 130W (Cada) - Impedância Nominal: 4 Ohms - Modelo Quadriaxial - Resposta de Frequência: 80Hz a 22Khz - Sensibilidade: 89dB - Na Cor Preta com Azul - Bobina Simples - Cone Injetado em Polipropileno - Borda em Borracha Surround - Tweeters Piezo - Diafragma de Mylar - Carcaça Injetada - Fácil Instalação - Altura Aproximada do Ímã: 1,4cm - Dimensões Aproximadas (DxP): 16,5x5,5cm Conteúdo da Embalagem: - 02 Alto Falantes', 135.66, 120.62, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/e5fb27dceaa6a9b2e4b7490a20b840e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F9528616887', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18626239535', 'Capa Cobrir Moto Proteção Chuva Sol Poeira Honda Nxr Bros', 'PREÇO DE FABRICA, QUEIMA DE ESTOQUE, GARANTA A SUA PORQUE VAI ACABAR. Capa para Cobrir Motocicleta 100% Impermeável e sem forro, protege contra sol, chuva , poeira, risco e sujeira de animais ou aves. Ideal para quem quer conservar a pintura da sua moto. Nas borda da capa possui elásticos que deixa a capa bem presa a moto. Fabricada com material de alta qualidade que oferece maior resistência e durabilidade, impede qualquer tipo de dano na pintura. Para escolher o tamanho ideal para sua moto, siga a tabela de medidas que se encontra nas fotos do anuncio. Atendimento De Qualidade | 100% Seguro | Satisfação Garantida Informações técnicas: Produto: Novo Tamanho: Universal P M G Cor: Cinza Forração: Sem Forro Aplicação: Motos Edição PREMIUM Especificações: - Não Risca a Pintura - 100% Impermeável - Utilização em Garagens Cobertas e Descobertas - Protege sua Motocicleta do Sol, Chuva e Poeira - Máxima Proteção Contra os Raios U.V. - Protege a Moto por Completo - Fixação Firme com Elástico nas Bordas - Fácil Instalação - PRODUTO PREÇO DE FABRICA ------------------------------------------------------------- Itens inclusos: 1 Capa | Cor: Cinza | ------------------------------------------------------------- Obs: Não nos responsabilizamos por mal uso.', 64.33, 64.33, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Covers', 'https://cf.shopee.com.br/file/503d645b342440bfe26ee7c748c33756', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F18626239535', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793211856', 'Não abra este livro... Nunca', 'Este livro é para minha mãe e meu pai (mais conhecidos como Momu e PaMick para seus netos) e para todos os avós por aí. Vocês são os melhores. Obrigado por tudo e saibam que estaremos ao seu lado enquanto vocês continuarem envelhecendo graciosamente.', 27.65, 27.65, NULL, 'Books & Magazines > Books > Education & School', 'https://cf.shopee.com.br/file/sg-11134201-7rdxy-lytw9399bfgnd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23793211856', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597083397', 'As aventuras de Mike - Outro Planeta', 'Sabe aquele garoto popular da escola? Que é descolado se veste bem e faz sucesso com as garotas? Pois é, esse com certeza não é o Mike. Na verdade, o Mike é exatamente o contrário de tudo isso! Ele é desastrado, prefere videogames e salgadinhos no lugar de futebol, e é PÉSSIMO com as garotas. Ao lado do seu fiel amigo Nando (que é o ser humano mais distraído do planeta Terra) vão se aventurar em uma competição de biscoitos em busca de um misterioso prêmio que irá mudar suas vidas para sempre. “Este é o melhor livro de todos os tempos”. Mike “É impossível parar de ler”. Nando', 60.43, 60.43, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7r9c8-ln7c2jyi8qb988', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23597083397', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40412675695', 'Serial killers - Astral Cultural', 'Qual é a linha tênue entre um pensamento perturbador e a ação? Jeffrey Dahmer, Ted Bundy, o Maníaco do Parque... é Extensa a lista de nomes de assassinos em série que ganharam notoriedade na mídia nas últimas décadas. Cada caso tem sua particularidade: A escolha das vítimas, as armas utilizadas, a cena do crime e, principalmente, a motivação. Buscar as raízes dos comportamentos e dos transtornos de personalidade desses possíveis indivíduos é o ponto chave dessa discussão para entender o que os move a cometer esses crimes O que você vai encontrar aqui: • Como funciona a mente de um serial killer • Principais aspectos e características • Teorias existentes para explicar o comportamento • O fascínio e a repulsa que causam na sociedade • Mitos e verdades sobre o tema.', 25.38, 25.38, NULL, 'Books & Magazines > Books > Psychology & Relationships', 'https://cf.shopee.com.br/file/sg-11134201-7rdxg-mddr63az447oc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F40412675695', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
