INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698726844', 'Kit - 6 Colheres De Sobremesa Ipanema Com Lâmina Em Aço Inox Cabo Preto Csptop - Tramontina', 'Kit - 6 Colheres De Sobremesa Ipanema Com Lâmina Em Aço Inox Cabo Preto Csptop - Tramontina MUITO IMPORTANTE: -- CONFERIR PRODUTOS NO ATO DO RECEBIMENTO. NÃO ACEITAR PRODUTOS COM EMBALAGEM VIOLADA (AMASSADO, RASGADO, ABERTO, QUEBRADO, ETC), A RECUSA DEVE SER FEITA NO ATO. 6 Colheres de Sobremesa Ipanema Com Lâmina Em Aço Inox Cabo Preto Csptop - Tramontina 23366400 Mais praticidade e qualidade na hora de comer aquele doce delicioso com a Colher para Sobremesa Tramontina Ipanema com Lâmina em Aço Inox e Cabo de Polipropileno Preto. Fácil de limpar, ela ainda pode ser lavada na máquina de lavar louças, otimizando sua rotina na cozinha. A escolha perfeita para deixar a hora da sobremesa mais clássica e elegante! - A lâmina de aço inox garante maior resistência devido a espessura do aço e a estampagem da lâmina. - O cabo de polipropileno possui maior resistência e durabilidade. - Pode ir à máquina de lavar louças facilitando seu dia a dia. - Garantia de 90 dias para vícios ou defeitos de fabricação. Tamanho da embalagem: 3cm A x 13cm L x 20cm P Peso: 0,180kg Cor: Preto | Selecione: Colher de sobremesa | Tipo de Talher: Colher', 20.94, 20.94, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/sg-11134201-7rdya-mcc3lwnwyz5dc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23698726844', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50908884741', 'Alicate Bico Meia Cana Curvo 6 Pol Aço Polido 1 Peça Nove54', 'O Alicate Bico Meia Cana Curvo 6" Nove54 é indicado para o manuseio de terminais, fios e cabos elétricos não energizados, especialmente em locais de difícil acesso. Seu formato curvo facilita o alcance em áreas estreitas, sendo ideal para eletricistas, instaladores e profissionais de manutenção. Fabricado em aço carbono, possui acabamento polido que proporciona maior resistência e durabilidade. Conta com função corte integrada, mordentes com pontas estriadas para melhor fixação e parte central côncava que auxilia na manipulação de peças cilíndricas. Com 6 polegadas (152 mm) de comprimento total, é compacto e eficiente para trabalhos de precisão. Características: Marca: Nove54 Modelo: Meia cana curvo Referência: 3662006200 Material do corpo: Aço carbono Acabamento: Polido Tipo de cabo: Sem isolação Comprimento total: 6" (152 mm) Massa aproximada: 0,183 kg Benefícios: Formato curvo ideal para locais de difícil acesso Função corte integrada Mordentes estriados para melhor fixação Estrutura resistente em aço carbono Conteúdo da embalagem: 1 Alicate.', 54.38, 41.67, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-81zux-mn2zar0rw2ko80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F50908884741', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097996489', 'Serra Circular 7.1/4'' Scv 1400 127V Vonder', 'Serra circular 7.1/4" SCV 1400 127 V~ VONDER Possui ajuste de profundidade de corte e regulagem de ângulo de até 45°. Indicada para cortar somente madeiras e derivados. Especificações: Modelo: SCV 1400 Tensão (V): 127 V~ Diâmetro da serra indicada: 7.1/4" - 185 mm Potência: 1.400 W Frequência (Hz): 50 Hz / 60 Hz Rotação (rpm): 5.000/min Ângulo de inclinação da serra: Base com inclinação de até 45º Capacidade de corte 45°: 50 mm Capacidade de corte 90º: 62 mm Diâmetro do eixo: 20 mm Incerteza da aceleração transmitida nas mãos - braços do operador - k: 1,5 m/s² Aceleração transmitida nas mãos - braços do operador - ah: 4,73 m/s² Segue norma: ABNT NBR IEC 60745-1 e ABNT NBR IEC 60745-2-5 Massa aproximada (peso) (kg): 5.308 kg Conteúdo da Embalagem: 1 Serra circular. Acompanha: 1 punho auxiliar, 1 guia de corte lateral, 1 chave tipo "T" e 1 lâmina de serra circular.', 745.06, 562.19, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7renx-m1y5v4aegkkdf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23097996489', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
