INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999368261', 'Cama Fun Safari e Zoológico Solteiro', 'A Cama Carro Solteiro conta com adesivagem nos painéis, com design moderno e direcionado para o conforto, bem-estar e segurança da criança, conferindo um ambiente alegre, colorido e divertido. Bordas arredondadas evitando riscos de acidentes, adesivos em vinil de alta qualidade e resistência. Produzida em 100% em MDF PESO SUPORTADO: 90 KG TAMANHO DA CAMA: SOLTEIRO PARA CRIANÇAS A PARTIR DE 6 ANOS APROX. TAMANHO IDEAL DO COLCHÃO: COLCHÃO INDICADO NO TAMANHO DE 14X88X188 CM COLCHÃO NÃO INCLUSO. Dimensões da Cama: Altura: 45,5 cm Largura: 91,5 cm Profundidade: 197 cm Informações da Cama: Cor da Cama: Branca Tema do Adesivo: Safari e Zoológico Material Principal: MDF Peso Suportado: 90 Kg Acompanha Colchão: Não Itens Inclusos: 1 Cama Solteiro Manual de Montagem Kit completo para montagem e manual de instruções Garantia: 3 meses contra defeito de fabricação Informações Adicionais: - Fotos meramente ilustrativas do produto no ambiente. - Os objetos que ambientam as fotos não acompanham o produto; - Verificar descrição e tamanho do produto antes da compra. - Avaliar a mercadoria no ato do recebimento e recusar em caso de divergência ou avarias. - Mantenha as informações de contato e endereço de entrega atualizados para entrarmos em contato caso necessário. - Limpar com flanela ou pano macio seco, não utilizar produtos abrasivos, desengordurantes, álcool ou solvente. Não expor o produto diretamente à luz solar e à umidade. * Sugerimos a contratação de um montador profissional para a montagem do produto. Não nos responsabilizamos por avarias causadas no ato da montagem. * Não nos responsabilizamos pela montagem e desmontagem do produto no ato da entrega e devolução, assim como os custos gerados nestas situações. * A transportadora entregará o produto no andar térreo do endereço de entrega. * Não nos responsabilizamos por subir escadas, corredores e elevadores ou transporte por guincho em apartamentos.', 850.99, 587.19, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rdwq-m0lr4y2gdefief', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F451273707%2F19999368261', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
