INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693063457', 'Pelucia boris gg - Imaginarium', 'Coloridos, fofos e com personalidade própria, nossos Mascotinhos chegaram para proporcionar altas doses de fofura (sem moderação)! Pensando nisso, Bóris, o gatinho antissocial mais fofo que você já viu, está aqui para ser o seu mais novo xodozinho! Mal-humorado e ranzinza, ele é do tipo que adora passar as tardes deitado no sofá e só vai a uma festa se tiver lugar para sentar! Contém 1 pelúcia. Tecido: 100% poliéster. Enchimento: 100% poliéster. Medidas: 50 cm x 43 cm. Limpar com pano levemente umedecido nas áreas sujas. Teme químicos e abrasivos. Validade indeterminada.', 377.0, 377.0, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rd3p-lw3e5hhoqa21a8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F789092088%2F22693063457', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
