INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993538436', 'DICIONÁRIO DAS RELAÇÕES ÉTNICO RACIAIS CONTEMPORÂNEAS', 'DICIONÁRIO DAS RELAÇÕES ÉTNICO RACIAIS CONTEMPORÂNEAS Obra de referência, pioneira em realizar o intento de ter especialistas brasileiros e latino americanos exclusivamente pertencentes aos grupos mais histórica e socialmente discriminados (negros, mulheres, indígenas, judeus) abordando a discriminação, os racismos e as relações étnicas em nosso país, por meio de 53 artigos que abrangem um amplo espectro de temas, de Afrocentricidade a Xenofobia, passando por movimento negro, feminismos, genocídio, cultura negra, islamofobia, perigo amarelo etc.. Informações Adicionais Autor: ALEX; SANTOS, MARCIO ANDRÉ DOS Data Publicação: 15/10/2023 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: DICIONÁRIO DAS RELAÇÕES ÉTNICO RACIAIS CONTEMPORÂNEAS Idioma: INDEFINIDO Páginas: 336 Edição: 1 ISBN-13: 9786555051575 ISBN-10: 6555051574', 99.9, 81.92, NULL, 'Books & Magazines > Books > Psychology & Relationships', 'https://cf.shopee.com.br/file/sg-11134201-7rd6p-luhikum8pak027', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23993538436', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
