INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21697980703', 'Filtro de Ar Fluo 125 2022 A 2025 Eksim', 'Filtro de Ar - Eksim Os filtros Eksim seguem os padrões das peças originais, utilizando tecnologia de ponta e materiais de altíssima qualidade. Compatível com: YAMAHA FLUO 125 2022 FLUO 125 2023 FLUO 125 2024 FLUO 125 2025 Vantagens: - Motor limpo (Livre de impurezas que possam comprometer o seu funcionamento de forma prematura) - Economia de combustível. O Filtro de ar Eksim é projetado com todas as características necessárias para o excelente funcionamento do motor, barrando quaisquer impureza e deixando livre apenas a passagem de ar necessária para a melhor potência do motor com maior durabilidade. Especificações Técnicas: - Qualidade em elementos filtrantes, desenvolvido para motores de alto desempenho; - Proporciona Melhor Queima de Combustível e Ajuda a Diminuir a Emissão de Gases Poluentes - Filtro Seco - Rigido - Oferece Menor Desgaste dos Componentes Internos do Motor - Maior Durabilidade e Qualidade de Filtração - Filtro de alto padrão desenvolvido com elementos filtrantes que equivalem as características técnicas exigidas pelos fabricantes de motocicletas - Fluxo de ar: Compatível com a especificação do fabricante - Não Lavável Importante: - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 54.9, 43.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7repd-m2r4nc10duyh77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F21697980703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
