INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43875759440', 'Prancha Para Pilates e Abdominal Multifuncional 9 em 1 | Treino Completo, Dobrável, Portátil', 'Transforme sua casa em um estúdio particular de Pilates com nosso completo e compacto aparelho reformer de Pilates. Nosso design dobrável garante um armazenamento prático, permitindo que você se exercite sempre que desejar. Nosso temporizador inteligente e suporte para celular facilitam o acompanhamento do progresso do seu treino e mantêm você motivado durante toda a sessão. O temporizador de contagem regressiva integrado ajuda a gerenciar com precisão a duração do treino, enquanto o suporte para celular permite que você assista facilmente a vídeos com instruções de exercícios físicos durante o treino, aprimorando sua experiência. Com um sistema de resistência ajustável, o aparelho reformer de Pilates é adequado para todos os níveis de condicionamento físico, permitindo que você treine com segurança e conforto de acordo com suas necessidades individuais. Faça seu pedido agora para elevar o nível do seu treino diário! Especificações Técnicas: • Modelo: Core Multifuncional • Função: Exercitador abdominal e prancha de pilates • Uso: Residencial • Material: Estrutura em aço e plástico resistente • Recursos: Trilho deslizante com apoio de joelhos, manoplas com espuma, níveis de inclinação ajustáveis • Tipo de exercício: Core, braços, pernas, glúteos • Dobrável: Sim • Portátil: Sim • Fácil de montar e guardar', 699.0, 179.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg7kpmss16o49c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1063922972%2F43875759440', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
