INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17263301648', 'Devocional Diário De Oração Tudo Para Ele Feminino 365 dias', 'Este Diário de Oração – Tudo para Ele, em design delicado e cativante, totalmente, voltado ao público feminino, contém o mesmo texto do reconhecido clássico de Oswald Chambers Tudo para Ele (Publicações Pão Diário, 2015). Este é um dos livros de meditação diária mais conhecidos e amados do mundo. Desde sua primeira publicação, em 1927, muitas pessoas têm sido transformadas por este conteúdo.Esta edição apresenta:Um devocional por diaEspaço para anotação das verdades bíblicas aprendidasEspaço para que se anote as reflexõesEspaço para anotar pedidos e respostas de oraçãoPáginas: 384', 33.99, 33.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/2888685c3f6c219449db7fa96842cd96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F17263301648', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097764420', 'Bíblia Sagrada The Purpose Book | A21 | Espaço Para Anotações | Capa Soft Verde', 'A bíblia The Purpose Book celebra a beleza das maravilhas de Deus em cada detalhe: da capa às ilustrações que abrem cada livro, passando pelas cores, texturas e ferramentas de leitura. Intencionalmente desenvolvida para que você se expresse enquanto medita na Palavra de Deus, ela conta com espaço para anotação pautado, a tradução Almeida Século 21, planos de leitura, guia para anotação do texto bíblico e muito mais!A The Purpose Book é perfeita para leitura bíblica, devocionais, journaling, anotações, orações e estudo. - Guia de uso com dicas para usar o espaço de anotações e as demais ferramentas da Bíblia. - Plano de leitura bíblica personalizado para que você organize sua leitura considerando suas necessidades atuais e quais livros deseja priorizar. - Plano de leitura bíblica de 365 dias para quem deseja ler a Bíblia de A a Z em um ano. - Plano de leitura bíblica cronológico trianual para quem prefere ler com tranquilidade, seguindo a ordem cronológica. - Introduções às categorias de livros que ajudam você a entender os grupos bíblicos (como Pentateuco, Livros Históricos, Evangelhos, etc) e a saber em que terreno está pisando. - Ilustrações exclusivas na abertura de cada livro da Bíblia, que apontam como o Senhor Jesus Cristo foi revelado naquele livro. - Ferramenta de estudo logo após a ilustração, que incentiva você a identificar temas centrais, versículos - chave e outras informações acerca de cada livro da Bíblia. - Texto bíblico com espaço para anotação para ser usado como quiser! Detalhes: Título: Bíblia Sagrada The Purpose Book | A21 | Espaço Para Anotações | Capa Soft Verde Editora: Thomas Nelson Brasil Versão: Almeida Século (A21) Índice: Não Fitilho: Sim Palavras de Jesus em Vermelho: Não Dimensões: 23,5 x 15,9 cm Paginas: 1760 Acabamento: Luxo', 257.31, 257.31, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdxy-lzqkn8k82oqf7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F22097764420', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393253132', 'A teologia do livro de Apocalipse | Richard Bauckham', 'A teologia do livro de Apocalipse | Richard Bauckham Um clássico da teologia bíblica sobre uma das mais intricadas obras literárias do novo testamento Apocalipse pode ser considerado um dos maiores feitos teológicos do cristianismo primitivo. Contudo, sua forma literária o torna impenetrável a muitos leitores contemporâneos e sujeito a interpretações errôneas. Para nos auxiliar, Richard Bauckham desenvolve um estudo em que analisa o livro tanto em seus aspectos literários quanto teológicos. Em A teologia do livro de Apocalipse, o autor explora as temáticas, as imagens e as simbologias utilizadas por João, além de apontar para os aspectos históricos de Apocalipse, enraizando-o no mundo do primeiro século, dominado por Roma. Bauckham demonstra como a teologia do livro é inseparável de sua estrutura literária e argumenta que, ao contrário do que se pensa comumente, ele não revela uma profecia codificada de acontecimentos históricos. Antes, Apocalipse chama os cristãos para enfrentar as idolatrias políticas de seu tempo e para participar do propósito divino de trazer todos os povos para o seu reino – um chamado que transcende o contexto original de escrita e se direciona à igreja ainda hoje. Autor: Richard Bauckham Editora: Thomas Nelson Brasil Acabamento: Capa brochura Dimensões: 14 cm largura x 21 cm altura Número de páginas: 192', 38.99, 38.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdyn-lzjjkqrjv3p0b3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F23393253132', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
