INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499559750', 'Chave Combinada Mayle Cromo Vanádio 27mm', 'Características Principais: Marca: Mayle Modelo: Cromo Vanadio Segmento: Chave Combinada Comprimento (cm): 29,80 Largura (cm): 5,50 Altura (cm): 2,10 Peso (kg): 0,33 Composição: 1 CHAVE COMBINADA 27mm Material: Aço Cromo Vanádio (Cr-V) Cor: Prata Especificações Técnicas: Composição: 1 Chave Combinada 27mm Acabamento: Niquelado e cromado para maior resistência à corrosão Perfil sextavado oferece melhor contato com parafusos, evitando danos Medidas iguais nos dois lados facilitam a identificação na caixa de ferramentas Modo de Uso: Indicada para apertar e desapertar porcas e parafusos com perfil sextavado e quadrado Instruções de Segurança: Utilize sempre equipamentos de proteção individual (EPIs) adequados durante o uso Garantia: 12 meses Fornecedor: APEX TOOL GROUP IND.E COM.LTDA', 42.8, 42.8, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824gq-mpibrc494nb603', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F18499559750', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49307819137', 'Capa Capinha Anti Impacto AZ Color Mag Para iPhone 17', 'Capa Capinha Anti Impacto AZ Color Mag Para iPhone 17 A Capa Anti Impacto AZ Color Mag combina proteção reforçada com um design moderno e elegante. Com traseira transparente e detalhe interno colorido com tecnologia magnética, ela valoriza o visual do aparelho enquanto garante praticidade no uso com acessórios MagSafe no dia a dia. • Proteção Anti Impacto: Estrutura reforçada com laterais em TPU flexível que absorvem impactos, protegendo contra quedas e batidas. • Compatível com MagSafe: Sistema magnético integrado que garante encaixe perfeito com carregadores e acessórios MagSafe. • Design Premium com Backplate Colorido: Traseira transparente com detalhe interno colorido que traz um visual sofisticado e diferenciado. • Espessura de 1.5mm: Estrutura resistente sem adicionar volume excessivo ao aparelho. • Encaixe Perfeito: Recortes precisos para câmera, botões e conexões, garantindo usabilidade total. • Bordas Elevadas: Proteção extra para tela e câmera contra riscos em superfícies planas. As cases da AZ estão entre as melhores do mundo. Não utilize produtos químicos abrasivos para higienizar a Capa, inclusive álcool. O álcool é abrasivo e pode remover o verniz e a tinta da Capa.', 78.9, 69.9, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-825zn-mmbsfoxia8lk2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442913304%2F49307819137', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23113734984', 'Kit 30 Peças Terminais Conector Elétrico Forquilha Garfo Pvc Pré Isolado Nylon Fio Cabo 0,5mm a 1,5mm M4', 'Os Terminais Forquilha ou Garfo Pré-Isolados são peças utilizadas na terminação de condutores, com capa plástica para isolação na região da conexão do condutor com o terminal. Produzidos em cobre eletrolítico, com acabamento estanhado possuem alta condutibilidade elétrica e resistência a corrosão.Especificações Técnicas:Tipo: Terminal Forquilha Garfo Pré IsoladoAplicação cabos e fios: 0,5mm à 1,5mmCor: VermelhoTemperatura máxima: 75°CTratamento térmico: EstanhoMaterial do Terminal: CobreMaterial do Isolante: PVCTensão: 450VAmperagem: 19AConteúdo da Embalagem:x30 Unidades Terminal Garfo 0,5 à 1,5mm M43NTV679', 15.99, 15.99, NULL, 'Home Appliances > Electrical Circuitry & Parts > Others', 'https://cf.shopee.com.br/file/sg-11134201-22120-h51l56dlpflv7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F278256920%2F23113734984', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
