INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694054136', 'Coifa Do Cambio Lado Esquerdo Clio Kangoo Original Renault', '(IMAGENS MERAMENTE ILUSTRATIVA) Antes de efetuar a compra favor informar chassis do veículo no campo de perguntas para confirmar aplicação da peça para o mesmo. Aplicações: - Renault Clio II; - Renault Kangoo; - Renault Mégane I; - Renault R-19; Detalhes do anúncio: - 1 KIT COIFA Fabricante: Renault Garantia de 3 Meses contra defeitos de fabricação. Envio: Produtos em Estoque - Postagem em 01 (um) dia útil. Compras efetuadas até as 13hrs, serão postadas no mesmo dia. Dúvidas frequentes: Os produtos são novos? Sim, todos nossos produtos são novos e de procedência legal. Posso retirar pessoalmente? Sim. Trabalhamos com envio ou com retirada em nossa loja física. O produto tem nota fiscal? Sim, emitimos nota fiscal para todas as compras. Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto. Atenção: As compras realizadas em nome de Pessoa Jurídica estão sujeitas à cobrança de ICMS, conforme Protocolo ICMS 41, de 4 de abril de 2008. Caso você tenha dúvidas sobre o percentual a ser aplicado, consulte a Cláusula Segunda, §1° do referido Protocolo. ** AVISO IMPORTANTE: DEVIDO AOS IMPOSTOS COBRADOS EM VENDAS PARA FORA DO ESTADO DE SÃO PAULO, OS VALORES ESTÃO SUJEITOS À ALTERAÇÕES. PORTANTO, ANTES DE FINALIZAR A COMPRA, NOS INFORME VOSSO CEP PARA CALCULARMOS O IMPOSTO** Quem somos?? Grupo de Concessionárias autorizada Renault, localizadas em São José do Rio Preto, Votuporanga, Catanduva, Araçatuba. Estamos no segmento à mais de 15 anos, visando não só atender, mas superar as expectativas de nossos clientes. Venha fazer parte desta família! Horário de atendimento: Seg. à sex.: 7:30h às 18:00hrs', 599.0, 599.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/br-11134201-820m7-mqy68kh2dibo13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F845450448%2F23694054136', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202056154', 'Almofada para Carrinho de Bebê SafeConfort Safety 1st', 'Almofada com formato universal para carrinhos de bebê: prática, descomplicada e confortável, não deforma nem esquenta. Dupla-face para variar o visual do seu carrinho. A Safety 1st desenvolveu a almofada SafeComfort pensando em proporcionar um assento mais confortável e seguro para o seu bebê no carrinho. -Desenvolvida para proporcionar maior conforto e segurança nos assentos dos carrinhos -Formato universal: encaixa na maioria dos carrinhos do mercado -Dupla-face: com 2 cores diferentes para variar o visual do carrinho -Pode ser usada no modo moisés ou passeio dos carrinhos -Aberturas padrão para encaixe do cinto de segurança dos carrinhos, com regulagem para 3 alturas -Laterais reforçadas na região da cabeça, com borda elevada para maior proteção do bebê -Não deforma e não esquenta -Lavável à máquina para maior praticidade no dia a dia Especificações: Uso: Universal Peso: 0,289g Medidas: 74cm x 38cm x 1,5-8cm Garantia: 12 Meses Conteúdo da embalagem: 1 almofada para carrinho dupla-face', 189.9, 189.9, NULL, 'Mom & Baby > Nursery > Mattresses & Bedding', 'https://cf.shopee.com.br/file/sg-11134201-822wk-mic36elatc0283', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1207408200%2F58202056154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
