INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599186104', 'Filtro de Óleo Kadett Ipanema 1.8 2.0 todos os modelos', 'Filtro de óleo Automotivo Anúncio referente a unidade Marca: Filtran Compatibilidade: Kadett Ipanema 1.8 2.0 todos os modelos - Filtra impurezas do óleo do motor. - Varia de tamanho conforme o veículo. - Troca recomendada durante a manutenção regular. - Disponível em diferentes modelos para veículos específicos. - Ajuda a prolongar a vida do motor. Como montar: 1. Limpe a base de assentamento do filtro 2. Oleie levemente a junta de vedação 3, Após encostar na base, aperte manualmente mais de 3/4 voltas 4. Ligue o motor e veriique se há vazamento', 28.0, 28.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbmm-lqmfei426esg74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397577506%2F21599186104', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
