INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44051562918', 'Jogo Chaves Torx T10 a T50 Tramontina PRO Longas Trafix 9pç 44452/209', 'Jogo Chaves Torx T10 a T50 Tramontina PRO Longas Trafix 9pç 44452/209 Descrição do Produto: - As chaves tipo L possuem dois braços de comprimentos diferentes, e ambas extremidades podem ser utilizadas dependendo do local onde será realizado o trabalho; - Ao utilizar o braço mais longo tem-se mais torque, enquanto o braço mais curto promove uma operação mais rápida; - Apertar ou afrouxar parafusos com encaixe trafix; - Haste em aço ferramenta S2 temperada; - Acabamento fosfatizado. Dados Técnicos: - Marca: Tramontina PRO; - Referência: 44452/209; - Dimensões embalagem: 305x110x45 mm; - Quantidade de peças: 9 Peças; - Peso: 0,49 kg. Itens Inclusos: - 09 Chaves torx longas Tramontina PRO: T10 - T15 - T20 - T25 - T27 - T30 - T40 - T45 - T50.', 255.0, 178.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9zu1ug5aj9e56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397583038%2F44051562918', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
