INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599067788', 'Ukulele Tenor Shelby Su25m Captador Passivo + Capa Afinador', 'UKULELE TENOR SHELBY SU25M STNT MOGNO Ukulele Eletrico com Captador Passivo ACOMPANHA: -CAPA REFORCADA EM NYLON 600 -AFINADOR -CABO 5 METROS -3 PALETAS -CAPTADOR DE CONTATO A melhor opcao para quem deseja o melhor Ukulele com preco baixo e otima qualidade sonora. Entrando no mercado com forca total, a Shelby apresenta sua linha de Ukuleles desenvolvidos para oferecer excelente sonoridade e timbres caracteristicos do instrumento. Com acabamento cuidadoso e a certeza que apenas madeiras de qualidade foram utilizadas em sua fabricacao, a Shelby vem com a estrategia de oferecer um instrumento barato, porem, de otima qualidade. ESPECIFICACOES: - Marca: Shelby (Eagle) - Modelo: SU-25M STNT - Linha: Acustico - Categoria: Amador - Estilo: Tenor - Tamanho: Tenor - Tampo: Mogno - Lateral: Mogno - Fundo: Mogno - Escala: Rosewood - Cavalete: Rosewood - Braco: Nato - Tarraxas: 2+2 Niqueladas - Trastes: 18 em Latao - Marcacao: Bolinhas Brancas - Roseta: Mosaico - Escudo: Nao Possui - Braco sem Tensor Regulavel - Corpo sem Cutaway - Tipo de Captacao: Nao Possui - Equalizador: Nao Possui - Afinador: Nao Possui - Controles: Nao Possui - Saidas: Nao Possui - Cordas: Nylon - Acabamento: Acetinado (fosco)', 407.0, 407.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/br-11134207-820lk-mnr5j1ueh3wid2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F20599067788', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
