INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57608307420', 'Relógio Orient Masculino Automático Sport Sea Garantia 1 Ano', 'Procurando um presente perfeito? Encontrou! Dê o lindo Orient de presente para você mesmo, ou para alguém querido! *1 ANO DE GARANTIA ORIENT - Produto com NOTA FISCAL* Atuamos somente com produtos 100% ORIGINAIS! Leve em um especialista de sua região para comprovar. Ficha Técnica PROVA D''ÁGUA: Sim - selo de resistência 20 ATM (resistência até 200 metros de profundidade) MATERIAL DO VIDRO: Cristal Safira MAQUINÁRIO: Automático mecânico MATERIAL DO RELÓGIO: Aço inoxidável COR DO FUNDO: Azul Medidas TAMANHO DA CAIXA (mostrador): 4,2 cm (42 mm) ESPESSURA DA CAIXA (mostrador): 1,3 cm (13 mm) LARGURA DA PULSEIRA: 2,0 cm (20 mm) CIRCUNFERÊNCIA DA PULSEIRA: 26 cm Funções Calendário Ponteiros fosforescentes Acompanha Relógio Orient, caixa original Orient, manual de instruções em português, certificado de garantia e nota fiscal. Nossos produtos são todos tratados com máximo cuidado, profissionalismo e atenção. Enviamos o seu relógio em uma embalagem reforçada, protegida por dentro e por fora. Caso não tenha gostado ou simplesmente se arrependeu, devolva o produto sem preocupações. Você tem 30 dias a partir do recebimento para devolvê-lo. COMPRE COM SEGURANÇA Revendedor autorizado Orient', 2159.0, 1798.0, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/sg-11134201-81zuh-mmqa9vagej2912', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463371489%2F57608307420', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499300964', 'Lola Cosmetics Dream Cream - Máscara De Hidratação 450g', 'Máscara hidratante para todos os tipos de cabelo.Dream Creamhidrata os fios, confere controle e restaura a fibra capilar. A Máscara Dream Cream Lola Cosmetics proporciona total aderência dos ativos que penetram profundamente na fibra capilar e conferem resultados instantâneos e de longa duração. É Livre de parabenos e com uma fórmula extremamente hidratante que doma os fios com volume excessivo e com frizz, recupera a hidratação perdida enquanto restaura todos os danos sofridos pelo cabelo. Como usar: Com o cabelo limpo pelo shampoo, retire o excesso de água com uma toalha. Aplique a máscara no comprimento e pontas e massageie. Deixe agir por 2 a 3 minutos e enxágue por completo. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 77.9, 77.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8262h-mlxpcvj1immga3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F23499300964', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203974194', 'Kit Com 5 Farinha Panko Para Empanar Alfa 1kg', 'A Farinha Panko é ideal para o preparo de pratos empanados orientais, como tempurá, camarão frito, hot roll e outros. Com farinha Panko, os pratos orientais fritos tornam-se mais crocantes, assemelhando-se à qualidade dos restaurantes orientais renomados. Características: Ingredientes: Farinha de trigo, Fermento e Sal. Informações Adicionais: “Contém Glúten”. Embalagem: Contém 10 pacotes de farinha Panko Alfa 1Kg. Origem: Brasil Fabricante: Alfa. Recomendações: Conservar em local seco e arejado.', 117.5, 117.5, NULL, 'Food & Beverages > Baking Needs > Flour', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjuto6udr18j42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1732495279%2F58203974194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
