INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57860932525', 'Creme De Hidratação Trivitt Máscara Intensiva Itallian 500G', 'Creme De Hidratação Trivitt Máscara Intensiva Itallian 500GTransforme seus cabelos com o Creme De Hidratação Trivitt Máscara Intensiva Itallian. Ideal para todos os tipos de cabelo, esta máscara proporciona uma hidratação profunda, reparando danos e conferindo brilho e condicionamento aos fios. Com ativos poderosos, sua fórmula penetra na fibra capilar, fortalecendo os cabelos e prevenindo quebras. Benefícios do ProdutoA Máscara Intensiva Trivitt é a escolha perfeita para quem busca cabelos saudáveis e radiantes. Seus ingredientes inovadores garantem: Hidratação prolongada e eficaz Brilho intenso e fios condicionados Proteção contra agentes externos e danos Modo de UsoPara obter os melhores resultados, aplique a máscara sobre os cabelos limpos e úmidos, do comprimento às pontas. Massageie suavemente mecha por mecha e deixe agir por 5 minutos. Enxágue bem e, se desejar, finalize com escova utilizando o Fluido para Escova Trivitt. Por que escolher a Máscara Intensiva Trivitt?Com sua fórmula rica em Trealose, Queratina e Óleo de Camelina Dourada, a Máscara Intensiva Trivitt não só hidrata, mas também restaura a elasticidade e flexibilidade dos fios. Diga adeus ao ressecamento e olá a cabelos saudáveis e vibrantes! Não perca a oportunidade de revitalizar seus cabelos! Experimente agora o Creme De Hidratação Trivitt Máscara Intensiva Itallian 500G e descubra a diferença que um tratamento profissional pode fazer. Adquira já o seu e sinta a transformação!', 100.69, 95.58, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-823qw-moiym20j90y511', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1186779187%2F57860932525', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498814023', 'Bola De Futebol De Campo Penalty Asa Branca R2 Xxv', 'Eleve seu jogo a um novo patamar com a Bola de Futebol de Campo Asa Branca R2, a escolha ideal para jogadores que buscam alta performance e equipamentos de qualidade profissional. Desenvolvida com tecnologia de ponta, esta bola oferece precisão, durabilidade e desempenho superior em cada partida. Domine o jogo com uma Bola de Campo que responde aos seus comandos e te leva à vitória. Benefícios: >Resistência e durabilidade >Menor absorção de água >Toque Macio >Estabilidade Alguns diferenciais técnicos: A Bola de Futebol de Campo Asa Branca R2 se diferencia pela sua construção sem costuras, impulsionada pela inovadora tecnologia Ultra Fusion. Essa tecnologia revolucionária oferece uma série de vantagens que elevam a performance em campo, como: menor absorção de água, maior durabilidade e esfericidade perfeita. Esta Bola de Campo conta também com sistema de forro termofixo, que assegura maior estabilidade e precisão nos chutes, além de aumentar a resistência da bola. Além do processo extra de dupla colagem reforça a união dos gomos, aumentando ainda mais a resistência e a vida útil da bola.', 159.99, 159.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-7rdy5-mdca27vrpnggec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F22498814023', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
