INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13538624854', 'Paleta de Contorno 3 CORES PhálleBeauty PH03201A1', 'Paleta de Contorno 3 CORES PhálleBeauty PH03201A1 Seu rosto mais fino, definido e aperfeiçoado! Com o jogo de luz e sombra, você consegue disfarçar e realçar o que deseja e fica pronta para os flashes! Conselho de Aplicação Pegue uma pequena quantidade do bronzer escolhido com um pincel apropriado e dê leves batidinhas para remover o excesso do produto. Aplique abaixo das maçãs do rosto, na linha do maxilar e em torno da raiz do cabelo. Esfume bem. Resultado Seu rosto fica com os traços mais definidos, destacados e modelados. Livre de Testes em Animais Produto Vegano', 19.99, 19.99, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0et142l8h356f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F434200296%2F13538624854', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
