INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997457809', 'Relé da Bomba Elétrica de Combustível VW 165906381 / WL50237007 - DNI 0332', 'Relé para Injeção Eletrônica Ficha Técnica Terminais: 5 Fixação: Sem Suporte Voltagem: 12V Aplicação: Relé do Módulo de Controle Eletrônico da Injeção Lista de códigos originais similars: Audi/VW: 165906381, WL50237007 Aplicável em: Golf, Jetta 95/...98, Passat TDS 94/...2001, Fusca com Injeção (México)', 124.94, 124.94, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rd6h-ltzlzy6mycvk24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F972460632%2F23997457809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198476874', 'Adesivo Construção PU 40 387g Cores Tekbond', 'É considerado um silicone de uso geral, muito utilizado na construção civil na vedação e selagem de pias e vasos sanitários, box em banheiros, portas e janelas. Possui excelente resistência aos raios UV e pode ser aplicado em áreas externas Limitações de uso: Este produto não deve ser usado em vidros laminados, metal corrosível, espelhos, superfícies pintadas e/ou porosas, superfícies alcalinas, aquário, acrílicos, concreto, cimento, tijolo, pedra calcária, zinco, placa de aço galvanizado. Não recomendado para plásticos à base de polietileno, polipropileno e policarbonato. Não indicado para fachadas de vidro e qualquer adesão estrutural que necessite resistência, contato de alimentos, imersão contínua em meios líquidos e em espaços totalmente fechados. Não aceita pintura. DADOS TÉCNICOS: Aparência (visual): Pasta translúcida com odor característico (ácido acético) Densidade a 25 ºC (g/mL): 0,93 à 1,05 Tempo de formação de película: 5 à 15 minutos Temperatura ideal de aplicação: + 5 à 35°C Temperatura de trabalho: - 50 à 150°C Alongamento à ruptura: =800 % Dureza Shore A: 25 Cura gradativa a 23°C e 55% U.R. após 24 horas: =3 mm O Silicone Acético Transparente Construcão é um adesivo selante tixotrópico monocomponente, baixo módulo, antifungo e de cura acética. Sua cura ocorre em temperatura ambiente e na exposição à umidade do ar 01 Adesivo Construção PU 40 Branco Tekbond', 25.05, 25.05, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-7rfh4-m9ejorx28b8n36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1425275679%2F22198476874', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593003044', 'KIT 10 FUSIVEL MINI LAMINA PERFIL BAIXO 30A - UNIVERSAL', '– Fusível Míni Lâmina Perfil Baixo Universal; – Amperagem: 30A; – Embalagem com 10 peças; – Aplicação:Honda; Nissan; Toyota; – Dimensões Aproximadas: 11 x 10 x 4mm.', 34.17, 34.17, NULL, 'Home Appliances > Electrical Circuitry & Parts > Electrical Safety', 'https://cf.shopee.com.br/file/sg-11134201-7rd6z-luuqdfx6dwtl8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F972460632%2F22593003044', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44076122243', 'Forma PVC Semiprofissional 24 Bombom Rosa BWB', 'CARACTERÍSTICA DO PRODUTOA Forma Semiprofissional 24 Bombom Rosa é ideal para a produção de chocolates maciços e cascas com muita praticidade e rico em detalhes. Ideal para otimizar seu tempo, pois com ela é possível produzir mais produtos ao mesmo tempo! Modo de usar: Derreta o chocolate conforme a instrução da embalagem e coloque-o na forma de acetato. Em seguida, dê leves batidinhas com a forma em uma superfície plana (pode ser sobre a mesa) para que o ar existente no chocolate seja eliminado e sua produção não fique com ""furinhos"". Para produção de cascas, utilize duas ou mais camadas/ pinceladas de chocolate em cada parte para que não fique muito fina e quebre ao rechear ou decorar. Para produção de moldes maciços, complete com chocolate até obter a quantidade desejada de sua produção. Após o uso, limpe bem as formas com um pano umedecido em água morna ou papel toalha. Não é recomendado o uso de detergente, sabão ou bucha para higienização, a fim de manter a qualidade de sua forma, sem danificá-la. Não utilize nenhum objeto pontiagudo no processo de limpeza. É muito importante esta etapa, pois aumentará a vida útil de sua forma e você poderá produzir muito mais com a mesma forma', 21.2, 11.66, NULL, 'Home & Living > Kitchenware > Bakewares & Decorations', 'https://cf.shopee.com.br/file/sg-11134201-821d1-mgnp8c4pgumib0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F44076122243', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497904632', 'Relógio Masculino Esportivo Champion Azul Barato Homem Esposo Marido Namorado CH30224F', 'Está procurando por um relógio que combine perfeitamente estilo e funcionalidade? Então o relógio masculino esportivo Champion é a escolha ideal! Com design arrojado e detalhes impressionantes, esse relógio é o acessório perfeito para acompanhar você em todas as ocasiões. Esse relógio apresenta uma combinação perfeita entre estilo e robustez. Seu vidro em cristal mineral garante uma excelente resistência a impactos e arranhões, mantendo o visor sempre nítido e impecável. A caixa em metal confere a durabilidade necessária para enfrentar o dia a dia com confiança e elegância. A pulseira em silicone de alta qualidade proporciona um ajuste perfeito ao pulso, garantindo conforto durante o uso prolongado. Além disso, o modelo analógico clássico se adapta perfeitamente a diferentes ocasiões, permitindo que você esteja sempre bem vestido, seja no escritório ou em um evento casual. O tamanho da caixa (peça onde fica o mostrador com os números e ponteiros), é de 4,5 cm, o que é considerado um tamanho médio para a grande maioria dos que adquirem esse relógio. Equipado com o mecanismo Quartz de alta precisão, este relógio oferece uma leitura de horas sempre pontual, sem a necessidade de ajustes frequentes. A resistência à água de 50 metros (5 ATM) permite que você se aventure em atividades que exigem contato com água sem preocupações, como lavar as mãos ou tomar um banho de piscina. Tenha a tranquilidade que comprando em nossa loja o relógio masculino da Champion, será entregue na caixa original, acompanhado de nota fiscal, certificado de garantia e manual de instruções. Além disso, você conta com 1 ano de garantia em todo o território nacional com a rede autorizada da Champion, assegurando a qualidade e a confiança de um produto de excelência. Não perca tempo! Adquira agora mesmo o relógio masculino esportivo Champion e eleve o nível do seu estilo, garantindo um visual moderno, sofisticado e cheio de personalidade! VAMOS CONHECER MELHOR O RELÓGIO? Informações Básicas Marca: Champion Referencia: CH30224F Gênero: Masculino Características Composição do Vidro: Cristal Mineral Material da Caixa: Metal Material da Pulseira: Silicone Modelo : Analógico Mecanismo: Quartz Alimentação: Bateria Resistência à Água: 5 ATM Diâmetro da Caixa: 4,5 cm O relógio vai na caixa original, com a nota fiscal, certificado e manual de instrução. 1 ano de garantia em todo o território nacional com a rede autorizada. VAMOS CONHECER MELHOR SOBRE A RBM? Quer conhecer as melhores marcas de relógios com os melhores preços? Então seja bem vindo a RBM WEBSHOP RELÓGIOS! Com mais de 10 anos de experiência, a RBM RELÓGIOS é referência no mercado relojoeiro. Todos os relógios vendidos pela nossa loja são 100% originais, contém nota fiscal, certificado, manual de instruções e garantia de 12 meses com a rede de assistência em todo o Brasil. Convidamos você a ver nossa reputação e comprar com segurança em nossa loja! Dúvidas? Pergunte - e será um enorme prazer lhe atender!', 399.0, 279.0, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m12x8ulhmgxwed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1309187428%2F23497904632', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593069569', 'Kit 2un. Vermífugo Vermivet Composto Para Gatos Biovet 4 Comprimidos', 'Vermífugo Vermivet Composto para Gatos Biovet 4 Comprimidos - Indicado para gatos; - Tratamento e controle das principais verminoses; - Sem efeitos colaterais quando administrado da forma recomendada; - Administrar 1 comprimido para cada 3kg. Vermífugo oral para gatos à base de Pamoato de Pirantel e Praziquantel. Vermivet Gatos é indicado no tratamento e controle das principais verminoses que acometem os gatos. Vermivet Gatos é indicado no tratamento e controle das principais verminoses que acometem os gatos e possui comprovada eficácia contra os agentes etiológicos. Modo de usar Administrar por via oral, em dose única, sendo a dose repetida após 15 dias, de acordo com o peso do animal. A posologia pode ser alterada conforme o tipo e grau de infestação, a critério do Médico Veterinário. De 1,0 Kg até 1,5 Kg > 1/2 comprimido De 1,5 Kg até 3,0 Kg > 1 comprimido De 3,0 Kg até 4,5 Kg > 1 e 1/2 comprimidos De 4,5 Kg até 6,0 Kg > 2 comprimidos Composição Cada comprimido de 300 mg contém: Pamoato de Pirantel ............................................. 174 mg (Equivalente a 60 mg de pirantel base) Praziquantel ........................................................ 15 mg Excipiente q.s.p ................................................... 300 mg', 72.5, 72.5, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvucgwg18mly1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F23593069569', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
