INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298736942', 'Luminária LED Redonda Teto 3 Cores 20W 40W Moderna Luz Quente Branco ON-LU291', 'A Luminária de LED ON-LU291 une design moderno, economia de energia e excelente desempenho luminoso. Ideal para ambientes internos, conta com três temperaturas de cor ajustáveis, sendo perfeita para salas, quartos, cozinhas e escritórios. Disponível em duas potências — 20W ou 40W —, adapta-se facilmente ao tamanho e à necessidade de iluminação de cada espaço. Seu formato discreto e sua proteção contra poeira e insetos garantem mais durabilidade e eficiência. ESPECIFICAÇÕES: - Modelo: ON-LU291(20W) ou ON-LU292(40W) - Alimentação: 127~220Vca / 60Hz - Potência: 20W ou 40W - Fluxo luminoso: 2000 LM (20W) / 4000 LM (40W) - Temperatura de cor: 3 cores ajustáveis - Índice de reprodução de cor (IRC): >70 - Vida útil: 5000 horas - À prova de poeira e insetos - Fixação: Teto - Diâmetro externo: 28 cm CONTEÚDO: 1x Luminária de LED', 78.5, 76.93, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc85aqckdjhn4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F22298736942', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
