INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499336245', 'Kit 3 Fans Cooler CPU LED RGB Com HUB Controlador e Controle', 'Potencialize o resfriamento do seu gabinete com o Kit 3 Fans Cooler RGB [Transparente]. Com efeito de luz RGB e 8 LEDs em cada fan, este kit oferece alta eficiência de refrigeração e um visual impressionante para aprimorar seu setup. As fans de 120mm x 25mm operam a 1300rpm, proporcionando um fluxo de ar de 31.2 CFM para manter seu sistema fresco. Equipadas com rolamento hidráulico, as fans têm uma vida útil de 40.000 horas. Com uma tensão nominal de 12Vdc e operando entre 10,8 a 13,2Vdc, consomem 0,26A + 10% max, com um consumo de potência de 3.12W. O ruído máximo é de 22,8 dBA, garantindo um desempenho silencioso. O kit inclui um hub controlador com capacidade para até 10 fans e um controle remoto para ajuste conveniente. Informações Técnicas: Kit com 3 fans para gabinete, hub controlador e controle remoto Alta eficiência de refrigeração Efeito de Luz RGB Fans com 8 LEDs Dimensões 120mm x 25mm Velocidade 1300rpm Rolamento Hidráulico Tensão Nominal 12Vdc Tensão de Operação de 10,8 a 13,2Vdc Corrente de Operação 0,26A + 10% max Consumo de Potência 3.12W Fluxo de ar 31.2 CFM Ruído Máximo 22,8 dBA Vida Útil 40.000 Horas Fan Interface 6 PIN Conector do Controlador: 10x 6 Pinos [para ventilador] 2x 4 Pinos [para barra de luz] 1x Sata [para conexão de energia] 1x 5V 3 PIN ARGB [Compatível com sincronização de iluminação] Itens Inclusos: 3x Fans Cooler RGB [Transparente] 12x Parafusos 1x Hub Controlador 1x Controle Remoto', 135.0, 91.96, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/br-11134201-820m8-mqxd7msokume41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F19499336245', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
