INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398715113', 'Carregador Turbo 32W GaN EC 12 POWER Preto Intelbras', 'O EC 12 POWER 32W GAN é um carregador USB ultrarrápido e versátil, com 3 saídas USB, sendo duas delas no formato USB-A e a outra em USB-C, oferecendo flexibilidade para atender os mais diferentes tipos de dispositivos, dos mais novos aos mais antigos. Com saída USB-C Power Delivery (USB-C PD) com potência máxima de 30 W, ele carrega seu aparelho até três vezes mais rápido* que um carregador convencional. *a tensão e corrente de saída podem variar de acordo com o dispositivo conectado e cabo utilizado. Principais Funcionalidades • Carregamento rápido e eficiente - Suporte à tecnologia USB-C Power Delivery (PD) com potência de até 30w. Oferece carregamento até 3 vezes mais rápido que carregadores convencionais. Capacidade de carregar até 3 dispositivos simultaneamente. • Conectividade e compatibilidade - Possui 3 saídas USB, 2 Portas USB- A, 1 Porta USB-C. • Segurança e durabilidade - Proteção contra surtos de tensão e sobrecarga. Não vicia a bateria dos dispositivos. • Design - Design compacto, ideal para viagens e uso diário. Fabricado com plástico antichamas, aumentando a segurança. * Fabricado com plástico antichamas, aumentando a segurança.', 129.9, 103.92, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/sg-11134201-81zwc-miq02ono5uype0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F859766415%2F22398715113', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394183035', 'Armário Aéreo Cozinhas Itatiaia Luce - 3 Portas - Branco', 'Armário Aéreo Cozinhas Itatiaia Luce - 3 Portas - BrancoCom puxadores em alumínio, o Armário Aéreo Itatiaia é mais resistente a corrosão e variações bruscas de temperatura, tem durabilidade e proteção contra ferrugem. A Itatiaia não se responsabiliza pela montagem e instalação dos produtos. A montagem deve ser realizada por um profissional, conforme as instruções do manual do produto. A responsabilidade da montagem é do consumidor. NÃO FATURAMOS PARA CLIENTES CNPJ, AGRADECEMOS A COMPREENSÃO. EspecificaçõesMarca: Itatiaia Modelo: Luce Recomendações Montagem: Seguir orientação de montagem conforme manual que vai junto ao produto e fixá-lo na parede Pintura eletrostática a pó: Sim Peso Máximo por Prateleiras (Kg): 15 Necessita Montagem: Sim Cor: Branco Rodapé: Não Recomendações de Uso, Manutenção e Limpeza: Pano levemente umedecido com sabão neutro Linha: Luce Largura - Montado (cm): 105 Pé regulável: Não Garantia: 12 meses Altura - Montado (cm): 55 Montagem e Montador: Não incluídos Corrediças telescópicas: Não EAN: 7892946336762 Profundidade - Montado (cm): 28 Peso (Kg): 10.46 Trava de segurança nas gavetas: Não Material predominante: AÇO Adquira agora o Armário Aéreo Cozinhas Itatiaia Luce - 3 Portas - Branco!', 396.22, 396.22, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7ra0h-mbh1xzetejqd3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1553092714%2F22394183035', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
