INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899208403', 'Kit 2 Sabonetes Líquido Coala Home Figo Imperial 500ml', 'Descubra a experiência única do Sabonete Líquido Coala Home - Figo Imperial 500ml, perfeito para higiene diária de mãos, corpo e rosto. Sua fórmula suave e hidratante limpa profundamente sem ressecar, proporcionando uma sensação de pele macia e perfumada. O aroma sofisticado de figo imperial traz um toque de elegância e frescor para o seu dia, elevando o cuidado pessoal a um novo patamar. Principais benefícios: - Limpeza eficaz e delicada para todos os tipos de pele - Fragrância exclusiva que dura na pele, promovendo bem-estar - Textura cremosa que facilita a aplicação e enxágue rápido - Embalagem prática com pump para uso econômico e higiênico Ideal para quem busca um sabonete líquido de qualidade, com alta hidratação e fragrância marcante, garantindo uma rotina de cuidados prazerosa e eficaz. Aproveite a sensação de frescor e conforto que só Coala Home proporciona.', 36.2, 34.2, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi5xintsp4oy01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177903362%2F22899208403', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
