INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998481259', 'Cuscuzeira Individual Antiaderente Vermelha preto Turim Tramontina nordestino', 'Cuscuzeira Tramontina 10 cm 0,8L em Alumínio com Revestimento Antiaderente Starflon Max Prepare cuscuz com muito mais praticidade e sabor usando a Cuscuzeira Tramontina 10 cm com capacidade de 0,8 litros. Fabricada em alumínio com revestimento interno e externo antiaderente Starflon Max, essa cuscuzeira é perfeita para o preparo rápido e uniforme, sem que os alimentos grudem. Compacta e funcional, é ideal para porções individuais ou para quem busca agilidade no dia a dia. Além disso, o revestimento antiaderente facilita muito a limpeza após o uso. ✅ Destaques do produto: Revestimento antiaderente Starflon Max: mais durabilidade, fácil de limpar e livre de PFOA Cozimento uniforme: alumínio de alta qualidade que distribui melhor o calor Uso prático: perfeita para preparar cuscuz, legumes no vapor, entre outros Cabos e pegadores de baquelite antitérmico, que não esquentam durante o uso Design leve, moderno e funcional 📦 Especificações técnicas: Marca: Tramontina Linha: Turim / Antiaderente Modelo: Cuscuzeira 10 cm Diâmetro: 10 cm Capacidade: 0,8 Litros Material: Alumínio Revestimento interno e externo: Antiaderente Starflon Max Material dos cabos e pegadores: Baquelite antitérmico Cor: Preta (ou conforme disponibilidade) Compatível com fogões: Gás, elétrico, vitrocerâmico (resistência elétrica) Pode ir à lava-louças: Sim Livre de PFOA: Sim Origem: Brasil Garantia: 90 dias para defeitos de fabricação 🛒 Garanta já a sua Cuscuzeira Tramontina e torne suas receitas ainda mais práticas e saborosas! Produto original com envio imediato.', 139.99, 139.99, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9uku7k31xxedf', 'https://shope.ee/an_redir?or