INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392969940', 'Combo 2 Pares Sapatilha Masculina Infantil Sapatilha Antiderrapante Aquatica', '"As imagens do anúncio correspondem exatamente a aparência real dos produtos. Caso o(a) cliente desejar alterar cores e numerações dos modelos referentes ao anúncio, recomenda-se solicitar as alterações dentro de 15 minutos após finalizar a compra, afim de evitar possíveis transtornos. Kit composto por 2 PARES DE SAPATILHA ANTIDERRAPANTE conforme foto do anúncio. A Sapatilha Infantil Antiderrapante é um calçado cuidadosamente projetado para garantir conforto e segurança aos pequenos, com um design moderno e funcional, essa sapatilha foi especialmente desenvolvida para oferecer estabilidade e aderência em diferentes superfícies, evitando escorregões e quedas. Feita com materiais de alta qualidade, proporciona durabilidade e resistência, além de possuir um formato flexível que se ajusta perfeitamente aos pés das crianças. Ideal para uso em piscina, natação, passeios, para superfícies molhadas e até mesmo para ficar em casa nos dias mais frios, pois funciona perfeitamente como meia também, combinando estilo e funcionalidade para acompanhar o ritmo das atividades infantis. Características do KIT: 2 Pares de Calçados Composição do Calçado: Marca: Duck Meias Material: Poliéster (revestido com espuma) Solado: Antiderrapante Guia de Tamanhos: 0-17/18 – 12,20 CM PP-19/20 – 13,00 CM P-21/22 – 14,75 CM M-23/24 – 15,75 CM G-25/26 – 16,75 CM GG-27/28 – 17,75 CM EG-29/30 – 18,40 CM XG-31/32 – 19,90 CM "', 106.9, 79.95, NULL, 'Baby & Kids Fashion > Boy Shoes > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lubzfdv0opzo18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287287585%2F23392969940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20072154442', 'Garrafa Térmica GLT Rolha 1L Lille Verde Matcha Invicta', 'A Garrafa GLT Lille foi inspirada em uma cidade localizada no norte da França, que possui o monumento “coluna da deusa”, e representa a resistência e perseverança de seus cidadãos durante a Revolução Francesa. Esta garrafa possui um design diferenciado, com as mesmas linhas caneladas encontradas no principal marco da cidade de Lille! A garrafa Lille possui copo superior, a nova rolha de fácil rosqueamento e ampola de vidro que conserva os líquidos quentes por até 6h e gelados por até 12 horas. É ideal tanto para o uso doméstico, quanto institucional. Modo de uso 1) Retire a tampa 2) Encha com água quente 3) Deixe a garrafa fechada por dois minutos 4) Despeje todo o conteúdo da garrafa 5) Coloque o líquido a ser mantido termicamente, utilizando a capacidade total da garrafa 6) Coloque a tampa e feche bem. Limpeza 1) Retire a tampa 2) Use sempre água morna ou quente com detergente neutro. Para remover manchas, odores ou resíduos utilize água e vinagre 3) Retire todo o líquido do interior da garrafa e enxágue antes de reutilizá-la 4) Lave externamente com água e sabão neutro 5) Deixa secar as peças mantendo a garrafa térmica aberta.', 39.9, 39.9, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/sg-11134201-8259s-mqw7a40zmuq264', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F859051456%2F20072154442', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
