INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598114327', 'Ventilador Mondial VT-30NB 30cm', 'VENTILADOR DE 30CM + 6 PÁS: O design aerodinâmico proporciona forte ventilação e melhor distribuição de ar. O resultado é um ambiente mais fresco e agradável; MAIS SILENCIO E CONFORTO: O sistema de ventilação da Mondial apresenta baixo nível de ruído, assegurando o silêncio necessário para uma excelente noite de sono; MAIOR DISTRIBUIÇÃO DE AR: O Sistema Oscilante Contínuo amplia o raio de alcance do vento no ambiente; INCLINAÇÃO VERTICAL REGULÁVEL: Para um direcionamento ideal do fluxo do ar; CONTROLE DE VELOCIDADE: As 3 opções de velocidade permitem adequar o vento à sua necessidade; FACILIDADE NA LIMPEZA: A grade desmontável oferece mais facilidade na limpeza das hélices. MODELO: VT-30NB Vento Turbo Mais Silêncio e Conforto 6 Pás Controle de velocidade 3 velocidades Inclinação vertical regulável Dimensões do Produto: Altura: 50 cm Largura: 39,5 cm Profundidade: 28 cm Peso: 2,16 Kg Garantia: 12 meses', 169.9, 169.9, NULL, 'Home Appliances > Small Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ra1m-m4ooyoo8j42f5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1243712796%2F23598114327', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
