INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10255801669', 'Torneira Tanque e Máquina De Lavar De Metal 1/4 De Volta C61', 'A Softinox trabalha com uma ampla variedade de metais, como torneiras, ralos, engates e muito mais. Buscamos sempre oferecer preços e produtos imbatíveis, sem abrir mão da qualidade de cada item que você recebe em sua casa. Selecionamos cuidadosamente os melhores produtos para garantir que sua experiência de compra conosco seja inesquecível e duradoura. Descrição: A Torneira para Tanque e Máquina em Metal Cromado com 1/4 de Volta oferece praticidade e conveniência para suas tarefas diárias de lavanderia. Com duas saídas distintas, esta torneira proporciona uma solução inovadora para quem precisa utilizar a máquina de lavar ao lado do tanque, permitindo que ambas as saídas sejam utilizadas simultaneamente sem a necessidade de desconectar a mangueira. Fabricada com corpo em metal cromado de alta resistência, garante durabilidade e precisão no uso. Especificações Técnicas: Material: Metal Cromado Tipo de Acionamento: 1/4 de Volta Saídas: 2 saídas de 3/4 Entradas: 1 entrada de 1/2 e 1 entrada de 3/4 Dimensões (Altura x Largura x Comprimento): 12,5 x 10 x 13,5 cm Tags:Torneira, Tanque, Máquina, Metal Cromado, Praticidade, Conveniência, Durável, Inovação.', 159.9, 67.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-7rd41-lu9l0bau8hwl05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F350194951%2F10255801669', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
