INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43463855439', 'Bíblia Sagrada Farol Ilustrado | KJA | Letra Maior | Capa Dura', 'Bíblia Sagrada Farol Ilustrado | KJA | Letra Maior | Capa DuraA Plenitude Distribuidora traz a Bíblia Sagrada King James Atualizada, uma obra que une tradição, precisão e elegância. Com capa dura e texto em letra maior, esta edição oferece conforto visual e durabilidade, ideal para leitura diária, estudo bíblico e meditação. Tradução Fiel e HistóricaA Bíblia King James é uma das traduções mais respeitadas do mundo, com raízes na Inglaterra do século XVII. Encomendada pelo Rei James I e elaborada por 50 estudiosos especializados, sua linguagem preserva a fidelidade aos originais em Hebraico e Grego, mantendo a riqueza literária que influenciou gerações. Design Exclusivo e FuncionalLetra maior: Facilita a leitura sem cansar a vista.Capa dura resistente: Garante maior durabilidade.Mapas e recursos extras: Inclui referências geográficas e históricas, como "Viagem pelo Mundo Romano" e "Cidades de Refúgio", enriquecendo seu entendimento das Escrituras.Esta versão atualizada da King James é uma peça única para colecionadores, estudiosos e fiéis que valorizam precisão teológica e qualidade editorial. Tenha em mãos uma obra que une história, fé e excelência textual – perfeita para aprofundar sua espiritualidade e enriquecer seus momentos de devoção. Garanta o seu exemplar exclusivo!', 35.45, 30.14, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824g9-mpmc89wsac5re3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F43463855439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26738545230', 'Livro Cartonado When I Feel Surprised W.Books', 'Children experience all kinds of feelings in a single day, but they can’t always name them or talk about them easily._x000D_ This essential series focuses on the six major emotions experienced by very young children. Each book uses non-gendered characters to illustrate, identify and talk about a single feeling, suggesting coping strategies where relevant._x000D_ _x000D_ Editora: W. Books_x000D_ Edição: 1, 2025_x000D_ Autor: Child s Play_x000D_ Ilustrador: Paula Bowles_x000D_ Idioma: Inglês_x000D_ Páginas: 12_x000D_ Dimensões: L 20.30 x A 20.30 x E 1.00_x000D_ ISBN: 9786552940933_x000D_ Coleção: Primeiras emoções/First feelings_x000D_ Linha Editorial: W. Books - Infantil_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Emoções, Sentimentos, Surpresa, Inglês_x000D_ BISAC: Literatura Infantil / Literatura Infantil / Temas Sociais / Emoções e Sentimentos_x000D_ Linha de Produto: Cartonado_x000D_ Encadernação: Lombada quadrada_x000D_ Acabamento: Verniz de máquina_x000D_ Material: Cartonado', 19.9, 13.93, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdvd-mc0plwzlfmku8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F26738545230', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
