INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193510084', 'Kit com 6 Cadeiras de Jantar - Milla Cinza/Marrom Cinza/Marrom', 'Para complementar sua sala de jantar apresentamos a Cadeira para Mesa de Jantar Milla, desenvolvida pela Henn com materiais de alta qualidade em sua estrutura conta com design moderno e elegante, não perca mais tempo e aproveite pois é a escolha perfeita para trazer conforto e estilo no seu ambiente. As Cadeiras Milla são super estilosas, seu design moderno e exclusivo chama atenção, perfeitas para quem quer deixar o ambiente com mais personalidade. Estilo: Moderno Peso (kg): 43 Garantia: 03 Meses Altura (cm): 94.5 Largura (cm): 41.5 Profundidade (cm): 53.5 Tipo de Assento: Fixo Escala de Brilho: Fosco Origem do Produto: Nacional Ambiente Principal: Sala de Jantar Material Principal: MDF/MDP Necessita Montagem: Sim Almofada do Assento: Fixa Quantidade de Itens: 6 Enchimento do Assento: Espuma D-18 Enchimento do Encosto: Espuma Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem Possui Assento/Encosto Estofados: Possui Encosto e Assento Estofados Marca: Henn Cor: Cinza/Marrom Cor do Produto: Cinza/Marrom Cor Predominante: Cinza Linha ou Coleção: Milla', 1233.63, 1233.63, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-824gs-mfg22dxc2uq7d8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F23193510084', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21473674707', 'Cesto De Lixo Brinox Decorline Gamma 9,4 Litros Ø 20 x 29 cm Aço Inox', 'Perfeito para dormitórios, escritórios, salas de recepção e lojas, o cesto Gamma é resistente, fácil de limpar e pode ser utilizado como papeleira ou para lixo seco. Seu corpo em aço inox e seu fundo plástico evitam o acúmulo de resíduos e garantem longa vida ao recipiente. O acabamento cromado possui pequenos orifícios e, além de elegante, combina com qualquer estilo de decoração. A lixeira tem capacidade para 9,4L e ø 20cmx29cm de dimensão.', 169.99, 114.75, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/sg-11134201-7rbkp-lol37fo7n8hte2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F21473674707', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
