INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257762649', 'Conjunto com 6 Pratos de Sobremesa Neo Preto Matte Ø21,5cm', 'O Stoneware, assim como a faiança feldspática e porcelana, é um material cerâmico. O Stoneware Porto Brasil é um material inovador e sustentável, onde a combinação das melhores matérias primas naturais, unido a um processo único de queima e acabamento manual, entregam um produto com características superiores em termos de qualidade e resistência, estando em conformidade com as principais normas mundiais. Além disso, conseguimos proporcionar peças exclusivas, onde alterações de formas, relevos e variações de cores são efeitos característicos dos produtos, evidenciando assim sua originalidade e autenticidade.', 317.9, 206.64, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-8262j-mmbupxuleex1e4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242213783%2F58257762649', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992976708', 'Banqueta Industrial em Aço e Madeira Maciça Laís Preto/Castanho 1', 'Banqueta de aço com madeira maciça, para agregar e decorar seu ambiente, sala, varanda, hall, áreas gourmet. Com um design moderno e luxuoso para desfrutar de grande utilidade que o produto oferece. Adicionados ao charme e beleza os produtos Art&Luxo possuem grande tecnologia e durabilidade, as estruturas são produzidas em aço carbono com tratamento anti corrosivo e pintura epox. Agregando o mercado nacional, com beleza, requinte e consciência ambiental, a Art&Luxo usa madeiras maciças 100 % de reflorestamento, produzindo encostos e assentos de altíssima qualidade e ajudando o meio ambiente. Estilo: Industrial Peso (kg): 4.6 Dobrável: Não Garantia: 03 Meses Altura (cm): 95 Largura (cm): 37 Possui Encosto: Sim Possui Rodízio: Não Suporta Até (kg): 120 Profundidade (cm): 50 Tipo de Assento: Fixo Tipo de Encosto: Fixo Altura Regulável: Não Escala de Brilho: Semi-Brilho Altura do Encosto: 26 Origem do Produto: Nacional Altura da Banqueta: Alta (> 65 cm) Ambiente Principal: Cozinha Material Principal: Aço Necessita Montagem: Não Material do Assento: Madeira Maciça Material do Encosto: Madeira Maciça Material da Estrutura: Aço Acabamento da Estrutura: Pintura Classificação da Altura: Alta Possui Apoio para Braços: Não Possui Apoio para os Pés: Sim Possui Almofada no Assento: Não Altura do Assento até o Chão: 70 Marca: Art & Luxo Tonalidade: Azul Cor do Produto: Preto/Castanho Itens Inclusos: 1 Banqueta Tipo do Produto: Banqueta Cor Predominante: Preto Linha ou Coleção: Lais Quantidade do Produto: 1', 320.98, 320.98, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-82580-mqz30mimlfk094', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshope