INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293916879', 'Kit C/ 4 Pisca Led Seta Honda Cb250f Twister 2019 Fan Titan', 'Pisca LED Modelo CB 250 Twister com Coxim – Compatível com Diversas Motos Honda 🚨 ATENÇÃO: Este modelo de pisca LED possui coxim de fixação. Não é compatível com motos que utilizam fixação apenas por parafuso. ✅ Verifique o ano e modelo da sua moto antes da compra! 🔧 Compatibilidade Aplicável nos seguintes modelos: Honda CG Titan Fan 150 – Anos: 2014, 2015, 2016 Honda CB250 Twister – Anos: 2016 a 2020 Honda CG Cargo 160 – Anos: 2015 a 2020 Honda Start 160 – Anos: 2014 a 2020 Honda CG Fan 160 – Anos: 2015 a 2020 Honda CG Titan 160 – Anos: 2015 a 2020 Honda XRE 300 – Anos: 2019, 2020 👉 Serve para todas as motos que utilizam coxim para fixação! 🔌 Instalação Fácil Produto desenvolvido conforme especificações originais. Encaixe perfeito, sem necessidade de adaptações na estrutura da moto. Em alguns modelos, pode ser necessário trocar o relé de pisca – sempre teste antes de qualquer substituição. 📦 O que acompanha o produto: 04 Piscas de LED (2 pares)', 78.95, 41.09, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8dpc7yrf7qp43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1002186443%2F22293916879', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
