INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698377911', 'Pia de Cozinha em Mármore Sintético com Furação para Válvula Americana 150CMX55CM Aj Rorato Travertino Travertino', 'A linha de Pias Roralit para válvula americana, destaca-se por sua versatilidade e design orgânico e elegante. Sua cuba foi desenvolvida com dimensões generosas, proporcionando espaço suficiente para facilitar suas tarefas na cozinha. Além da funcionalidade ela complementa o estilo da sua cozinha, com variedade de cores e acabamento em gel coat de alta qualidade, que proporciona a peça superfícies lisas e sem porosidade e um brilho incrível, combinando utilidade e beleza. Peso (kg): 19.75 Garantia: 03 Meses Altura (cm): 0.205 Largura (cm): 150 Espessura (mm): 340 Possui Ladrão: Não Antivandalismo: Não Profundidade (cm): 0.55 Acompanha Válvula: Não Origem do Produto: Nacional Tipo de Cuba para Cozinha: Simples Acompanha Manual de Instalação: Não Possui Adaptação para Triturador: Não Material Principal Construção e Acabamento: Mármore Sintético Marca: AJ Rorato Cor: Travertino Cor do Produto: Travertino Itens Inclusos: 1 Cuba Válvula Indicada: A válvula indicada para a Pia de cozinha é o modelo Americano, com a bitola de 3 ½ x 1 ½ polegadas. E o diâmetro aproximado de 8,9 cm do topo e de 4,5 cm do pescoço. Podendo ser plástica e/ou cromada.', 488.17, 488.17, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gx-mprjo19f826959', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22698377911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
