INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52902611740', 'Livro Diversão Só Caça-Palavras 30 | Nível Médio: 29', 'Um clássico moderno: o passatempo que combina desafio, diversão e saúde mental! Nível fácil 96 páginas 13,5X20,4cm Diversidade de temas para caça-palavras Ideal para todas as idades, para quem busca momentos de relaxamento com foco, concentração e estimulação cognitiva leve Com "Diversão Só Caça-Palavras - Fácil", você terá horas de entretenimento garantido! Este livro é perfeito para relaxar, exercitar a mente e se divertir com uma variedade de temas, desde dicas de bem-estar até curiosidades sobre o mundo. Desvende palavras ocultas em caça-palavras cuidadosamente elaborados para todos os níveis. Ideal para quem busca passatempos leves e educativos. Adquira já o seu e transforme seus momentos de lazer em puro aprendizado e diversão!', 14.99, 10.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8227y-mhv627cuerd2c6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F52902611740', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
