INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394150253', 'LANTERNA ENCAIXE ORIGINAL PARA LUZ DE PLACA GM CHEVROLET MONZA DE 1991 ATÉ 1996 REF. 52255937', 'LANTERNA PARA LUZ DE PLACA LINHA GM MONZA 1991 ATÉ 1996 Garanta a sinalização correta e evite multas com uma iluminação eficiente e discreta! A lanterna para luz de placa GM Monza 91 a 96 foi desenvolvida para reposição perfeita, mantendo o padrão original de fábrica e proporcionando segurança e estilo ao seu veículo. Fabricada em material plástico resistente, ela conta com acabamento de alta qualidade, encaixe preciso e lente translúcida que permite excelente difusão da luz. Compatível com lâmpadas 12V, oferece fácil instalação plug and play, sem a necessidade de adaptações. Ideal para reposições em carros restaurados ou manutenção preventiva. Aplicação específica: GM Chevrolet Monza de 1991 a 1996 (Pode haver compatibilidade com outros modelos – verifique medidas) Características: Aplicação em ambos os lados Reposição fiel ao original Lente translúcida para melhor iluminação da placa Material plástico de alta resistência Compatível com lâmpadas 12V Encaixe sob medida – sem adaptações Acabamento resistente a intempéries Dimensões da lanterna: Aproximadamente 93x40x29mm (LxAxP) – 9,3cm / 4cm / 2,9cm Conteúdo da Embalagem: 1 Lanterna para luz de placa (Não acompanha lâmpada) NTV1550', 17.9, 17.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rau3-mb2t9x74yp2a50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F278256920%2F23394150253', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58262420946', 'Aditivo Impermeabilizante Vedacit (Balde 18 litros) - VEDACIT - Concreto e argamassa', 'VEDACIT VEDACIT é um aditivo impermeabilizante para concretos e argamassas, que age por hidrofugação do sistema capilar e permite a respiração dos materiais, mantendo os ambientes salubres. ÁREAS DE APLICAÇÃO Estruturas • Muro de Arrimo e Paredes de Encosta • Concreto • Alicerce, Baldrame e Sapatas Áreas Frias e de Serviços • Cozinha • Lavanderia • Banheiros Áreas Externas • Paredes Reservatórios • Muro de Arrimo e Paredes de Encosta • Concreto Piscinas • Enterrada Áreas Internas • Paredes MODO DE APLICAÇÃO Uso de poucas ferramentas e pouca dificuldade de aplicação Preparo e aplicação Você pode consultar mais detalhes abaixo de como preparar o produto para uso. Características Densidade: 1,05 g/cm³ Composição básica: Silicatos Rendimento: • Balde de 18 L: até 9 sacos de cimento (50kg) Preparação do Substrato As estruturas que serão impermeabilizadas com argamassa devem estar suficientemente dimensionadas e sem trincas. Já as superfícies a serem revestidas devem estar chapiscadas e limpas. "VEDACIT: Um aditivo indispensável para qualquer projeto de construção." Atuando há mais de 10 anos no mercado, a LB Materiais oferece tudo o que você precisa para realizar seu sonho de construção e reforma! Em caso de dúvidas, fale conosco deixando a sua pergunta no campo de "Perguntas e Respostas", estamos à disposição para melhor atendê-los. Boas Compras Equipe LB Materiais.', 189.9, 137.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-820m3-mpe1nyfv72mb60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F705932885%2F58262420946', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15794286641', 'Filtro Ar Volkswagen Spacefox 1.6 8v 2006 A 2008 Tecfil', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação SPACEFOX 1.6/ 1.6 TREND TOTAL FLEX 8V 5P 2006 até 2008 SPACEFOX COMFORTLINE 1.6 MI T.FLEX 8V 5P 2006 até 2008 Conteúdo Da Embalagem 1 Filtro de Ar Tipo de Veículo para Carros Marca A TECFIL é uma indústria de Filtros Automotivos presente no mercado há mais de 67 anos. A empresa, fundada em 20 de março de 1953, especializou-se no segmento tornando-se a maior fábrica de filtros da América Latina. A Tecfil se dedica a desenvolver filtros de qualidade, sempre buscando o que há de mais moderno em tecnologia e equipamentos para fabricação de seus produtos. Importante • Tempo de garantia - 3 meses • Imagem meramente ilustrativa • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 • Valor unitário Código do Fabricante ARL6095 >', 29.4, 29.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbkz-lltaqenj1c238c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F15794286641', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
