INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594182461', 'Aspirador de Pó Vertical e Portátil Mondial Turbo Cycle 1500W Vermelho 220V - AP-40-R', 'Garanta mais poder de sucção com o Aspirador de Pó Turbo Cycle. A função 2 em 1 permite sua utilização no modo portátil ou vertical. Seus 1500W de potência, com motor superpotente, limpa mais rápido e com eficiência. O sistema de dupla filtragem Turbo Cycle é removível e lavável, além de ser ecológico. Além disso, tem coletor de pó translúcido com capacidade para 1,8 litros e cabo elétrico de 6 metros. 2 EM 1: Possui haste removível e pode ser utilizado como aspirador vertical ou portátil. Na versão portátil, ele é perfeito para limpeza de estofados, carros e teclados. POTÊNCIA DE 1500W: Proporciona alta eficiência na sucção da sujeira, possibilitando uma limpeza mais rápida. FILTRO CICLONE: O Turbo Cycle (sistema de dupla filtragem) mantém os filtros limpos e desobstruídos, o que aumenta a capacidade de aspiração. Além de ser removível e lavável. CABO ELÉTRICO COM 6 METROS: Praticidade e flexibilidade para alcançar todos os cantos da sua casa. RESERVATÓRIO DE 1,8L: Grande capacidade do coletor de pó para maior rendimento na limpeza. BOCAL GIRO 360°: Mais mobilidade para realizar as suas tarefas. PORTA-FIO + PORTA ACESSÓRIOS: Mais praticidade na hora de guardar. ACESSÓRIOS INDISPENSÁVEIS: Acompanha 1 bocal multiúso, 1 bocal para cantos e frestas e 1 bocal para estofados. PARA DIFERENTES TIPOS DE PISO: O aspirador Mondial limpa piso frio, carpete, tapetes, entre outros. ESPECIFICAÇÕES: Altura: 111 cm Largura: 24,6 cm Profundidade: 17,3 cm Peso: 1,8 kg Potência: 1.500W Tensão/Voltagem: 220V Cor: Vermelho CONTEÚDO DA EMBALAGEM: 1 Aspirador de Pó 1 Bocal Multiúso 1 Bocal para Cantos e Frestas 1 Bocal para Estofados 1 Manual de Instruções', 329.9, 259.9, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjq0izvh3wg17e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1296760327%2F22594182461', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
