INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23292339011', 'Capa Case Capinha Samsung Galaxy A04 Gshield Dual Shock X - Proteção Antimpacto e Anti-Amarelamento', 'Duas vezes mais forte = duas vezes mais protegido. Com a capa duplamente reforçada, o seu Samsung Galaxy A04 estará em segurança! A Capa Dual Shock X para Samsung Galaxy A04, da Gshield, foi projetada com uma dupla proteção. Além da proteção padrão de capas, a Dual Shock possui uma elevação na parte traseira que evita que a câmera entre em contato direto com os impactos. ESPECIFICAÇÕES Material: Polipropileno de alta densidade - Não Amarela Marca: Gshield Dimensões: Dimensões exatas do aparelho Proteção: Contra impactos e riscos à traseira Certificações: Us Military COMPATIBILIDADE Samsung Galaxy A04 ITENS INCLUSOS 1x Capa protetora GARANTIA 3 meses contra defeitos de fabricação', 10.99, 10.99, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7qvf2-lj4717oqaoabe7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23292339011', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253135028', 'Boia Esportiva Inflável Rebocável Para 3 Pessoas Suporta 270Kg Ideal Para Lancha E Jet Ski', 'Boia Esportiva Inflável Rebocável 3 Pessoas 270kg Laranja Importway Perfeita para quem busca adrenalina, diversão e segurança em atividades aquáticas. Projetada para ser rebocada por lancha ou jet ski, ela proporciona uma experiência emocionante para até 3 pessoas, sendo ideal para lazer em rios, lagos e no mar. Especificações: • Marca: Importway • Modelo: IWI002 • Material: PVC+Nylon • Capacidade: 3 pessoa • Peso suportado: 270 kg • Tamanho: 195x185x85 cm • Possui alça • Acompanha adesivo reparo Conteúdo Embalagem: - 01 Boia Esportiva Inflável Rebocável 3 Pessoas 270kg Laranja Importway "Compra Garantida" - Ao Comprar conosco a sua compra é 100% garantida, o seu dinheiro está seguro até a entrega. *Imagens meramente ilustrativas Importway Importando Soluções com Qualidade, Inovação e Responsabilidade desde 2007.', 3234.56, 2839.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Boating', 'https://cf.shopee.com.br/file/sg-11134201-8262f-mjeg1xirbj0l5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1229255557%2F58253135028', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
