INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198156961', 'Assento Sanitário Celite Original PP Soft Close Fit Plus Branco', 'Detalhes do Produto: O Assento Sanitário Celite Original PP Soft Close Fit Plus Branco combina conforto e funcionalidade. Com tecnologia Softclose, oferece fechamento suave e silencioso, evitando impactos. Compatível com bacias sanitárias da linha Fit da Celite, é fabricado em polipropileno de alta resistência, garantindo durabilidade e longa vida útil. Ideal para quem busca qualidade e praticidade no dia a dia. Características do produto: Marca: Celite Material: Polipropileno (PP) Cor: Branco Brilhante Informações adicionais: Tecnologia Softclose: Queda amortecida que permite o fechamento suave e silencioso, evitando impactos Compatibilidade: Desenvolvido para bacias sanitárias da linha Fit da Celite Durabilidade: Fabricado em polipropileno de alta resistência, garantindo maior vida útil Benefícios: Praticidade: Fechamento sem ruídos, ideal para evitar incômodos. Segurança: Reduz riscos de incidentes, especialmente com crianças. Design Moderno: Acabamento brilhante que agrega elegância ao banheiro. Garantia: 12 meses Fornecedor: ROCA SANITARIOS BRASIL LTDA', 142.81, 142.81, NULL, 'Home & Living > Bathrooms > Others', 'https://cf.shopee.com.br/file/sg-11134201-824g8-mpiapn01105d47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23198156961', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22195680216', 'Película para Xiaomi Redmi Note 10 5G - Traseira Hydrogel HD - Gshield', 'DESCRIÇÃOAumente a resistência com a película para o seu Xiaomi Redmi 10 5G A Película de Hydrogel para Xiaomi Redmi 10 5G, da Gshield, garante proteção extra para a tela do seu dispositivo. Produzida com a tecnologia hidro nano pet + material semelhante ao silicone, são ultra resistentes contra riscos e com revestimento oleofóbico, atenuando as marcas de digitais na tela do aparelho; a película se adapta às extremidades curvadas, cobrindo todo o visor. ESPECIFICAÇÕESMaterial: Hidro nano pet + TPU Soft Gel Marca: Gshield - ( Gorila Shiel d )Espessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Grau de transparência: 97% High DefinitionCertificações: US MilitaryDimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais.', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7qvd2-lg2nhq2mjojyfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22195680216', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
