INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798319078', 'Kit 4 Arandelas JBL 6CO3R+ 6" 140w Redonda Embutir Teto Gesso Caixa Som Ambiente Selenium', 'Os alto-falantes de teto JBL da linha CO são compactos, desenvolvidos com bordas reduzidas e material de alta qualidade que permite ser pintado para que combinem com qualquer decoração oferecendo melhor integração ao ambiente. Oferecem ótima performance para músicas ou locução em som ambiente com alta sensibilidade oferecendo maior volume de som. Woofer com cone de kevlar oferecendo maior resistência mecânica e a umidade que os cones tradicionais, resposta acústicas com graves presentes, tweeter de domo de seda oferecendo agudos claros e cobertura acústica uniforme para melhor preenchimento do ambiente. A instalação é descomplicada, rápida e fácil através do sistema de fixação que permite a instalação em forros de diversas espessuras sem acessar o teto. Podem ser usados em uma variedade de ambientes como restaurantes, lojas, supermercados, escolas, casas de eventos, escritórios e locais públicos. Especificações Técnicas • Potência Máxima (RMS): 140W (Cada) • Impedância Nominal: 8 Ohms • Frequência de Crossover: 60Hz • SPL Máximo: 110dB • Cor: Branca • Conexão: Borne de pressão • Resposta de Frequência (-3dB): 95Hz - 18kHz • Alcance de Frequência (-10dB): 40Hz - 20kHz • Peso Líquido: 1,2kg', 1798.0, 1149.9, NULL, 'Audio > Home Audio & Speakers > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7c8wn54b1vu82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411081274%2F22798319078', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
