INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57756267428', 'Mangá - One Piece Vol. 112 - Novo/Lacrado', 'One Piece Vol. 112 Luffy e seus amigos finalmente chegam a Elbaf e começam a explorar a lendária ilha dos gigantes. Durante sua aventura, Luffy conhece um misterioso gigante chamado Loki, que guarda importantes segredos sobre o passado de Elbaf e possui uma ligação inesperada com Shanks. Enquanto isso, o restante do bando se reúne para acompanhar Robin em um emocionante reencontro que promete marcar essa nova etapa da jornada dos Chapéus de Palha. Tipo de Produto: Revista Segmentos: Mangás Marcas: Planet Manga Autor(es): Eiichiro Oda ISBN: 9786525943688 Check-List: Fevereiro/2026 Classificação Etária: 12 anos Editora: Panini Gênero: Ação, Aventura Indicação: Jovens Adolescentes - Ensino Médio, Pré-Adolescentes - Fundamental II Demografia: Shonen Número de páginas: 208 Tipo de capa: Capa Cartão Data de Lançamento: 21/02/2026 Idioma: Português Condição: Novo/Lacrado', 45.9, 45.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-82615-mkusj24xnlza55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F57756267428', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19120295536', 'Dvd Karaoke Aparelho dvd Player Mondial Entrada Usb Ii Mp3 Bivolt D20', 'DVD Player Mondial D-20 com Entrada USB e Função Karaokê Bivolt Acrescente tecnologia e entretenimento em sua casa com o DVD Player D-20 da Mondial. Especialmente desenvolvido para os amantes do cinema, o DVD D-20 reúne o que há de melhor em tecnologia e matéria-prima para suprir a necessidade de seus consumidores mais exigentes. Além disso, possui entrada USB, função Ripping e karaokê, perfeito para divertir e entreter familiares, amigos e convidados! Solte a voz no karaokê, assista a filmes e séries preferidas com a qualidade do DVD Player D-20 da Mondial. Especificações Técnicas: - Função disc copying: copia músicas, fotos ou vídeos de um CD/DVD em formato de dados diretamente para um dispositivo USB - Karaokê: Pontuação, ajuste de volume do eco do microfone, guia vocal e escolha de músicas (Obs: Não acompanha microfone!) - Zoom para imagens estáticas e em movimento - Entrada USB para conexão pen drive - Senha para controle de arquivos censurados - Saída de áudio stereo 2.0 - Saída de vídeo composto - Reproduz: DVD, DVD-r/rw, DVD+r/rw, vCD, svCD, JPEG, mp3 players - Controle remoto para todas as funções do aparelho - Função ripping: extrai músicas de um CD de áudio diretamente para um dispositivo USB - Opções de escolha: linguagem de áudio, linguagem de legenda, ângulo de cenas e imagens, caso essas funções estejam disponíveis no disco a ser reproduzido Dimensões(AxLxP): 26 x 26 x 7 centímetros Peso: 1,060 kilos Conteúdo da embalagem: - 1 DVD Player Mondial D-20 - 1 Controle Remoto - 1 Cabo de Vídeo - 1 Manual Garantia do Fabricante: 12 meses *Imagens meramente ilustrativas. **A Garantia Legal é de 90 dias, conforme CDC - Código de Defesa do Consumidor. A partir do 91 dia, passa a vigorar a Garantia Contratual, que é tratada diretamente pelo FABRICANTE do item e segue as regras estipuladas pelo próprio. A Garantia Total (garantia legal + garantia contratual) é exibida no campo correspondente deste anúncio. Atente-se a responsabilidade de cada parte e lembre-se que estamos sempre a disposição para esclarecimentos em nosso SAC.', 199.9, 199.9, NULL, 'Audio > Media Players > CD, DVD, & Blu-ray Players', 'https://cf.shopee.com.br/file/795f3f06e379df0777c8e267a2f3e7ac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337570318%2F19120295536', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
