INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40602593073', 'A violinista de Auschwitz | Ellie Midwood', 'A violinista de Auschwitz | Ellie Midwood Baseado na história real da violinista austríaca judia, Alma Rosé, respeitada até mesmo pelos guardas da SS e comandantes nazistas, este livro retrata a vida de uma das heroínas mais destemidas, inspiradoras e corajosas da história. Com sua bravura e perspicácia, salvou inúmeras vidas, trazendo esperança para aqueles que haviam esquecido seu significado. Há diferentes relatos sobre o destino de Alma e, não importa qual seja verdadeiro, a vida dessa mulher é extraordinária. Uma escrita que estimula o pensamento e evoca emoções. Título: A violinista de Auschwitz Autor: Ellie Midwood Páginas: 352 Capa: Brochura Dimensões: 14 x 21 cm Editora: Ciranda Cultural', 29.9, 29.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rau5-mad4xjs2wttf99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F40602593073', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40020115556', 'Moedor Elétrico de Carne Saro Bivolt com Botão de Emergência MEC', 'Construção Metálica Resistente, Alto Desempenho e Segurança IntegradaO Moedor de Carne Saro alia robustez, potência e segurança em um único equipamento. Construído com carenagem 100% em metal e revestimento em pintura epóxi anti-risco, oferece resistência superior e longa vida útil, mesmo em uso intenso. Com motor de 1/3 CV, tecnologia RED-Plus e placa integrada, o moedor é capaz de processar até 70 kg de carne por hora com eficiência e baixo desgaste, reduzindo a necessidade de manutenção. Além disso, acompanha funil de alumínio para linguiças e embutidos, bem como disco especial para moldar biscoitos e bolachas em até quatro formatos. A segurança também é destaque: o equipamento possui sistema de emergência que interrompe imediatamente o funcionamento, atendendo às normas da NR12 e certificado pelo Inmetro. Seus quatro pés emborrachados garantem estabilidade e evitam danos à superfície de apoio durante o uso. Resistente, versátil e confiável, o Moedor de Carne Saro é a solução ideal para quem busca desempenho profissional com total segurança. Especificações Técnicas: Marca: Saro Modelo: MEC Voltagem: Bivolt Cor: Branco Nacionalidade: Nacional Aplicação: Moer carnes e alimentos em geral Material: Aço carbono (metal) Capacidade: 70kg/hora Potência: 1/3cv Frequência: 50/60 hz Consumo: 0,24 Kw/h Dimensões do Produto (LxAxP): 29,5 x 30x 24cm Dimensões da Embalagem (LxAxP): 40 x 40 x 35cm Peso líquido: 12Kg Peso Bruto: 9 kg Garantia: 12 meses', 1180.98, 1049.0, NULL, 'Home Appliances > Small Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258m-meu5976qtpfoe4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1059412251%2F40020115556', NULL, 