INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294345328', 'Película Proteção Nanoglass 9h Zontes R310 Y310 R310 R350 2023 2024', 'Película Protetora para Painéis de Moto Garanta a máxima proteção para o painel da sua moto com a Película Protetora KARBOLD 9H NanoGlass. Com a tecnologia de nanotecnologia, ela preserva a integridade e o visual do painel, oferecendo uma proteção premium sem comprometer a visibilidade. Modelos Compatíveis: ZONTES 310V 2023 ZONTES 310V 2024 ZONTES 310V 2025 ZONTES 310R 2023 ZONTES 310R 2024 ZONTES 310R 2025 ZONTES 310T 2023 ZONTES 310T 2024 ZONTES 310T 2025 ZONTES 310V 2023 ZONTES 310V 2024 ZONTES 310V 2025 ZONTES 350R 2023 ZONTES 350R 2024 ZONTES 350R 2025 ZONTES 350T 2023 ZONTES 350T 2024 ZONTES 350T 2025 ZONTES 350V 2023 ZONTES 350V 2024 ZONTES 350V 2025 ZONTES 350GK 2023 ZONTES 350GK 2024 ZONTES 350GK 2025 Características e Benefícios: - Resistência 9H: Superfície ultra-dura contra arranhões; - Sensação Suave ao Toque: Perfeita para o uso diário; - Transparência Ultra Clear 99,9%: Clareza total para você visualizar o painel sem distorções; - Camada Oleofóbica: Reduz marcas de impressões digitais e sujeira; - Proteção Completa. Cobre toda a área sensível ao toque, protegendo contra poeira, calor, raios UV e água. - Auto-cura de Arranhões Leves: Melhora a aparência do painel, reparando arranhões superficiais. - Durabilidade Extrema: Protege sem trincar, arranhar ou quebrar. Inclui Kit Completo de Instalação: 1x Película Protetora KARBOLD 9H Nano 1x Espátula de Aplicação 1x Adesivo Anti-Impurezas 1x Pano de Microfibra e Lenços Umedecidos 1x Manual em Português Preserve o painel da sua moto com proteção máxima e estilo inigualável. Escolha KARBOLD!', 59.9, 59.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg