INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693834736', 'Pelúcia Interativa Stich (Fantoche) com Som - Stitch Wow', 'Descrição: O alien mais fofo da galaxia chegou e esta pronto para se divertir, com a nova e incrivel pelucia do Stitch voce vai ter uma experiencia unica com esse brinquedo maravilhoso, a pelucia do Stitch é feito com um material super fofo e que é feito para ser abraçado, use os sons dele e se divirta com o Stitch! A nova pelucia animada de Stitch é rica em detalhes e totalmente personalizada, parecendo que sair diretamente das telas de filmes para a sua casa! A nova pelucia de Stitch vem com inumeros sons que deixam a sua brincadeira ainda mais real, recrie suas cenas favoritas dos filmes com essa nova pelucia! Desenvolva a criatividade e a imaginação recriando seus momentos favoritos com as novas pelucias interativas do stitch! Esses brinquedos estimulam brincadeiras e a criação de histórias divertidas. Ideal para crianças que amam aventuras! Características: Marca: Sunny Brinquedos Referência: 4421 Idade recomendada: A partir de 2 meses Pilhas Inclusas? Tipo de Pilha/Bateria Não. Requer 3 pilhas AAA (LR03) de 1,5V. Possui Luzes: Não Possui Sons: Sim Dimensões aproximadas da embalagem: 33,5 x 22,5 x 16cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Pelúcia Interativa Certificado Inmetro: REGISTRO 018065/2024 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 899.99, 845.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rd6q-m7gmovk1rkz42a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F22693834736', NULL, NU