INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13685677497', 'Livro Totalmente pela graça - CHARLES SPURGEON', 'Um dos principais escritos do “Príncipe dos pregadores” do século 19, Charles H. Spurgeon. Enfatiza a maravilhosa verdade de que não há moeda de troca que possamos oferecer nem mérito humano na busca e conquista da imerecida salvação. É exclusivamente pela graça de Deus que somos salvos. Ela, sim, é a causa da nossa redenção em Cristo Jesus. CHARLES SPURGEON1834–92Foi um pastor britânico que permanece altamente conceituado no meio cristão, em diferentes denominações, nas quais ainda é conhecido como o “Príncipe dos pregadores”. Capa Dura', 41.9, 41.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/55b4c6d0816fed9fcfe640104dd9b56a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F13685677497', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
