INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211057006', 'Figura de Ação Marvel Serie Titan Deluxe Homem-Aranha Um Novo Dia Hulk 30 cm - Hasbro G2455', 'Este brinquedo do Hulk mede 29,7 cm de altura e apresenta design inspirado em Spider-Man: Brand New Day, parte do Universo Cinematográfico Marvel Esta figura do Hulk possui 11 pontos de articulação, para que as crianças possam posicioná-la em aventuras emocionantes cheias de pancadaria e destruição que imaginarem Os brinquedos Spider-Man da Série Titan apresentam personagens queridos, incluindo o Homem-Aranha e o Hulk Os brinquedos Marvel Série Titan incentivam a brincadeira criativa e imaginativa, permitindo que crianças a partir de 4 anos imaginem suas próprias histórias e batalhas com superpoderes com esta figura Esta figura de ação Marvel Spider-Man vem em uma embalagem colecionável com design inspirado no entretenimento, que fica incrível para exposição Pais e crianças podem procurar mais brinquedos do Homem-Aranha, incluindo figuras de ação para meninos e meninas, para montar uma coleção incrível do lançador de teias Os brinquedos Marvel Spider-Man para meninos e meninas são ótimos presentes para aniversários, feriados e outras ocasiões especiais (Cada um vendido separadamente. Sujeito à disponibilidade.) PRODUTOS E CORES PODEM VARIAR DAQUELES APRESENTADOS NA EMBALAGEM. DEMAIS PRODUTOS MOSTRADOS NA EMBALAGEM SÃO VENDIDOS SEPARADAMENTE(SUJEITO A DISPONIBILIDADE). NÃO RECOMENDÁVEL PARA CRIANÇAS MENORES DE 3 (TRÊS) ANOS POR CONTER PARTES PEQUENAS QUE PODEM SER ENGOLIDAS OU ASPIRADAS. Código Inmetro: 005107/2021 Faixa Etária: 4+ Cores: Verde, Preto, Marrom', 152.99, 152.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/br-11134207-820m2-moh56qk9hfyb30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1761200885%2F58211057006', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43606746657', '30 Dias para Transformar sua vida | Junior Rostirola', '30 Dias para Transformar sua vida | Junior Rostirola Mudar de vida exige dedicação. Para a maior parte das pessoas, é um processo longo e sofrido, mas você pode seguir o direcionamento de quem já percorreu esse trajeto para ter direção, vida e propósito em tempo muito menor. Em 30 dias para transformar a sua vida, você encontrará uma jornada cuidadosamente pensada para levá-lo a um novo patamar, pois você se moverá pela fé, se conectará com Deus e encontrará sua identidade e seu propósito no Pai. Cada estudo foi elaborado com uma aplicação prática que o levará a refletir e colocar em ação o que você precisa para alcançar a cura e liberdade que Jesus conquistou na cruz para você. Aprenda com Junior Rostirola, o garoto tímido, inseguro e solitário que se tornou um pregador da Palavra, autor de um dos livros mais vendidos do Brasil e homem curado que leva o cuidado e o amor de Deus Pai por seu país e ao redor do mundo. Título: 30 Dias para Transformar sua vida Autor: Junior Rostirola Páginas: 224 Capa: Brochura Dimensões: 16 x 23 cm Editora: Velos', 60.9, 60.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meemwssp3nr666', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F43606746657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20539086274', 'Fita Anti furo Proteção Para Bicicletas Bike Mtb Speed Tectire Aro 29 26 35mm x 2,3 Metros', 'FITA ANTI FURO BICICLETA MTB ARO 26 29 TECTIRE 35MM X 2,3 METROS Fita desenvolvida para evitar furos de pregos, cacos de vidro e outros objetos cortantes no pneu. Produzida com materiais de alta qualidade, combinados numa fita com espessura de 2mm e com acabamento chanfrado a Tectire proporciona uma proteção para o pneu e uma melhor performance durante as pedaladas. Não é tóxica e pode ser reutilizada nas trocas de pneus se instalada corretamente. - ESPECIFICAÇÕES TÉCNICAS: Marca: Tectire Medida: 35mm x 2.3 metros Compatível com pneus: 20 x 2.10 20 x 2.125 20 x 2.25 20 x 2.30 20 x 4.00 24 x 2.10 24 x 2.125 24 x 3.00 26 x 1-1/2 x 2 26 x 2.10 26 x 2.125 26 x 2.135 26 x 2.20 26 x 2.30 26 x 2.35 27.5 - Todos 29 x 1.95 29 x 2.00 29 x 2.10 29 x 2.20 29 x 2.25 29 x 2.30 29 x 2.40 700 x 38c 700 x 42 700 x 45 700 x 48c NÃO ACEITAMOS DEVOLUÇÕES DE PRODUTOS QUE JÁ FORAM MONTADOS E/OU USADOS. -De extrema importância que o produto seja instalado por um mecânico profissional – EVITAR ADAPTAÇÕES. -Todas as garantias são dadas pelos fabricantes, e variam de produto para produto. Caso tenha alguma dúvida, entre em contato conosco. -Para devoluções, os produtos deverão ser remetidos em suas embalagens originais. -Certifique-se de preencher corretamente seus dados pessoais e endereço para que não haja problemas com o pedido. -Produto Novo -Enviamos para todo o Brasil. -Imagem meramente ilustrativa -Tire todas as dúvidas antes da compra. Evite transtornos!', 25.0, 25.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-82606-mldmxybx9l3407', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2