INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698896410', 'Engate Cinto De Segurança Traseiro Gol Palio Uno Corsa Celta', 'Cinto de Segurança Fêmea 50cm Reposição Universal Foto meramente Ilustrativa (Pode sofrer Variações de Tonalidade Dependendo do Lote). Produto Segue em embalagem Unitária. Características Material: Poliéster. Obs. Poderá escolher a cor em “Opções de cores”. Preto, Cinza, Vermelho, Bege, Marrom, Verde, Azul, Amarelo. Montado com marcas consolidadas no mercado por sua qualidade e segurança. Especificações Técnicas Aplicação: Universal (Adaptação) Sugerida utilização em carros populares Nacionais. Medida: 50cm Garantia 06 Meses Excluído da Garantia: Danos causados por mau uso tais como queda, umidade, violação e reparos indevidos resultando em dano no equipamento. Garantia do vendedor: 6 meses. Benefícios do uso do cinto de segurança: Reduz o risco de ferimentos graves em acidentes de trânsito. Mantém o corpo estabilizado, evitando o impacto contra o volante ou painel. Garante segurança e conforto durante a condução. Atende às normas de segurança veicular exigidas por lei. Evita multas e pontuação na CNH por uso incorreto. Indicado para todos os veículos: carros, caminhonetes e utilitários. Fácil instalação e reposição, ideal para manutenção preventiva. Custo-benefício alto, sendo essencial para a segurança automotiva. Recomendações: - Instalar com apoio de profissional qualificado. - Garantia de 6 meses.', 24.75, 24.75, NULL, 'Fashion Accessories > Additional Accessories > Cufflinks', 'https://cf.shopee.com.br/file/sg-11134201-824hi-mekxr3yde8li1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1604698269%2F23698896410', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
