INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394090487', 'Garrafa de tinta Epson 504, 70 ml, Ciano, T504220-AL - 0071912-01', 'GARANTA A SEGURANÇA DA SUA IMPRESSORA As tintas originais Epson foram desenvolvidas especialmente para uso na sua EcoTank, seguindo altíssimos padrões de qualidade internacionais, e evitam quaisquer danos ao seu equipamento. ALTA QUALIDADE DE IMPRESSÃO Somente as tintas originais garantem impressões consistentes, com a qualidade e durabilidade que você merece! APROVEITE TODA PERFORMANCE EPSON Além de garantirem confiabilidade na impressão, as tintas originais permitem que sua impressora trabalhe com performance máxima. SISTEMA DE ABASTECIMENTO SUPER PRÁTICO Com o sistema EcoFit, você encaixa a garrafa e evita sujeira ou desperdício. CARACTERÍSTICAS - Marca: EPSON - Modelo: T504220-AL - 0071912-01 ESPECIFICAÇÕES COMPATIBILIDADE - L4150 / L4160 / L4260 / L6171 / L6161 / L6191; COR DO CARTUCHO - Ciano; MEDIDAS (A x L x C) - 17 x 6 x 6 cm; - 70ml; RENDIMENTO - aproximadamente 6.000 páginas; CONTEÚDO DA EMBALAGEM - 1x Garrafa de tinta Epson 504, Ciano, T504220-AL - 0071912-01.', 89.9, 89.9, NULL, 'Computers & Accessories > Printers & Scanners > Inks & Toners', 'https://cf.shopee.com.br/file/sg-11134201-7rdyg-mdf3r9gjzuvtcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778397589%2F22394090487', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
