INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894088578', 'Filtro de Cabine Wega para Chevrolet Onix 1.0 12V ECOTEC 2020 até 2023 - Cod. AKX35725', 'Alta eficiência na filtragem; Remoção de impurezas e odores; Fácil instalação; Melhora a qualidade do ar dentro do veículo; Previne doenças respiratórias e alergias; Somos a Dispemec! Nossa trajetória começou em 1988. De lá para cá trabalhamos muito para evoluir e buscar excelência nos nossos serviços. Nosso segredo sempre foi cuidar de cada detalhe com muita dedicação e flexibilidade, pois é isso o que esperam os nossos parceiros e clientes com os quais compartilhamos os mesmos valores. Os desafios que superamos para acompanhar as mudanças do mercado automotivo sempre foram grandes, mas seguimos firmes, buscando soluções inovadoras para oferecer um atendimento ágil e prestativo. Se alguém solicita uma peça, seja no balcão ou na loja online, ela está sempre à mão. Nosso estoque conta com mais de 20.000 peças e acessórios, com qualidade e garantia asseguradas. Além de tudo, nossa equipe está sempre pronta para primeiro avaliar a causa e os danos no veículo, e aí, sim, sugerir as peças realmente necessárias e adequadas. Este tipo de cuidado você encontra aqui, na Dispemec. Um atendimento desses só é possível graças ao Programa de Capacitação Continuada da Dispemec, que prepara nossos especialistas com o que há de mais moderno no mercado. Isso significa ir além de “cumprir pedidos”, é prestar uma verdadeira consultoria. Há mais de 36 anos é assim, e sempre será. Para conquistar o reconhecimento dos maiores peritos no assunto. É isso o que torna a Dispemec uma das melhores autopeças do Brasil. ITENS INCLUSOS: 1 filtro de cabine; DESCRIÇÃO: O filtro de cabine é um item indispensável para manter a qualidade do ar dentro do veículo. O filtro de cabine Wega AKX35725 é uma excelente opção para quem busca mais eficiência na filtragem de ar. Fabricado com materiais de alta qualidade, o filtro de cabine Wega AKX35725 garante a remoção de impurezas e odores do ar que circula dentro do veículo. . Com o filtro de cabine Wega AKX35725, o motorista e os passageiros do veículo terão uma experiência mais agradável e saudável. VEÍCULOS COMPATÍVEIS: Chevrolet: • Onix 2020 1.0 12V ECOTEC • Onix 2021 1.0 12V ECOTEC • Onix 2022 1.0 12V ECOTEC • Onix 2023 1.0 12V ECOTEC DADOS TÉCNICOS: similar la1890; GARANTIA: 3 meses Somos a Dispemec! A mais confiável loja de Autopeças que continua atendendo com excelência desde 1988. Dispemec, quem conhece, confia e compra.', 38.9, 38.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7raux-maskmvpz7shv99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819107232%2F22894088578', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794068284', 'Pomada Massageadora Fisiofort Premium 150gr', 'Pomada Massageadora Fisiofort Premium 150grA pomada massageadora Fisiofort Premium 150g, da marca Bio Instinto, é um produto cosmético desenvolvido para auxiliar no alívio de dores musculares, articulares e na recuperação pós-treino. Sua fórmula é rica em ingredientes naturais como arnica, mentol e cânfora, que proporcionam sensação de frescor e relaxamento na pele, auxiliando no alívio de tensões e desconforto.', 18.99, 16.81, NULL, 'Health > Medical Supplies > First Aid Supplies', 'https://cf.shopee.com.br/file/sg-11134201-7raub-mak9wrb200zn28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F22794068284', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497984678', 'Hidratante De Couro Hidracouro Vonixx 500ml', 'O Hidracouro Vonixx é um produto que hidrata e protege bancos de couro. Sua fórmula à base de lanolina evita o ressecamento do couro, mantendo-o com aspecto de novo. DILUIÇÃO Pronto uso. INFORMAÇÕES ADICIONAIS Antes de aplicar Hidracouro, recomendamos a limpeza prévia com Higicouro ou Sintra. RENOVA E PROMOVE BRILHO; AGE CONTRA O RESSECAMENTO; Devolve a Maciez do Couro; MODO DE USAR 1. Limpar a superfície com Higicouro ou Sintra; 2. Aplicar o produto com um aplicador de espuma até a completa hidratação; 3. Se necessário, repetir a operação.', 47.41, 47.41, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1zh94l7dl2c3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F843124271%2F18497984678', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53952195223', '[MINI] LANEIGE Creme Névoa Para Pele 30ml', '⭐ Características dos recursos Névoa Ultra-hidratante formulada com tecnologia Creme Blending™, combinando a riqueza de um creme com a leveza de uma névoa Fornece hidratação profunda instantaneamente, deixando a pele macia, úmida e flexível Ajuda a fortalecer a barreira da pele com água do chá de folha branca, rica em aminoácidos Partículas de névoa finas oferecem umidade duradoura sem peso Ideal para peles secas ou para reidratar durante todo o dia Pode ser usado antes ou depois da maquiagem, sem incomodar o acabamento Tamanho 30ml amigável para viagem perfeito para hidratação em movimento ⭐ Modo de usar Segure a garrafa a cerca de 20–30 cm de distância do rosto. Feche os olhos e pulverize uniformemente em todo o rosto. Feche os olhos e pulverize uniformemente em todo o rosto. Passe suavemente para melhor absorção se desejar. Use a qualquer hora que sua pele se sentir seca - antes da maquiagem, após a maquiagem ou ao longo do dia.', 66.3, 63.0, NULL, 'Beauty > Skincare > Facial Mist', 'https://cf.shopee.com.br/file/sg-11134207-8225y-mhju5y05hj4240', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F53952195223', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18076345167', 'SOME BY MI AHA BHA PHA 30 Dias Espuma Transparente Para Acne Milagrosa 100ml', 'Descrição do produto em inglês após português O MI: ALGUNS POR MI: ALGUMAS POR MI: ALGUMAS POR MI são uma palavra composta de''ALGUMAS'' e''POR UM MIRÁCULO''. A nossa missão de marca é fazer produtos que se mantenham aos itens essenciais de cosméticos, com ingredientes seguros e limpos com eficácia comprovada. Através de nossos produtos de Skincare, esperamos trazer algumas mudanças positivas e''MIRACLES'' para através de nossos produtos de Skincare, esperamos trazer algumas mudanças positivas e''MIRACLES'' para a sua pele - Espuma MIRACLE CLEAR: Este limpador facial combinado ingrediente TruecicaTM com concentração de 160.200 ppm e projetado para acalmar a pele propensa a acne e proteger contra irritantes externos ou substâncias nocivas. O uso de ativadores de superfície natural Quando usado para limpeza, a irritação da pele é reduzida através do uso de ativadores de superfícies naturais para uma experiência suave do usuário. A espuma facial é livre de 20 ingredientes artificiais e foi testada dermatologicamente para quem tem pele sensível Aha esfolia a superfície da pele e pode ajudar a reduzir a aparência de linhas finas, rugas e melhorar a textura e o tom da pele. O BHA esfolia o interior dos poros, ajuda a limpar as impurezas e o excesso de sebo. O PHA é um esfoliante suave que ajuda a hidratar a pele, reduz a aparência de linhas finas e melhora a esfoliação suave que ajuda a hidratar a pele, iluminar a pele, reduzir a aparência de linhas finas e melhorar a textura geral da pele Linha MIRACLE: As linhas MIRACLE são adequadas para peles com tendência a acne, contendo altas quantidades de folha de Tea Tree para melhorar a pele. Esta linha tem de forma ideal mista AHA, BHA, PHA para refinar células e impurezas mortas da pele, e Truecica, um agente calmante exclusivo, que mantém uma pele com aparência saudável e evita que o surto de acne através de cuidados com o equilíbrio do pH. Teste de irritação de 20 ingredientes nocivos Livre de 20 ingredientes nocivos e passou no teste de irritação para peles sensíveis - Algumas POR NÓS: Fazemos produtos comprovada eficácia apenas passando por rigorosos testes a partir dos estágios de planejamento e desenvolvimento para lançamento de produtos, em colaboração com vários especialistas em dermatologia. Se você tiver alguma dúvida sobre nossos produtos, não hesite em entrar em contato conosco. O primeiro golpe de prioridade'' de ALGUMAS POR MI ************************************************** - SOME BY MI : SOME BY MI is a compound word of ‘SOMETHING’ and ‘BY A MIRACLE’. Our brand mission is to make products that stick to the essentials of cosmetics, with safe and clean ingredients with proven efficacy. Through our Skincare products, we hope to bring some positive changes and ‘MIRACLES’ to your skin - MIRACLE CLEAR FOAM : This facial cleanser combined TruecicaTM ingredient with a concentration of 160,200 ppm and designed to soothe acne-prone skin and protect against external irritants or harmful substances. When used for cleansing, skin irritation is reduced through the use of natural surface activators for a gentle user experience. The facial foam is free of 20 artificial ingredients and has been dermatologically tested for those with sensitive skin - KEY INGREDIENTS : AHA exfoliates the surface of the skin and can help to reduce the appearance of fine lines, wrinkles and improve the skin texture and tone. BHA exfoliates the inside of the pores, help to clear out impurities and excess sebum. PHA is a gentle exfoliator which help to hydrate the skin, brighten the skin, reduce the appearance of fine lines, and improve the overall texture of the skin - MIRACLE LINE : MIRACLE Lines are suitable for acne-prone skin, containing high amounts of Tea Tree Leaf to improve the skin. This line has optimally mixed AHA, BHA, PHA to refine dead skin cells and impurities, and Truecica, an exclusive calming agent, that maintains healthy-looking skin and prevents acne-breakout through pH balance care. Free of 20 harmful ingredients and passed irritation test for sensitive skin - SOME BY US : We make products with proven efficacy only by undergoing strict testing from the planning & developing stages to product launch, in collaboration with various dermatology experts. If you have any questions about our products, please do not hesitate to contact us. Your satisfaction is the ‘First Priority Goal’ of SOME BY MI', 74.71, 71.0, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134207-7rdyb-lzsski077p0a9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F18076345167', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24876015444', 'SKINFOOD Royal Honey Propolis Enrich Essence 50ml Product/Refill', 'Hydrating Toner for Face - SKINFOOD Royal Honey Essential Toner is great for reducing acne and dark spots. This hydrating facial toner creates a protective barrier for long lasting moisture and a honey kissed complexion. Benefits of Black Bee Propolis Extract - Black Bee Honey is considered a rare delicacy with medicinal properties in both Eastern & Western Medicine since ancient times. It''s a beauty remedy with anti-aging, moisturizing, and revitalizing properties. Combined with Royal Jelly Extract, this toner builds a firm barrier for radiant and moist skin. Honey Propolis Essence Toner - An amazing dark spot diminisher, this hydrating facial toner is the best skin toner for providing a rich nutrient cleaning experience for dry and rough skin. Leave your skin glowing and smooth as you go about your day! How to Use - After using a gentle exfoliating cleanser on your face and neck, apply the toner to your skin using a cotton pad or your palms. Gently pat your skin until the toner is completely absorbed. For best results, use daily with a SKINFOOD cleanser, followed by a SKINFOOD facial lotion. Authentic Korean Beauty Products - Korean Beauty products like SKINFOOD lead the world with their top-tier beauty and makeup products. We are the first cosmetic brand to root itself in food since 1957, as we believe that the highest quality nutritive food results in healthy, beautiful skin to create a healthier lifestyle.', 94.8, 91.0, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/sg-11134207-7rd5f-lwzfo2s81akq5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F24876015444', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
