INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299232122', 'Jogo 4 Pratos Rasos Prisma Brancos 28 cm Porcelana Schmidt', 'Jogo 4 Pratos Rasos Prisma Brancos 28 cm Porcelana Schmidt Beleza e requinte em sua mesa! Leve à sua mesa toda a beleza e qualidade das porcelanas Schmidt. Peças com maior resistência ao impacto e a variação brusca de temperatura sem perder o alto brillho e a conservação do calor do alimento. Ideal para uma ocasião especial ou mesmo para uso diário. Excelente para dar de presente para aquela pessoa especial ou decorar o ambiente, com charme e elegância. Descrição do produto: Marca: Porcelana Schmidt Decoração: Prisma Conteúdo: 4x Prato Raso Prisma Peças podem ser usadas no refrigerador, micro-ondas e lava-louças. Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 121.17, 121.17, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zuf-miivl58o8s1ya1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F23299232122', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
