INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194166994', 'Tesoura de podar plantas e galhos de jardim tesourão', 'Fotos e vídeos originais. Pronta entrega. Enviamos em até 24 horas úteis. Tesoura para cortar galhos Bestfer: a melhor opção para realizar podas com segurança e rapidez. Esta é uma ferramenta indicada para efetuar cortes em galhos mais grossos ou de difícil alcance, seja por estarem altos demais ou cercados por outros galhos. A tesoura Bestfer combina conforto com eficiência e robustez. Seu cabo alongado permite maior alcance e as lâminas afiadas possibilitam um corte rápido e com pouco esforço. Na ponta dos cabos há um revestimento antiderrapante para evitar acidentes durante o uso. Também há dois orifício para facilitar o armazenamento, inclusive em painéis de ferramentas. Ela é apropriada para uso em jardins, canteiros, podas, retirada de frutos e atividades afins. Se você procura uma ferramenta de qualidade e acessível para seus serviços de jardinagem, chegou no anúncio certo. Aproveite nossa oferta e ganhe agilidade e profissionalismo com esta tesoura. Atuando há mais de 10 anos no mercado, a LB Materiais oferece tudo o que você precisa para realizar seu sonho de construção e reforma! Em caso de dúvidas, fale conosco deixando a sua pergunta no campo de "Perguntas e Respostas", estamos à disposição para melhor atendê-los. Boas Compras Equipe LB Materiais.', 89.9, 59.7, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/br-11134201-7r98o-mcusbbw3ebea81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F705932885%2F22194166994', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
