INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27086765594', 'Grass Fed Balance Collagen Protein® 28g Proteína | Colágeno Pepcol®| Chocolate Avelã | 560g Bigens', 'Grass Fed Balance Collagen Protein® Chocolate com Avelã 🍫🌰 | 28g de Proteína por Porção | Colágeno Premium Pepcol® | 560g - Bigens Sua rotina merece mais do que um suplemento. Merece um colágeno puro, potente e com sabor de verdade! 💪✨ O Grass Fed Balance Collagen Protein® Chocolate com Avelã, da Bigens, oferece até 28g de proteína por porção, proveniente de gado 100% criado a pasto, sem hormônios, antibióticos ou rações artificiais. 🌱🐄 💥 Destaques que fazem a diferença: ✔️ Colágeno hidrolisado Premium com tecnologia patenteada Pepcol® ✔️ Perfil completo de aminoácidos, incluindo BCAAs naturais ✔️ Sabor cremoso e marcante de chocolate com avelã 🍫🌰 ✔️ Ideal para suporte à pele, músculos e articulações 🔎 Fórmula limpa, consciente e versátil: 🚫 Zero lactose 🚫 Zero caseína 🚫 Sem glúten 🚫 Sem adição de açúcares ✅ Alta concentração de proteína (até 28g por dose) 📏 Rendimento inteligente: 1 scoop (15g) = 14g de proteína 2 scoops (30g) = 28g de proteína Perfeito para quem busca um reforço proteico prático, saudável e agora com um sabor indulgente. 💖', 159.9, 159.9, NULL, 'Health > Food Supplement > Beauty Supplements', 'https://cf.shopee.com.br/file/sg-11134201-7rfgn-m9zws6bekt615a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1059419518%2F27086765594', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6192836619', 'Livro - Rilla de Ingleside - Capa comum - Ciranda Cultural', 'Rilla está chegando aos quinze anos e o seu primeiro baile no farol de Four Winds se aproxima trazendo também a expectativa por um romance com Kenneth Ford. Porém, os desafios que aguardam a filha caçula de Anne podem ser maiores que o anseio por um primeiro beijo, com a eminência de uma guerra que ameaça a família Blythe. Anne e Gilbert se preocupam com os seus filhos e com a ingenuidade da pequena Rilla, que terá sua coragem e amadurecimento testados por episódios que a mudarão para sempre. Editora: Ciranda Cultural Edição: 1, 2020 Autor: Lucy Maud Montgomery Idioma: Português Páginas: 320 Dimensões: L 16.00 x A 23.00 x E 1.50 ISBN: 9786555002973', 34.9, 34.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/0ddb0087c5ac8620d234a90787776075', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F6192836619', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19998942351', 'Mental Focus, Fosfatidilserina, Tirosina, Taurina, Caféina, Magnésio Glicina Bigens, 60cps', 'Biogens agora é Bigens! MENTAL FOCUS 60 CÁPSULAS Mental Focus Bigens é um suplemento formulado especialmente com substâncias que, apesar de potencializar o desempenho cognitivo, não são tóxicas ou viciantes. Praticantes de exercício físico possuem suplementos para o upgrade físico bem como praticantes de atividades mentais também podem se favorecer com suplementos para um upgrade mental. Mental Focus Biogens pode ser considerado um nootrópico, já que possui em sua composição nutrientes essenciais e biodisponíveis além de um composto ativo estimulante que colabora para um estado de alerta e atenção. Sua fórmula carrega doses eficientes de fosfatidilserina, cafeína, zinco quelato, colina, taurina, tirosina, ácido fólico, vitaminas C, E e do complexo B. INGREDIENTES: Bisglicinato de magnésio, tirosina, ácido ascórbico, niacina (nicotinamida), acetato de D-alfa-tocoferol (vitamina E), cloridrato piridoxina (vitamina B6), metilcobalamina (vitamina B12), sulfato de zinco, bitartarato de colina, taurina, fosfatidil serina, cafeína, ácido fólico. INGREDIENTES DA CÁPSULA: Gelatina, corante inorgânico clorofila, opacificante INS 171 e umectante água potável filtrada. NÃO CONTÉM GLÚTEN. SUGESTÃO DE USO: Adultos 19 anos, Ingerir 2 cápsulas ao dia após o café da manhã, ou conforme a orientação de médico ou nutricionista. Conservar este produto bem fechado, em lugar fresco, seco e ao abrigo da luz. Após aberto consumir em até 90 dias. Suplemento Alimentar dispensado de registro conforme Resolução RDC nº 240/2018. A BIOGENS AGORA É BIGENS! UM NOVO NOME, A MESMA QUALIDADE!', 49.3, 49.3, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m82